INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C1','kor',3,2,'u4',2,'높임 표현과 대화 예절 — 이 단원의 두 가지로, 같은 부탁이라도 말을 건네는 상대·상황이 달라지면 쓰는 말이 달라지며, 둘 다 상대를 존중하는 일임',ARRAY['[4국01-04][4국04-04]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C2','kor',3,2,'u4',2,'높임 표현의 뜻 — 말하는 사람이 어떤 대상을 높이려고 쓰는 표현이고, 그 안에 상대를 존중하는 마음이 담김(말을 길게 늘이거나 어려운 낱말을 쓰는 방법이 아님)',ARRAY['[4국04-04]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C3','kor',3,2,'u4',2,'높임 표현을 쓰는 상황 — 웃어른께 말씀드릴 때뿐 아니라 학급 회의처럼 여러 사람 앞에서·처음 만난 사이에서도 쓰고, 어른이 더 어린 사람에게 쓰기도 함; 나이만이 아니라 어떤 곳에서·어떤 사이로·어떤 마음을 나타내려는지를 함께 살핌(높임 표현은 나이표가 아님)',ARRAY['[4국04-04]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C4','kor',3,2,'u4',3,'‘-시-’로 높이기 — 움직임을 나타내는 말 안에 ‘-시-’를 넣으면 그 움직임을 하는 사람을 높임(오다 → 오시다, 읽다 → 읽으시다)',ARRAY['[4국04-04]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C5','kor',3,2,'u4',3,'‘께’와 ‘께서’로 높이기 — ‘이/가’ 대신 ‘께서’, ‘에게’ 대신 ‘께’를 써서 높임',ARRAY['[4국04-04]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C6','kor',3,2,'u4',3,'높임의 뜻이 있는 낱말 — 낱말 자체에 높임의 뜻이 담긴 것(집-댁 · 나이-연세 · 이름-성함 · 있다-계시다 · 자다-주무시다 · 사람-분 · 아프다-편찮으시다 · 묻다-여쭈어보다 · 보다-뵙다)',ARRAY['[4국04-04]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C7','kor',3,2,'u4',3,'‘-습니다’와 ‘요’로 듣는 사람 높이기 — 말끝에 ‘-습니다’나 ‘요’를 붙이면 그 말을 듣는 사람을 높임(앞의 셋은 말 속의 사람을 높임)',ARRAY['[4국04-04]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C8','kor',3,2,'u4',3,'높임은 사람에게 — 높이는 대상은 사람이고 물건이나 일에는 높임말을 쓰지 않으며, ‘-시-’를 말끝마다 붙인다고 더 바른 말이 되지도, 어렵다고 아예 쓰지 않아도 되는 것도 아님',ARRAY['[4국04-04]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C9','kor',3,2,'u4',3,'잘못 쓴 높임 표현 바로잡기 — 누구를 높여야 하는지(말 속의 사람·듣는 사람)를 먼저 찾아, 물건이나 나를 높인 곳·높여야 할 분을 높이지 않은 곳을 바르게 고침',ARRAY['[4국04-04]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C10','kor',3,2,'u4',5,'서툴러도 말을 건네는 마음 — 「서툰 인사」의 민결이처럼 틀릴까 봐 말을 건네지 않는 것보다, 조금 서툴러도 말을 건네는 것이 상대를 살피는 일임(부끄러움이 아니라 알아차림)',ARRAY['[4국04-04][4국01-04]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C11','kor',3,2,'u4',5,'말을 옮길 때의 높임 — 웃어른의 말씀을 다른 사람에게 옮길 때에도 높여야 할 분은 그대로 높임(“선생님께서 너 오라고 하셔.”); 말을 옮겨 받는 친구를 높이지는 않음',ARRAY['[4국04-04][4국01-04]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C12','kor',3,2,'u4',5,'낱말 사이의 관계 — 한 낱말이 다른 낱말의 뜻을 포함하는 관계(신발-운동화), 서로 뜻이 반대인 관계(묻다-대답하다), 서로 뜻이 비슷한 관계(돕다-거들다)',ARRAY['[4국04-01]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C13','kor',3,2,'u4',7,'대화 예절의 뜻 — 말하는 사람과 듣는 사람이 말을 주고받을 때 지키는 것으로, 가장 먼저 상대를 배려하고 존중하려는 마음이 필요하며 그 마음은 말투·표정·듣는 태도에도 드러남(부탁을 다 들어주는 것이 아님)',ARRAY['[4국01-04][4국04-05]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C14','kor',3,2,'u4',7,'부르는 말·부탁하는 말·말하는 태도 — 같은 부탁도 상대를 부르는 말, 시키지 않고 묻는 부탁하는 말, 상대를 보며 말하는 태도에 따라 대답이 달라짐(예절은 내용이 아니라 이 세 가지에 드러남)',ARRAY['[4국01-04][4국04-05]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C15','kor',3,2,'u4',7,'거절할 때의 대화 예절 — 부탁을 들어줄 수 없을 때 거절하는 것은 잘못이 아니며, 미안한 마음과 도와줄 수 없는 까닭(할 수 있는 만큼)을 함께 말함; 웃어른의 부탁이어도 거짓으로 하겠다고 하지 않음',ARRAY['[4국01-04][4국04-05]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C16','kor',3,2,'u4',8,'상황을 이루는 것 — 대화 상대(누구와)·시간과 장소(언제 어디에서)·목적과 방식(무엇을 하려고 어떻게)이 달라지면 알맞은 예절도 달라짐(운동장과 도서관의 목소리)',ARRAY['[4국01-04]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C17','kor',3,2,'u4',8,'상황에 알맞은 대화 예절 — 웃어른이 물으실 때는 말끝뿐 아니라 자세와 대답하는 태도로, 모둠 활동에서는 함께 정하는 것과 이어지는 말로, 여럿이 함께 있을 때는 한 사람을 빼는 귓속말 없이 말함',ARRAY['[4국01-04]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C18','kor',3,2,'u4',8,'전화 예절 — 얼굴이 보이지 않으니 내가 누구인지 밝히고 상대를 확인하며, 지금 통화해도 되는지 묻고, 끊기 전에 끝인사를 함(받을 때까지 다시 걸기·바로 끊기·받자마자 내 말부터 하기는 알맞지 않음)',ARRAY['[4국01-04]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C19','kor',3,2,'u4',8,'모둠 대화에서 지킬 것 — 모둠 대화는 이기려는 것이 아니라 함께 답을 찾는 것이라 다른 사람의 말을 끝까지 듣고 내 생각도 말함(밀고 가기도, 아무 말 안 하기도 모둠 대화가 아님)',ARRAY['[4국01-04]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C20','kor',3,2,'u4',10,'상황을 살피고 대화하기 — 대화 상대·목적·방식을 먼저 살펴 대본에 들어갈 말(전화라면 누구인지 밝히기·통화해도 되는지 묻기·끝인사)을 정하고, 높임 표현과 대화 예절을 한 대화 안에서 함께 씀',ARRAY['[4국01-04][4국04-04]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C21','kor',3,2,'u4',10,'표정·몸짓·말투 — 같은 말이라도 표정·몸짓·말투에 따라 듣는 사람의 마음이 달라지고, 상대를 바라보기·고개 끄덕이기·하던 일 멈추기도 듣고 있다는 말이 되며, 전화에서는 “응.”·“그렇구나.” 같은 짧은 말이 그것을 대신함',ARRAY['[4국01-04][4국04-04]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C22','kor',3,2,'u4',10,'점검하고 되돌아보기 — 점검표·되돌아보기 표는 칸을 채우거나 점수를 고치려는 것이 아니라 다음에 고칠 점을 찾으려고 보는 것',ARRAY['[4국01-04][4국04-04]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C23','kor',3,2,'u4',12,'지킬 수 있는 다짐 쓰기 — 다짐 카드에는 언제·무엇을 할지 드러나게 한 가지만 적어야 실천할 수 있고(막연한 다짐·여러 개는 지키기 어려움), 어떤 예절을 고를지는 사람마다 다름',ARRAY['[4국04-04][4국01-04]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C24','kor',3,2,'u4',12,'실천 활동을 고르는 기준 — 우리 반에서 할 활동은 가장 재미있어 보이거나 빨리 끝나는 것이 아니라 이 단원에서 배운 것을 실제로 써 보는 것으로 고름',ARRAY['[4국04-04][4국01-04]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C25','kor',3,2,'u4',12,'방언 — 어느 한 지역에서만 쓰는, 표준어가 아닌 말로 같은 것을 지역마다 다르게 부르는 것이며 틀린 말이 아님; 실제 예는 지어내지 않고 둘레 어른께 여쭈어 알아봄(기초 다지기)',ARRAY['[4국04-04][4국01-04]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C26','kor',3,2,'u4',12,'모음자 ㅐ·ㅔ·ㅒ·ㅖ 바르게 쓰기 — ㅐ와 ㅔ는 가로획의 자리가 다르고, ㅒ와 ㅖ는 짧은 획이 두 개임(새해·세배·얘들아·계절, 기초 다지기)',ARRAY['[4국04-04][4국01-04]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X01','kor',3,'u4',ARRAY['K3-2-u4-C1','K3-2-u4-C3']::text[],'같은 부탁인데 말이 달라진 까닭을 물건·시간처럼 말의 내용에서 찾고, 말을 건네는 상대와 곳이 달라졌다는 것을 놓친다','무엇이 그대로이고 누가 바뀌었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X02','kor',3,'u4',ARRAY['K3-2-u4-C3']::text[],'높임 표현을 나보다 나이가 많은 사람에게만 쓰는 말(나이표)로 여겨, 학급 회의·처음 만난 사이·어른이 더 어린 사람에게 쓰는 높임을 틀렸다고 여긴다','어떤 곳에서, 어떤 사이로?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X03','kor',3,'u4',ARRAY['K3-2-u4-C3']::text[],'한 번 높인 친구나 친구 사이에도 언제 어디서나 높임 표현을 써야 한다고 여긴다','쉬는 시간 짝과 학급 회의는 같은 곳일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X04','kor',3,'u4',ARRAY['K3-2-u4-C2']::text[],'높임 표현을 말을 길게 늘이거나 어려운 낱말을 많이 쓰는 방법으로 여긴다','높임 표현에 담긴 것은 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X05','kor',3,'u4',ARRAY['K3-2-u4-C4']::text[],'‘-시-’가 높이는 사람을 말하는 나나 장소로 여겨, 그 움직임을 하는 사람을 높인다는 것을 놓친다','그 일을 하는 사람이 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X06','kor',3,'u4',ARRAY['K3-2-u4-C5','K3-2-u4-C9']::text[],'높여야 할 분에게 ‘께’·‘께서’ 대신 ‘에게’·‘이/가’를 그대로 쓰거나, ‘께’와 ‘께서’를 엇갈려 쓴다','‘이/가’ 자리엔 께서, ‘에게’ 자리엔 께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X07','kor',3,'u4',ARRAY['K3-2-u4-C6']::text[],'높임의 뜻이 있는 낱말의 짝(나이-연세·이름-성함·있다-계시다·자다-주무시다·사람-분·아프다-편찮으시다·묻다-여쭈어보다·보다-뵙다)을 엇갈리게 잇는다','뜻은 같고 웃어른께 쓰는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X08','kor',3,'u4',ARRAY['K3-2-u4-C7','K3-2-u4-C9']::text[],'말끝의 ‘-습니다’·‘요’가 그 말을 듣는 사람을 높인다는 것을 모르고, 말 속의 사람을 높이는 방법과 듣는 사람을 높이는 방법을 섞는다','말을 듣는 사람은 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X09','kor',3,'u4',ARRAY['K3-2-u4-C8']::text[],'높임말은 많이 붙일수록 공손하다고 여겨 물건이나 일(우산·칠판·공책·숙제)에도 ‘-시-’나 ‘계시다’를 쓴다','높이는 것은 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X10','kor',3,'u4',ARRAY['K3-2-u4-C8','K3-2-u4-C9']::text[],'높임 표현이 어렵다며 아예 쓰지 않거나, 웃어른이 듣는 말인데도 말끝을 낮춘다','높일 사람만 찾으면 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X11','kor',3,'u4',ARRAY['K3-2-u4-C9']::text[],'높이지 않아야 할 사람(말하는 나·친구·동생)에게 ‘-시-’나 ‘계시다’를 써서 높인다','그 일을 하는 사람이 나라면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X12','kor',3,'u4',ARRAY['K3-2-u4-C10']::text[],'높임말이 헷갈리거나 틀릴 것 같으면 말을 건네지 않는 것이 낫다고 여긴다','말을 건네지 않으면 상대는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X13','kor',3,'u4',ARRAY['K3-2-u4-C10']::text[],'한 글자도 틀리지 않아야 인사를 할 수 있다고 여기거나, 서툰 인사를 부끄러운 일로만 여긴다','어른은 무엇이 고맙다고 하셨지?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X14','kor',3,'u4',ARRAY['K3-2-u4-C11']::text[],'웃어른의 말씀을 옮길 때 높여야 할 분을 빼 버리거나(“선생님이 너 오래”), 말을 옮겨 받는 친구 쪽을 높인다(“오시래”)','그 말씀을 처음 하신 분은 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X15','kor',3,'u4',ARRAY['K3-2-u4-C12']::text[],'포함하는 관계·반대인 관계·비슷한 관계를 엇갈리게 안다','한 가지인가, 반대인가, 비슷한가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X16','kor',3,'u4',ARRAY['K3-2-u4-C13','K3-2-u4-C15']::text[],'대화 예절을 남의 부탁을 모두 들어주는 것·시키는 대로 하는 것으로 여겨, 거절하면 예절을 어긴 것이라고 여긴다','예절은 들어주기가 아니라 살피기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X17','kor',3,'u4',ARRAY['K3-2-u4-C13','K3-2-u4-C19']::text[],'말하지 않고 가만히 있으면 끼어들 일도 다툼도 없으니 예절을 가장 잘 지킨 것이라고 여긴다','내 생각은 어디에?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X18','kor',3,'u4',ARRAY['K3-2-u4-C14']::text[],'예절을 부탁한 내용·물건·친한 정도에서 찾고, 부르는 말·부탁하는 말·말하는 태도에 드러난다는 것을 놓친다','내용이 같았는데 무엇이 달랐나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X19','kor',3,'u4',ARRAY['K3-2-u4-C15']::text[],'부탁을 들어줄 수 없을 때 까닭 없이 “안 돼.”라고 짧게만 말하거나 말없이 피한다','상대가 “나를 싫어하나?” 하지 않으려면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X20','kor',3,'u4',ARRAY['K3-2-u4-C15']::text[],'웃어른의 부탁은 들어드릴 수 없어도 하겠다고 거짓으로 대답해야 한다고 여긴다','못 하는데 하겠다고 하면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X21','kor',3,'u4',ARRAY['K3-2-u4-C16','K3-2-u4-C17']::text[],'목소리 크기·말 빠르기를 예절로 여겨, 어디에서든 크게 말하면 좋다고 여긴다','운동장과 도서관은 같은 곳일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X22','kor',3,'u4',ARRAY['K3-2-u4-C16','K3-2-u4-C20']::text[],'상황을 이루는 것(대화 상대·시간과 장소·목적과 방식)을 엇갈리게 짝짓거나, 상황이 달라져도 말은 같아야 한다고 여긴다','누구와, 어디에서, 무엇을 하려고?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X23','kor',3,'u4',ARRAY['K3-2-u4-C17']::text[],'말끝에 ‘요’만 붙이면 예절을 다 지킨 것이라 여겨 누운 채·화면만 보며 대답하는 자세와 태도를 놓친다','말끝 말고 몸은 어땠나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X24','kor',3,'u4',ARRAY['K3-2-u4-C17']::text[],'여럿이 함께 있을 때 한 사람을 빼는 귓속말이나 함께 정하는 일과 상관없는 말을 해도 괜찮다고 여긴다','함께 있는 사람의 마음은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X25','kor',3,'u4',ARRAY['K3-2-u4-C18','K3-2-u4-C20']::text[],'전화에서 내가 누구인지 밝히지 않거나, 받을 때까지 다시 걸거나, 끝인사 없이 바로 끊거나, 받자마자 내 할 말부터 한다','상대는 나를 볼 수 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X26','kor',3,'u4',ARRAY['K3-2-u4-C19']::text[],'모둠 대화를 이기는 일로 여겨 다른 생각은 듣지 않고 내 생각만 끝까지 밀고 간다','함께 답을 찾는 거예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X27','kor',3,'u4',ARRAY['K3-2-u4-C21']::text[],'표정·몸짓·말투는 말이 아니라 아무 뜻이 없다고 여기거나, 전화처럼 보이지 않으면 듣고 있다는 것을 알릴 방법이 없다고 여긴다','같은 말, 다른 말투') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X28','kor',3,'u4',ARRAY['K3-2-u4-C22']::text[],'점검표·되돌아보기 표를 칸을 채우거나 점수를 높여 적는 일로 여긴다','고치려고 보는 거예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X29','kor',3,'u4',ARRAY['K3-2-u4-C23']::text[],'다짐을 “착하게 살겠습니다”처럼 언제·무엇을 할지 드러나지 않게 쓰거나 여러 개를 한꺼번에 적고, 남과 같은 예절을 골라야 한다고 여긴다','내일 해 보았는지 알 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X30','kor',3,'u4',ARRAY['K3-2-u4-C24']::text[],'우리 반 실천 활동을 가장 재미있어 보이거나 빨리 끝나는 것으로 고른다','실천 시간은 무엇을 하려고?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X31','kor',3,'u4',ARRAY['K3-2-u4-C25']::text[],'방언을 잘못 배운 틀린 말이나 옛날에만 쓰던 말로 여기거나, 확인하지 않고 지어낸 낱말을 방언이라고 여긴다','다른 것은 틀린 것이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X32','kor',3,'u4',ARRAY['K3-2-u4-C26']::text[],'ㅐ와 ㅔ, ㅒ와 ㅖ의 모양을 섞어 새해·세배·얘들아·계절을 틀리게 쓴다','가로획 자리, 짧은 획 두 개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X33','kor',3,'u4',ARRAY['K3-2-u4-C10','K3-2-u4-C15']::text[],'이야기나 대화에서 인물의 마음·행동의 까닭을 글에 없는 내용으로 짐작해 잘못 읽는다','그 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X34','kor',3,'u4',ARRAY['K3-2-u4-C2','K3-2-u4-C9']::text[],'높임 표현을 찾을 때 문장 전체나 부르는 말(“할아버지”)을 통째로 높임 표현으로 보고, 높임을 나타내는 말(께·께서·-시-·드리다·생신)을 짚어 내지 못한다','왼쪽 장면과 견주어 달라진 말은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X35','kor',3,'u4',ARRAY['K3-2-u4-C6','K3-2-u4-C8']::text[],'높임의 뜻이 있는 낱말이 따로 있는 말(있다·먹다·데리다·인사하다)에 ‘-시-’만 붙이거나 그대로 써서 ‘있으시다·먹으시면·데리러·인사하고’처럼 말한다','높임의 뜻이 있는 낱말이 따로 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X36','kor',3,'u4',ARRAY['K3-2-u4-C6']::text[],'높임의 뜻이 있는 낱말과 본래의 낱말을 거꾸로 알아 ‘밥·생일·집’을 높임의 뜻이 있는 낱말로 여긴다','웃어른께 쓰는 쪽은 어느 낱말?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X37','kor',3,'u4',ARRAY['K3-2-u4-C13']::text[],'‘참 좋은 말’이나 대화 예절을 듣기 좋게 꾸민 말을 하는 것으로 여기고, 상대의 상황과 처지를 헤아리는 것임을 놓친다','그 사람은 지금 어떤 상황일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X38','kor',3,'u4',ARRAY['K3-2-u4-C19']::text[],'모둠 대화의 차례(주제 확인하기 → 의견 마련하기 → 의견 모으기 → 의견 결정하기)를 엇갈리게 알아, 주제를 확인하기 전에 의견부터 정하거나 의견을 모으기 전에 결정한다','무엇을 이야기할지부터 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X39','kor',3,'u4',ARRAY['K3-2-u4-C14','K3-2-u4-C15']::text[],'부탁할 때 상대가 들어줄 수 있는 상황인지 묻지 않고 부탁하는 까닭과 내용도 밝히지 않은 채 시키듯 말하거나, 부탁을 들어준 뒤 고마움을 표현하지 않는다','지금 괜찮은지, 왜 필요한지, 고마워') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X40','kor',3,'u4',ARRAY['K3-2-u4-C8','K3-2-u4-C9']::text[],'상대에게 하라고 권하는 말을 ‘오실게요·앉으실게요’처럼 ‘-실게요’로 말한다(→ 오세요·앉으세요)','‘-ㄹ게요’는 내가 하겠다는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_basic#1','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C1',1,'mc','auto','『국어』 178쪽 1번이에요. 대화 ㉮와 ㉯에서 유찬이가 말하려는 내용은 무엇인가요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":1,"concept":"K3-2-u4-C1","difficulty":1,"kind":"mc","stem":"『국어』 178쪽 1번이에요. 대화 ㉮와 ㉯에서 유찬이가 말하려는 내용은 무엇인가요?","options":[{"t":"국어사전을 빌릴 수 있을지 묻는 내용","correct":true},{"t":"국어사전을 선물하겠다는 내용","mis":"K3-2-u4-X33"},{"t":"국어사전을 돌려주겠다는 내용","mis":"K3-2-u4-X33"},{"t":"국어사전이 어디 있는지 묻는 내용","mis":"K3-2-u4-X33"}],"explanation":["㉮에서는 지현이에게, ㉯에서는 선생님께 말했어요.","두 대화 모두 국어사전을 빌려 달라는 부탁이에요.","말하려는 내용은 같아요."],"asset":{"type":"speech","turns":[{"who":"㉮ 유찬 → 친구","text":"“지현아, 국어사전 좀 빌려줄래?”"},{"who":"지현","text":"“물론이지.”"},{"who":"㉯ 유찬 → 선생님","text":"“선생님, 국어사전 좀 빌려주시겠어요?”"},{"who":"선생님","text":"“그럼.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_basic#2','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C1',1,'mc','auto','대화 ㉮와 대화 ㉯에서 유찬이의 표현이 달라진 까닭은 무엇인가요?',ARRAY['K3-2-u4-X01','K3-2-u4-X04']::text[],false,'{"seq":2,"concept":"K3-2-u4-C1","difficulty":1,"kind":"mc","stem":"대화 ㉮와 대화 ㉯에서 유찬이의 표현이 달라진 까닭은 무엇인가요?","options":[{"t":"대화하는 상대가 달라졌기 때문","correct":true},{"t":"빌리려는 물건이 달라졌기 때문","mis":"K3-2-u4-X01"},{"t":"선생님께는 말을 길게 늘여야 하기 때문","mis":"K3-2-u4-X04"},{"t":"부탁한 시간이 달라졌기 때문","mis":"K3-2-u4-X01"}],"explanation":["빌리려는 것은 둘 다 국어사전이에요.","㉮는 친구 지현이, ㉯는 선생님과 대화했어요.","대화 상대가 달라지면 쓰는 표현도 달라져요."],"asset":{"type":"speech","turns":[{"who":"㉮ 유찬 → 친구","text":"“지현아, 국어사전 좀 빌려줄래?”"},{"who":"지현","text":"“물론이지.”"},{"who":"㉯ 유찬 → 선생님","text":"“선생님, 국어사전 좀 빌려주시겠어요?”"},{"who":"선생님","text":"“그럼.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_basic#3','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C2',1,'ox','auto','높임 표현은 대상을 높이는 표현이고, 그 안에는 존중과 공경의 마음이 담겨 있어요.',ARRAY['K3-2-u4-X04']::text[],false,'{"seq":3,"concept":"K3-2-u4-C2","difficulty":1,"kind":"ox","stem":"높임 표현은 대상을 높이는 표현이고, 그 안에는 존중과 공경의 마음이 담겨 있어요.","answer":"O","reason_options":[{"t":"『국어』 180쪽 정리 그대로예요. 높임 표현에는 존중과 공경의 마음이 담겨 있어요.","correct":true},{"t":"높임 표현은 말을 길고 어렵게 만드는 표현일 뿐이에요.","mis":"K3-2-u4-X04"}],"mis":"K3-2-u4-X04","explanation":["높임 표현은 누군가를 높이는 표현이에요.","그 사람을 존중하고 공경하는 마음이 들어 있어요.","말을 길게 늘인다고 높임 표현이 되는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_basic#4','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',1,'mc','auto','『국어』 180쪽 1번이에요. 상황 ㉮와 상황 ㉯는 각각 누구의 생일을 축하하고 있나요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":4,"concept":"K3-2-u4-C3","difficulty":1,"kind":"mc","stem":"『국어』 180쪽 1번이에요. 상황 ㉮와 상황 ㉯는 각각 누구의 생일을 축하하고 있나요?","options":[{"t":"㉮는 진우, ㉯는 할아버지","correct":true},{"t":"㉮는 할아버지, ㉯는 진우","mis":"K3-2-u4-X33"},{"t":"㉮와 ㉯ 모두 진우","mis":"K3-2-u4-X33"},{"t":"㉮와 ㉯ 모두 할아버지","mis":"K3-2-u4-X33"}],"explanation":["㉮에서 친구들은 “진우야, 생일 축하해!”라고 했어요.","㉯에서 진우는 “할아버지, 생신 축하드려요!”라고 했어요.","생일잔치라는 상황은 같지만 생일의 주인공이 달라요."],"asset":{"type":"speech","turns":[{"who":"㉮ 친구들 → 진우","text":"“진우야, 생일 축하해!”"},{"who":"㉯ 진우 → 할아버지","text":"“할아버지, 생신 축하드려요!”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_basic#5','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C2',2,'mc','auto','상황 ㉯에서 진우가 할아버지를 높이려고 사용한 표현은 무엇인가요?',ARRAY['K3-2-u4-X34','K3-2-u4-X36','K3-2-u4-X10']::text[],false,'{"seq":5,"concept":"K3-2-u4-C2","difficulty":2,"kind":"mc","stem":"상황 ㉯에서 진우가 할아버지를 높이려고 사용한 표현은 무엇인가요?","options":[{"t":"‘생신’과 ‘축하드려요’","correct":true},{"t":"‘할아버지’ — 부르는 말에 웃어른이 나와서","mis":"K3-2-u4-X34"},{"t":"‘생일’ — 축하하는 날을 말해서","mis":"K3-2-u4-X36"},{"t":"“진우야, 생일 축하해!”","mis":"K3-2-u4-X10"}],"explanation":["㉮의 “생일 축하해!”와 견주어 보아요.","‘생일’ 대신 ‘생신’, ‘축하해’ 대신 ‘축하드려요’를 썼어요.","이렇게 달라진 말이 할아버지를 높이는 표현이에요."],"asset":{"type":"speech","turns":[{"who":"㉮ 친구들 → 진우","text":"“진우야, 생일 축하해!”"},{"who":"㉯ 진우 → 할아버지","text":"“할아버지, 생신 축하드려요!”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_basic#6','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',2,'mc','auto','『국어』 181쪽 상황 ㉮의 오른쪽 장면에서 사용한 높임 표현과 그 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X34','K3-2-u4-X08']::text[],false,'{"seq":6,"concept":"K3-2-u4-C3","difficulty":2,"kind":"mc","stem":"『국어』 181쪽 상황 ㉮의 오른쪽 장면에서 사용한 높임 표현과 그 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"‘께’, ‘드릴’ — 선물을 받는 사람이 할머니(어른)이기 때문","correct":true},{"t":"‘선물’ — 선물이 귀한 물건이기 때문","mis":"K3-2-u4-X09"},{"t":"“할머니께 드릴 선물이야.” 문장 전체 — 할머니가 나오기 때문","mis":"K3-2-u4-X34"},{"t":"‘이야’ — 말끝이 공손하기 때문","mis":"K3-2-u4-X08"}],"explanation":["왼쪽 “지윤이한테 줄”과 오른쪽 “할머니께 드릴”을 견주어요.","‘한테’가 ‘께’로, ‘줄’이 ‘드릴’로 바뀌었어요.","선물을 받는 사람이 할머니라서 높였어요."],"asset":{"type":"passage","lines":["왼쪽 — “이 선물은 누구한테 주는 거니?”","“지윤이한테 줄 선물이야.”","오른쪽 — “이 선물은 누구한테 주는 거니?”","“할머니께 드릴 선물이야.”"],"title":"상황 ㉮ — 『국어』 181쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_basic#7','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',2,'mc','auto','상황 ㉯의 학급 회의에서 같은 반 친구 성준이에게 “박성준 학생, …… 말해 주십시오.”라고 높임 표현을 쓴 까닭은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X33','K3-2-u4-X03']::text[],false,'{"seq":7,"concept":"K3-2-u4-C3","difficulty":2,"kind":"mc","stem":"상황 ㉯의 학급 회의에서 같은 반 친구 성준이에게 “박성준 학생, …… 말해 주십시오.”라고 높임 표현을 쓴 까닭은 무엇인가요?","options":[{"t":"학급 회의라는 공식적인 상황이기 때문","correct":true},{"t":"성준이가 나이가 더 많기 때문","mis":"K3-2-u4-X02"},{"t":"성준이와 사이가 나빠졌기 때문","mis":"K3-2-u4-X33"},{"t":"친구에게는 언제나 높임 표현을 써야 하기 때문","mis":"K3-2-u4-X03"}],"explanation":["쉬는 시간에는 “성준아, …… 정했어?”라고 반말을 했어요.","학급 회의에서는 같은 친구에게도 높임 표현을 썼어요.","회의나 발표처럼 공식적인 상황이기 때문이에요."],"asset":{"type":"passage","lines":["쉬는 시간 — “성준아, 회의 주제에 대한 의견 정했어?”","“응, 실천 방법을 제안해 보려고.”","학급 회의 — “박성준 학생, 회의 주제에 대한 의견을 말해 주십시오.”","“네, 제가 발표하겠습니다.”"],"title":"상황 ㉯ — 『국어』 181쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_basic#8','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',2,'mc','auto','상황 ㉰에서 전학 온 김동현이 반 친구들에게 높임 표현을 쓴 까닭은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X04','K3-2-u4-X03']::text[],false,'{"seq":8,"concept":"K3-2-u4-C3","difficulty":2,"kind":"mc","stem":"상황 ㉰에서 전학 온 김동현이 반 친구들에게 높임 표현을 쓴 까닭은 무엇인가요?","options":[{"t":"친구들 앞에서 발표하고, 처음 만난 친구들에게 자신을 소개하는 상황이기 때문","correct":true},{"t":"반 친구들이 모두 동현이보다 나이가 많기 때문","mis":"K3-2-u4-X02"},{"t":"높임말은 길수록 멋져 보이기 때문","mis":"K3-2-u4-X04"},{"t":"앞으로도 반 친구들에게 늘 높임말을 써야 하기 때문","mis":"K3-2-u4-X03"}],"explanation":["동현이는 교실 앞에서 여러 친구에게 말해요.","친구들과는 오늘 처음 만난 사이예요.","발표 상황과 처음 만난 사이라는 두 가지 때문에 높임 표현을 썼어요."],"asset":{"type":"passage","lines":["[그림] 교실 앞에 선 전학생과 처음 보는 반 친구들","“안녕하세요? 저는 ○○초등학교에서 전학 온 김동현이라고 합니다.","만나서 반갑습니다.”"],"title":"상황 ㉰ — 『국어』 182쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_basic#9','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',2,'blank','auto','『국어』 183쪽 정리 글이에요. ㉡에 들어갈 알맞은 낱말을 보기에서 고르세요.',ARRAY['K3-2-u4-X03','K3-2-u4-X02','K3-2-u4-X22']::text[],false,'{"seq":9,"concept":"K3-2-u4-C3","difficulty":2,"kind":"blank","stem":"『국어』 183쪽 정리 글이에요. ㉡에 들어갈 알맞은 낱말을 보기에서 고르세요.","options":[{"t":"공식적","correct":true},{"t":"비공식적","mis":"K3-2-u4-X03"},{"t":"웃어른","mis":"K3-2-u4-X02"},{"t":"존중","mis":"K3-2-u4-X22"}],"explanation":["「회의나 발표와 같은 (  ) 상황」을 다시 읽어요.","회의나 발표는 여러 사람 앞에서 정해진 차례로 말하는 자리예요.","이런 자리를 공식적인 상황이라고 해요."],"asset":{"type":"passage","lines":["높임 표현은 여러 가지 상황에서 사용할 수 있습니다.","먼저, (  ㉠  )께는 높임 표현을 사용해야 합니다.","평소에는 반말을 하는 친구 사이일지라도 회의나 발표와 같은","(  ㉡  ) 상황에서는 높임 표현을 사용해야 합니다.","처음 만난 사이처럼 가깝지 않은 사이에서는 주로 높임 표현을 사용합니다.","상대와의 관계에 따라 (  ㉢  )을 표현하기 위해","나이와 관계없이 높임 표현을 사용하기도 합니다.","보기: 비공식적 · 공식적 · 존중 · 웃어른"],"title":"「높임 표현을 사용하는 상황」 — 『국어』 183쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_basic#10','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',3,'mc','auto','상황 ㉱에서 진헌이 할머니가 자신보다 나이가 어린 선생님께 높임 표현을 쓴 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X33','K3-2-u4-X03']::text[],false,'{"seq":10,"concept":"K3-2-u4-C3","difficulty":3,"kind":"mc","stem":"상황 ㉱에서 진헌이 할머니가 자신보다 나이가 어린 선생님께 높임 표현을 쓴 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"상대와의 관계와 역할에 따라 나이와 관계없이 존중을 표현하려고","correct":true},{"t":"할머니가 실수로 높임 표현을 쓴 것이다","mis":"K3-2-u4-X02"},{"t":"선생님이 할머니보다 나이가 더 많기 때문이다","mis":"K3-2-u4-X33"},{"t":"학교에서는 누구나 누구에게나 높임 표현을 써야 하기 때문이다","mis":"K3-2-u4-X03"}],"explanation":["선생님은 진헌이를 가르치시는 분이에요.","할머니는 나이와 관계없이 선생님을 존중하려고 높임 표현을 썼어요.","높임 표현은 나이만으로 정하는 것이 아니에요."],"asset":{"type":"passage","lines":["[그림] 학교 앞에서 할머니와 진헌이가 젊은 담임 선생님을 만남","진헌이 할머니 — “선생님, 안녕하세요? 제가 진헌이 할머니예요.”","진헌 — “선생님, 안녕하세요?”"],"title":"상황 ㉱ — 『국어』 182쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_challenge#1','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C1',2,'mc','auto','『국어』 179쪽 2번 상황 ㉮예요. 도서관에서 큰 소리로 웃는 친구들이 지켜야 할 예절은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X22','K3-2-u4-X17']::text[],false,'{"seq":1,"concept":"K3-2-u4-C1","difficulty":2,"kind":"mc","stem":"『국어』 179쪽 2번 상황 ㉮예요. 도서관에서 큰 소리로 웃는 친구들이 지켜야 할 예절은 무엇인가요?","options":[{"t":"도서관에서는 다른 사람에게 방해가 되지 않게 조용히 말한다","correct":true},{"t":"재미있는 부분을 읽을 때는 크게 웃어도 된다","mis":"K3-2-u4-X21"},{"t":"친구끼리 이야기할 때는 장소를 생각하지 않아도 된다","mis":"K3-2-u4-X22"},{"t":"옆 친구가 말해도 못 들은 척한다","mis":"K3-2-u4-X17"}],"explanation":["옆 친구가 “어? 여긴 도서관인데…….” 하고 말했어요.","도서관은 여러 사람이 조용히 책을 읽는 곳이에요.","장소에 따라 지켜야 할 대화 예절이 있어요."],"asset":{"type":"passage","lines":["㉮ 도서관 — 친구들이 책을 보며 “하하하! 이 부분 엄청 재밌다!”","옆에 앉은 친구: “어? 여긴 도서관인데…….”","㉯ 전화 — 끊긴 전화기를 든 사람: “아직 할 말이 남았는데 끊어 버렸네.”"],"title":"『국어』 179쪽 2번 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_challenge#2','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C1',2,'mc','auto','상황 ㉯에서 “아직 할 말이 남았는데 끊어 버렸네.”라는 말을 듣지 않으려면 전화를 건 사람은 어떻게 해야 했나요?',ARRAY['K3-2-u4-X25','K3-2-u4-X21','K3-2-u4-X27']::text[],false,'{"seq":2,"concept":"K3-2-u4-C1","difficulty":2,"kind":"mc","stem":"상황 ㉯에서 “아직 할 말이 남았는데 끊어 버렸네.”라는 말을 듣지 않으려면 전화를 건 사람은 어떻게 해야 했나요?","options":[{"t":"상대의 말이 끝났는지 살피고 끝인사를 한 뒤에 끊는다","correct":true},{"t":"내 할 말을 다 했으면 바로 끊는다","mis":"K3-2-u4-X25"},{"t":"더 크게 말하고 바로 끊는다","mis":"K3-2-u4-X21"},{"t":"상대가 말할 때 다른 일을 한다","mis":"K3-2-u4-X27"}],"explanation":["상대는 아직 할 말이 남아 있었어요.","전화는 얼굴이 보이지 않아 말이 끝났는지 살펴야 해요.","끝인사를 하고 끊으면 기분 상할 일이 없어요."],"asset":{"type":"passage","lines":["㉮ 도서관 — 친구들이 책을 보며 “하하하! 이 부분 엄청 재밌다!”","옆에 앉은 친구: “어? 여긴 도서관인데…….”","㉯ 전화 — 끊긴 전화기를 든 사람: “아직 할 말이 남았는데 끊어 버렸네.”"],"title":"『국어』 179쪽 2번 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_challenge#3','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',3,'match','auto','『국어』 181~182쪽 상황 ㉮~㉱와 높임 표현을 사용한 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u4-C3","difficulty":3,"kind":"match","stem":"『국어』 181~182쪽 상황 ㉮~㉱와 높임 표현을 사용한 까닭을 알맞게 이으세요.","pairs":[{"l":"상황 ㉮ “할머니께 드릴 선물이야.”","r":"선물을 받는 사람이 어른이라서"},{"l":"상황 ㉯ “박성준 학생, …… 말해 주십시오.”","r":"학급 회의라는 공식적인 상황이라서"},{"l":"상황 ㉰ “저는 …… 김동현이라고 합니다.”","r":"처음 만난 친구들 앞에서 자신을 소개해서"},{"l":"상황 ㉱ “제가 진헌이 할머니예요.”","r":"나이와 관계없이 선생님을 존중하려고"}],"mis":"K3-2-u4-X02","explanation":["높임 표현을 쓰는 까닭은 상황마다 달라요.","어른을 높일 때, 공식적인 상황, 처음 만난 사이, 존중을 나타낼 때가 있어요.","나이만 보고 정하는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_challenge#4','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C2',3,'error','auto','세 친구가 상황 ㉮ 오른쪽 장면에서 높임 표현을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K3-2-u4-X34','K3-2-u4-X06','K3-2-u4-X07']::text[],false,'{"seq":4,"concept":"K3-2-u4-C2","difficulty":3,"kind":"error","stem":"세 친구가 상황 ㉮ 오른쪽 장면에서 높임 표현을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"하윤: “할머니께 드릴 선물이야.” 문장이 통째로 높임 표현이야.","correct":true,"mis_target":"K3-2-u4-X34"},{"t":"도윤: ‘한테’ 대신 ‘께’를 써서 할머니를 높였어.","mis":"K3-2-u4-X06"},{"t":"서아: ‘주다’ 대신 높임의 뜻이 있는 ‘드리다’를 썼어.","mis":"K3-2-u4-X07"}],"explanation":["높임 표현을 찾을 때에는 문장을 통째로 고르지 않아요.","왼쪽 장면과 견주어 달라진 ‘께’와 ‘드릴’을 짚어요.","높임을 나타내는 말을 정확히 찾아야 해요."],"asset":{"type":"passage","lines":["왼쪽 — “이 선물은 누구한테 주는 거니?”","“지윤이한테 줄 선물이야.”","오른쪽 — “이 선물은 누구한테 주는 거니?”","“할머니께 드릴 선물이야.”"],"title":"상황 ㉮ — 『국어』 181쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_challenge#5','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',3,'ox','auto','처음 만난 사이처럼 가깝지 않은 사이에서는 주로 높임 표현을 사용해요.',ARRAY['K3-2-u4-X02']::text[],false,'{"seq":5,"concept":"K3-2-u4-C3","difficulty":3,"kind":"ox","stem":"처음 만난 사이처럼 가깝지 않은 사이에서는 주로 높임 표현을 사용해요.","answer":"O","reason_options":[{"t":"『국어』 183쪽 정리 글에 처음 만난 사이에서는 주로 높임 표현을 쓴다고 했어요.","correct":true},{"t":"처음 만나도 나이가 같으면 바로 반말을 써야 해요.","mis":"K3-2-u4-X02"}],"mis":"K3-2-u4-X02","explanation":["처음 만난 사람과는 아직 가깝지 않은 사이예요.","그래서 서로 높임 표현을 쓰며 존중을 나타내요.","전학 온 동현이도 높임 표현으로 인사했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_challenge#6','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',3,'mc','auto','『국어』 183쪽 3번 「높임 표현을 언제 사용하면 좋을지」 이야기한 말 가운데에서 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X10']::text[],false,'{"seq":6,"concept":"K3-2-u4-C3","difficulty":3,"kind":"mc","stem":"『국어』 183쪽 3번 「높임 표현을 언제 사용하면 좋을지」 이야기한 말 가운데에서 알맞지 않은 것은 무엇인가요?","options":[{"t":"친구와는 어떤 상황에서도 높임 표현을 쓰지 않아도 돼.","correct":true},{"t":"모둠 활동을 할 때에도 서로 높임 표현을 사용하면 좋겠어.","mis":"K3-2-u4-X02"},{"t":"누군가를 처음 만난 자리에서는 일단 높임 표현을 사용해야겠어.","mis":"K3-2-u4-X02"},{"t":"부모님께 예의와 존중을 담아 높임 표현을 잘 사용해야겠어.","mis":"K3-2-u4-X10"}],"explanation":["친구 사이라도 회의·발표 같은 공식적인 상황에서는 높임 표현을 써요.","모둠 활동에서 서로 높여 말하는 것도 좋은 생각이에요.","처음 만난 자리, 부모님과의 대화에서도 높임 표현을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_challenge#7','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',3,'mc','auto','상황 ㉯와 같은 학급 회의에서 높임 표현을 쓰지 않으면 어떤 일이 생길 수 있을까요?',ARRAY['K3-2-u4-X10','K3-2-u4-X01','K3-2-u4-X21']::text[],false,'{"seq":7,"concept":"K3-2-u4-C3","difficulty":3,"kind":"mc","stem":"상황 ㉯와 같은 학급 회의에서 높임 표현을 쓰지 않으면 어떤 일이 생길 수 있을까요?","options":[{"t":"회의가 장난처럼 느껴지고, 발표하는 사람을 존중하지 않는 것처럼 보일 수 있다","correct":true},{"t":"아무 일도 없다 — 친구끼리는 높임 표현이 필요 없다","mis":"K3-2-u4-X10"},{"t":"회의 주제가 저절로 바뀐다","mis":"K3-2-u4-X01"},{"t":"발표하는 사람의 목소리가 커진다","mis":"K3-2-u4-X21"}],"explanation":["회의는 여러 사람이 함께 정하는 공식적인 자리예요.","높임 표현을 쓰면 서로의 의견을 존중한다는 마음이 드러나요.","높임 표현을 쓰지 않으면 회의의 분위기가 흐트러질 수 있어요."],"asset":{"type":"passage","lines":["쉬는 시간 — “성준아, 회의 주제에 대한 의견 정했어?”","“응, 실천 방법을 제안해 보려고.”","학급 회의 — “박성준 학생, 회의 주제에 대한 의견을 말해 주십시오.”","“네, 제가 발표하겠습니다.”"],"title":"상황 ㉯ — 『국어』 181쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_challenge#8','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',4,'essay','teacher','『국어』 183쪽 3번이에요. 높임 표현을 사용하면 좋을 상황을 서로 다른 두 가지 쓰고, 그때 높임 표현을 써야 하는 까닭을 각각 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u4-C3","difficulty":4,"kind":"essay","stem":"『국어』 183쪽 3번이에요. 높임 표현을 사용하면 좋을 상황을 서로 다른 두 가지 쓰고, 그때 높임 표현을 써야 하는 까닭을 각각 쓰세요.","answer_guide":{"answer":"예: ① 할아버지께 전화로 안부를 여쭐 때 — 웃어른을 공경하는 마음을 나타내려고. ② 반에서 모둠 발표를 할 때 — 친구들 앞에서 말하는 공식적인 상황이라서.","scoring_points":["높임 표현을 사용할 상황을 서로 다른 두 가지 썼는가","각 상황에서 높임 표현을 써야 하는 까닭을 썼는가","웃어른·공식적인 상황·처음 만난 사이·존중 가운데에서 알맞게 까닭을 댔는가"]},"explanation":["웃어른께 말할 때, 회의나 발표 때, 처음 만난 사람과 말할 때를 떠올려요.","까닭은 그 상황에서 높임 표현이 왜 필요한지로 써요.","나이 말고도 상황과 관계를 함께 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_challenge#9','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',4,'mc','auto','『국어』 177쪽 「생각 열기」예요. 여자아이는 친구에게 “내가 지난 주말에…….”, 선생님께 “제가 지난 주말에…….”라고 했어요. ‘내가’를 ‘제가’로 바꾼 것은 어떤 높임 방법인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X09','K3-2-u4-X01']::text[],false,'{"seq":9,"concept":"K3-2-u4-C3","difficulty":4,"kind":"mc","stem":"『국어』 177쪽 「생각 열기」예요. 여자아이는 친구에게 “내가 지난 주말에…….”, 선생님께 “제가 지난 주말에…….”라고 했어요. ‘내가’를 ‘제가’로 바꾼 것은 어떤 높임 방법인가요?","options":[{"t":"자신을 낮추는 ‘제가’를 써서 이야기를 듣는 선생님을 높였다","correct":true},{"t":"‘제가’를 써서 말하는 자신을 높였다","mis":"K3-2-u4-X11"},{"t":"‘제가’를 써서 지난 주말을 높였다","mis":"K3-2-u4-X09"},{"t":"아무것도 높이지 않았다 — 이야기 내용이 같기 때문이다","mis":"K3-2-u4-X01"}],"explanation":["‘제가’는 ‘내가’를 낮추어 이르는 말이에요.","나를 낮추면 듣는 선생님을 높이게 돼요.","그래서 선생님과 말할 때 ‘제가’를 써요."],"asset":{"type":"speech","turns":[{"who":"여자아이 → 친구","text":"“내가 지난 주말에…….”"},{"who":"여자아이 → 선생님","text":"“제가 지난 주말에…….”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L02_challenge#10','kor',3,2,'u4','L02','tb_g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',4,'mc','auto','상황 ㉰에서 동현이가 높임 표현을 쓴 데에는 두 가지가 함께 작용했어요. 바르게 묶은 것은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X22']::text[],false,'{"seq":10,"concept":"K3-2-u4-C3","difficulty":4,"kind":"mc","stem":"상황 ㉰에서 동현이가 높임 표현을 쓴 데에는 두 가지가 함께 작용했어요. 바르게 묶은 것은 무엇인가요?","options":[{"t":"발표라는 공식적인 상황 + 처음 만난 사이","correct":true},{"t":"친구들의 나이 + 발표 내용","mis":"K3-2-u4-X02"},{"t":"발표라는 공식적인 상황 + 친구들이 모두 웃어른임","mis":"K3-2-u4-X22"},{"t":"처음 만난 사이 + 교실이 넓음","mis":"K3-2-u4-X22"}],"explanation":["동현이는 여러 친구 앞에서 발표하듯 말해요.","친구들과는 오늘 처음 만났어요.","높임 표현을 쓰는 까닭은 하나가 아니라 여럿이 함께 작용하기도 해요."],"asset":{"type":"passage","lines":["[그림] 교실 앞에 선 전학생과 처음 보는 반 친구들","“안녕하세요? 저는 ○○초등학교에서 전학 온 김동현이라고 합니다.","만나서 반갑습니다.”"],"title":"상황 ㉰ — 『국어』 182쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_basic#1','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C4',1,'mc','auto','『국어』 184쪽 1번 대화 ㉮예요. “이번 마을 축제에 너희 부모님께서도 (가니, 가시니)?”에서 알맞은 높임 표현은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X05']::text[],false,'{"seq":1,"concept":"K3-2-u4-C4","difficulty":1,"kind":"mc","stem":"『국어』 184쪽 1번 대화 ㉮예요. “이번 마을 축제에 너희 부모님께서도 (가니, 가시니)?”에서 알맞은 높임 표현은 무엇인가요?","options":[{"t":"가시니","correct":true},{"t":"가니","mis":"K3-2-u4-X10"},{"t":"가니와 가시니 둘 다 똑같다","mis":"K3-2-u4-X05"}],"explanation":["‘가다’는 누가 하는 일인지 찾아요.","가는 사람은 친구의 부모님이에요.","부모님을 높이려면 ‘-시-’를 넣어 ‘가시니’라고 해요."],"asset":{"type":"speech","turns":[{"who":"㉮ 친구","text":"“이번 마을 축제에 너희 부모님께서도 (가니, 가시니)?”"},{"who":"㉯ 친구","text":"“나도 도저히 모르겠어. 선생님께 (물어보자, 여쭈어보자).”"},{"who":"㉰ 아이 → 어머니","text":"“어머니, 학교 (다녀올게, 다녀오겠습니다).”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_basic#2','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C6',1,'mc','auto','대화 ㉯예요. “선생님께 (물어보자, 여쭈어보자).”에서 알맞은 높임 표현은 무엇인가요?',ARRAY['K3-2-u4-X07','K3-2-u4-X35']::text[],false,'{"seq":2,"concept":"K3-2-u4-C6","difficulty":1,"kind":"mc","stem":"대화 ㉯예요. “선생님께 (물어보자, 여쭈어보자).”에서 알맞은 높임 표현은 무엇인가요?","options":[{"t":"여쭈어보자","correct":true},{"t":"물어보자","mis":"K3-2-u4-X07"},{"t":"물어보시자","mis":"K3-2-u4-X35"}],"explanation":["선생님께 묻는 상황이에요.","‘묻다’에는 높임의 뜻이 있는 낱말 ‘여쭈다(여쭈어보다)’가 따로 있어요.","‘-시-’만 붙인 ‘물어보시자’는 바른 말이 아니에요."],"asset":{"type":"speech","turns":[{"who":"㉮ 친구","text":"“이번 마을 축제에 너희 부모님께서도 (가니, 가시니)?”"},{"who":"㉯ 친구","text":"“나도 도저히 모르겠어. 선생님께 (물어보자, 여쭈어보자).”"},{"who":"㉰ 아이 → 어머니","text":"“어머니, 학교 (다녀올게, 다녀오겠습니다).”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_basic#3','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C7',1,'mc','auto','대화 ㉰예요. “어머니, 학교 (다녀올게, 다녀오겠습니다).”에서 알맞은 높임 표현은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X11']::text[],false,'{"seq":3,"concept":"K3-2-u4-C7","difficulty":1,"kind":"mc","stem":"대화 ㉰예요. “어머니, 학교 (다녀올게, 다녀오겠습니다).”에서 알맞은 높임 표현은 무엇인가요?","options":[{"t":"다녀오겠습니다","correct":true},{"t":"다녀올게","mis":"K3-2-u4-X10"},{"t":"다녀오시겠습니다","mis":"K3-2-u4-X11"}],"explanation":["말을 듣는 사람은 어머니예요.","말끝에 ‘-습니다’를 붙여 듣는 어머니를 높여요.","학교에 가는 사람은 나라서 ‘-시-’를 넣지 않아요."],"asset":{"type":"speech","turns":[{"who":"㉮ 친구","text":"“이번 마을 축제에 너희 부모님께서도 (가니, 가시니)?”"},{"who":"㉯ 친구","text":"“나도 도저히 모르겠어. 선생님께 (물어보자, 여쭈어보자).”"},{"who":"㉰ 아이 → 어머니","text":"“어머니, 학교 (다녀올게, 다녀오겠습니다).”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_basic#4','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C7',1,'match','auto','『국어』 185쪽 1번 (2)예요. 대화 ㉮~㉰에서 사용한 높임 표현 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u4-C7","difficulty":1,"kind":"match","stem":"『국어』 185쪽 1번 (2)예요. 대화 ㉮~㉰에서 사용한 높임 표현 방법을 알맞게 이으세요.","pairs":[{"l":"대화 ㉮ “부모님께서도 가시니?”","r":"높임을 나타내는 ‘께서’와 ‘-시-’를 사용한다."},{"l":"대화 ㉯ “선생님께 여쭈어보자.”","r":"높임의 뜻이 있는 낱말을 사용한다."},{"l":"대화 ㉰ “학교 다녀오겠습니다.”","r":"높임을 나타내는 ‘-습니다’나 ‘요’를 사용한다."}],"mis":"K3-2-u4-X08","explanation":["㉮는 ‘께서’와 ‘가시니’의 ‘-시-’로 부모님을 높였어요.","㉯는 ‘여쭈어보다’라는 높임 낱말을 썼어요.","㉰는 ‘-습니다’로 듣는 어머니를 높였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_basic#5','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C4',2,'sa','auto','『국어』 185쪽 2번이에요. 민수가 ‘오는’ 대신 ‘오시는’이라고 해서 높인 사람은 누구인가요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u4-C4","difficulty":2,"kind":"sa","stem":"『국어』 185쪽 2번이에요. 민수가 ‘오는’ 대신 ‘오시는’이라고 해서 높인 사람은 누구인가요? 한 낱말로 쓰세요.","answer":["할아버지","할아버지를"],"explanation":["‘오다’는 누가 하는 일인지 찾아요.","오늘 오시는 분은 할아버지예요.","‘-시-’는 그 일을 하는 사람을 높여요."],"asset":{"type":"speech","turns":[{"who":"민수","text":"“아버지, 오늘 할아버지께서 오시는 날이지요? 누가 모시러 가요?”"},{"who":"아버지","text":"“응, 누나가 이미 출발했어. 할아버지께 미리 연락을 드렸대.”"}]},"mis":"K3-2-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_basic#6','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C7',2,'mc','auto','민수가 ‘가?’ 대신 ‘가요?’라고 해서 높인 사람은 누구인가요?',ARRAY['K3-2-u4-X08','K3-2-u4-X05','K3-2-u4-X11']::text[],false,'{"seq":6,"concept":"K3-2-u4-C7","difficulty":2,"kind":"mc","stem":"민수가 ‘가?’ 대신 ‘가요?’라고 해서 높인 사람은 누구인가요?","options":[{"t":"민수의 말을 듣는 아버지","correct":true},{"t":"할아버지","mis":"K3-2-u4-X08"},{"t":"누나","mis":"K3-2-u4-X05"},{"t":"민수 자신","mis":"K3-2-u4-X11"}],"explanation":["말끝의 ‘요’는 그 말을 듣는 사람을 높여요.","민수는 아버지께 묻고 있어요.","그래서 ‘가요?’는 아버지를 높이는 표현이에요."],"asset":{"type":"speech","turns":[{"who":"민수","text":"“아버지, 오늘 할아버지께서 오시는 날이지요? 누가 모시러 가요?”"},{"who":"아버지","text":"“응, 누나가 이미 출발했어. 할아버지께 미리 연락을 드렸대.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_basic#7','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C9',2,'mc','auto','『국어』 186쪽 동영상에서 “……제품이시고요.”라는 말이 어색한 까닭은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X04','K3-2-u4-X08']::text[],false,'{"seq":7,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"『국어』 186쪽 동영상에서 “……제품이시고요.”라는 말이 어색한 까닭은 무엇인가요?","options":[{"t":"물건(신발)에 높임 표현 ‘-시-’를 썼기 때문","correct":true},{"t":"손님을 높이지 않았기 때문","mis":"K3-2-u4-X10"},{"t":"말이 너무 짧기 때문","mis":"K3-2-u4-X04"},{"t":"말끝에 ‘요’를 붙였기 때문","mis":"K3-2-u4-X08"}],"explanation":["‘제품이시고요’에서 높인 것은 신발이에요.","신발은 물건이라 높임의 대상이 아니에요.","그래서 신발이 “뭐? 내가 제품이시라고?” 하고 놀랐어요."],"asset":{"type":"passage","lines":["[동영상] 가게에서 물건과 음료를 높이는 말이 들린다 — 『국어』 186쪽","신발 가게 — “……제품이시고요.”","카페 — “……아메리카노 나오셨습니다.”","“……매진되셨어요.”","[그림] 커다란 신발이 놀라서 — “뭐? 내가 제품이시라고?”"],"title":"동영상 속 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_basic#8','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C9',2,'sa','auto','동영상 속 “주문하신 아메리카노 나오셨습니다.”를 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u4-C9","difficulty":2,"kind":"sa","stem":"동영상 속 “주문하신 아메리카노 나오셨습니다.”를 바르게 고쳐 쓰세요.","answer":["주문하신 아메리카노 나왔습니다","아메리카노 나왔습니다","나왔습니다"],"explanation":["‘나오다’는 아메리카노가 하는 일이에요.","음료는 물건이라 ‘-시-’를 넣지 않아요.","“주문하신 아메리카노 나왔습니다.”라고 해요."],"asset":{"type":"passage","lines":["[동영상] 가게에서 물건과 음료를 높이는 말이 들린다 — 『국어』 186쪽","신발 가게 — “……제품이시고요.”","카페 — “……아메리카노 나오셨습니다.”","“……매진되셨어요.”","[그림] 커다란 신발이 놀라서 — “뭐? 내가 제품이시라고?”"],"title":"동영상 속 말"},"mis":"K3-2-u4-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_basic#9','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C5',2,'blank','auto','『국어』 187쪽 지운이의 쪽지예요. 「이건 저희 부모님(     ) 할머니, 할아버지께 드리는 떡이에요.」 빈칸에 들어갈 높임 표현은 무엇인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X10']::text[],false,'{"seq":9,"concept":"K3-2-u4-C5","difficulty":2,"kind":"blank","stem":"『국어』 187쪽 지운이의 쪽지예요. 「이건 저희 부모님(     ) 할머니, 할아버지께 드리는 떡이에요.」 빈칸에 들어갈 높임 표현은 무엇인가요?","options":[{"t":"께서","correct":true},{"t":"이","mis":"K3-2-u4-X06"},{"t":"께","mis":"K3-2-u4-X06"},{"t":"한테","mis":"K3-2-u4-X10"}],"explanation":["떡을 드리는 사람은 부모님이에요.","‘이/가’ 자리에서 높일 때는 ‘께서’를 써요.","‘께’는 ‘에게’ 자리에 써요."],"asset":{"type":"passage","lines":["할머니, 할아버지께","안녕하세요?","저는 옆집에 이사 온 김지운입니다.","직접 인사하고 싶었지만 집에 안 계셔서 이렇게 쪽지를 남겨요.","이건 저희 부모님께서 할머니, 할아버지께 드리는 떡이세요.","맛있게 잡수시면 좋겠어요.","안녕히 계세요.","김지운 올림"],"title":"지운이가 쓴 쪽지 — 『국어』 187쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_basic#10','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C9',3,'mc','auto','지운이의 쪽지에서 잘못된 높임 표현과 고친 표현을 바르게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X10','K3-2-u4-X35']::text[],false,'{"seq":10,"concept":"K3-2-u4-C9","difficulty":3,"kind":"mc","stem":"지운이의 쪽지에서 잘못된 높임 표현과 고친 표현을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"인사하고 → 인사드리고 · 집 → 댁 · 떡이세요 → 떡이에요","correct":true},{"t":"인사하고 → 인사드리고 · 집 → 집이세요 · 떡이세요 → 떡이시옵니다","mis":"K3-2-u4-X09"},{"t":"계셔서 → 있어서 · 집 → 댁 · 떡이세요 → 떡이에요","mis":"K3-2-u4-X10"},{"t":"인사하고 → 인사하시고 · 집 → 댁 · 잡수시면 → 먹으면","mis":"K3-2-u4-X35"}],"explanation":["인사를 하는 사람은 지운이, 인사를 받는 분은 할머니, 할아버지예요.","할머니, 할아버지의 집은 ‘댁’이라고 해요.","떡은 물건이라 ‘떡이에요’라고 고쳐요."],"asset":{"type":"passage","lines":["할머니, 할아버지께","안녕하세요?","저는 옆집에 이사 온 김지운입니다.","직접 인사하고 싶었지만 집에 안 계셔서 이렇게 쪽지를 남겨요.","이건 저희 부모님께서 할머니, 할아버지께 드리는 떡이세요.","맛있게 잡수시면 좋겠어요.","안녕히 계세요.","김지운 올림"],"title":"지운이가 쓴 쪽지 — 『국어』 187쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_challenge#1','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C9',2,'mc','auto','스승의 날 일기예요. 지금 담임 선생님을 높이지 않아 어색한 부분은 어디인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X09','K3-2-u4-X11']::text[],false,'{"seq":1,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"스승의 날 일기예요. 지금 담임 선생님을 높이지 않아 어색한 부분은 어디인가요?","options":[{"t":"선생님께서 …… 편지를 주고 오라고 했다.","correct":true},{"t":"작년 담임 선생님께 편지를 썼다.","mis":"K3-2-u4-X06"},{"t":"스승의 날을 맞이해","mis":"K3-2-u4-X09"},{"t":"뿌듯한 마음이 들었다.","mis":"K3-2-u4-X11"}],"explanation":["‘오라고 했다’는 지금 담임 선생님이 하신 말이에요.","선생님을 높이려면 ‘오라고 하셨다’라고 해요.","‘께서’로 시작했으니 끝도 ‘-시-’로 맞추어요."],"asset":{"type":"passage","lines":["5월 15일 ○요일 날씨: 맑음","오늘은 스승의 날을 맞이해 작년 담임 선생님께 편지를 썼다.","편지를 다 쓰고 선생님께서 작년 담임 선생님께 편지를 주고 오라고 했다.","나랑 현승이는 작년에 같은 반이었기 때문에","함께 작년 담임 선생님에게 편지를 주고 왔다.","선생님이 기뻐하는 모습을 보니 뿌듯한 마음이 들었다."],"title":"어느 날의 일기 — 높임 표현을 살펴보아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_challenge#2','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C5',2,'mc','auto','일기의 「함께 작년 담임 선생님에게 편지를 주고 왔다.」를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X11','K3-2-u4-X08']::text[],false,'{"seq":2,"concept":"K3-2-u4-C5","difficulty":2,"kind":"mc","stem":"일기의 「함께 작년 담임 선생님에게 편지를 주고 왔다.」를 바르게 고친 것은 무엇인가요?","options":[{"t":"함께 작년 담임 선생님께 편지를 드리고 왔다.","correct":true},{"t":"함께 작년 담임 선생님께서 편지를 주고 왔다.","mis":"K3-2-u4-X06"},{"t":"함께 작년 담임 선생님에게 편지를 주시고 왔다.","mis":"K3-2-u4-X11"},{"t":"함께 작년 담임 선생님한테 편지를 주고 왔어요.","mis":"K3-2-u4-X08"}],"explanation":["편지를 받는 분이 작년 담임 선생님이에요.","‘에게’ 대신 ‘께’, ‘주다’ 대신 ‘드리다’를 써요.","편지를 주는 사람은 나라서 ‘-시-’를 넣지 않아요."],"asset":{"type":"passage","lines":["5월 15일 ○요일 날씨: 맑음","오늘은 스승의 날을 맞이해 작년 담임 선생님께 편지를 썼다.","편지를 다 쓰고 선생님께서 작년 담임 선생님께 편지를 주고 오라고 했다.","나랑 현승이는 작년에 같은 반이었기 때문에","함께 작년 담임 선생님에게 편지를 주고 왔다.","선생님이 기뻐하는 모습을 보니 뿌듯한 마음이 들었다."],"title":"어느 날의 일기 — 높임 표현을 살펴보아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_challenge#3','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C7',3,'ox','auto','『국어』 185쪽 2번 반응이에요. 「민수가 ‘가?’ 대신 ‘가요?’라고 한 것은 할아버지를 높이기 위해서야.」는 알맞은 반응이에요.',ARRAY['K3-2-u4-X08']::text[],false,'{"seq":3,"concept":"K3-2-u4-C7","difficulty":3,"kind":"ox","stem":"『국어』 185쪽 2번 반응이에요. 「민수가 ‘가?’ 대신 ‘가요?’라고 한 것은 할아버지를 높이기 위해서야.」는 알맞은 반응이에요.","answer":"X","reason_options":[{"t":"‘가요?’의 ‘요’는 민수의 말을 듣는 아버지를 높여요.","correct":true},{"t":"‘요’는 말 속에 나오는 할아버지를 높여요.","mis":"K3-2-u4-X08"}],"mis":"K3-2-u4-X08","explanation":["민수는 아버지께 묻고 있어요.","말끝의 ‘요’는 듣는 사람을 높이는 방법이에요.","할아버지는 ‘께서’와 ‘오시는’, ‘모시러’로 높였어요."],"asset":{"type":"speech","turns":[{"who":"민수","text":"“아버지, 오늘 할아버지께서 오시는 날이지요? 누가 모시러 가요?”"},{"who":"아버지","text":"“응, 누나가 이미 출발했어. 할아버지께 미리 연락을 드렸대.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_challenge#4','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C6',3,'error','auto','세 친구가 높임의 뜻이 있는 낱말 짝을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X36','K3-2-u4-X07']::text[],false,'{"seq":4,"concept":"K3-2-u4-C6","difficulty":3,"kind":"error","stem":"세 친구가 높임의 뜻이 있는 낱말 짝을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서진: ‘생신’이 본래 낱말이고, ‘생일’이 높임의 뜻이 있는 낱말이야.","correct":true,"mis_target":"K3-2-u4-X36"},{"t":"도하: ‘나이’를 높이면 ‘연세’야.","mis":"K3-2-u4-X07"},{"t":"유나: ‘이름’을 높이면 ‘성함’이야.","mis":"K3-2-u4-X07"}],"explanation":["‘생일’이 본래 낱말이고 ‘생신’이 높임의 뜻이 있는 낱말이에요.","나이-연세, 이름-성함처럼 웃어른께 쓰는 쪽이 높임 낱말이에요.","짝의 방향을 거꾸로 알지 않게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_challenge#5','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C8',3,'mc','auto','「할아버지가 편찮으시다.」는 높임 표현이 어색해요. 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X35','K3-2-u4-X10','K3-2-u4-X06']::text[],false,'{"seq":5,"concept":"K3-2-u4-C8","difficulty":3,"kind":"mc","stem":"「할아버지가 편찮으시다.」는 높임 표현이 어색해요. 바르게 고친 것은 무엇인가요?","options":[{"t":"할아버지께서 편찮으시다.","correct":true},{"t":"할아버지가 아프시다.","mis":"K3-2-u4-X35"},{"t":"할아버지께서 아프다.","mis":"K3-2-u4-X10"},{"t":"할아버지께 편찮으시다.","mis":"K3-2-u4-X06"}],"explanation":["높임의 뜻이 있는 ‘편찮으시다’를 썼어요.","이런 낱말은 대부분 ‘께서’와 함께 써요.","‘할아버지가’를 ‘할아버지께서’로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_challenge#6','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C6',3,'mc','auto','『국어활동』 58쪽이에요. “이 내용은 선생님께 여쭈어보자.”에서 높임을 표현한 방법을 보기에서 모두 고른 것은 무엇인가요?',ARRAY['K3-2-u4-X08','K3-2-u4-X05','K3-2-u4-X07']::text[],false,'{"seq":6,"concept":"K3-2-u4-C6","difficulty":3,"kind":"mc","stem":"『국어활동』 58쪽이에요. “이 내용은 선생님께 여쭈어보자.”에서 높임을 표현한 방법을 보기에서 모두 고른 것은 무엇인가요?","options":[{"t":"③, ④","correct":true},{"t":"①, ②","mis":"K3-2-u4-X08"},{"t":"②, ④","mis":"K3-2-u4-X05"},{"t":"①, ③","mis":"K3-2-u4-X07"}],"explanation":["‘께’는 ③ ‘께서’나 ‘께’를 사용한 방법이에요.","‘여쭈어보다’는 ④ 높임의 뜻이 있는 낱말이에요.","말끝은 ‘-자’라서 ①은 쓰지 않았어요."],"asset":{"type":"passage","lines":["① 높임을 나타내는 ‘-습니다’나 ‘요’를 사용한다.","② 높임을 나타내는 ‘-시-’를 사용한다.","③ 높임을 나타내는 ‘께서’나 ‘께’를 사용한다.","④ 높임의 뜻이 있는 낱말을 사용한다.","[그림 1] 손자가 할아버지께 달려가며 — “할아버지, 그동안 잘 지내셨어요?”","[그림 2] 공부하던 친구가 짝에게 — “이 내용은 선생님께 여쭈어보자.”"],"title":"『국어활동』 58쪽 실력 키우기 1"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_challenge#7','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C4',3,'mc','auto','『국어활동』 58쪽이에요. “할아버지, 그동안 잘 지내셨어요?”에서 높임을 표현한 방법을 보기에서 모두 고른 것은 무엇인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X08','K3-2-u4-X05']::text[],false,'{"seq":7,"concept":"K3-2-u4-C4","difficulty":3,"kind":"mc","stem":"『국어활동』 58쪽이에요. “할아버지, 그동안 잘 지내셨어요?”에서 높임을 표현한 방법을 보기에서 모두 고른 것은 무엇인가요?","options":[{"t":"①, ②","correct":true},{"t":"③, ④","mis":"K3-2-u4-X06"},{"t":"②만","mis":"K3-2-u4-X08"},{"t":"①만","mis":"K3-2-u4-X05"}],"explanation":["‘지내셨어요’에는 ‘-시-’가 들어 있어요(②).","말끝에 ‘요’를 붙였어요(①).","‘께서’나 높임 낱말은 쓰지 않았어요."],"asset":{"type":"passage","lines":["① 높임을 나타내는 ‘-습니다’나 ‘요’를 사용한다.","② 높임을 나타내는 ‘-시-’를 사용한다.","③ 높임을 나타내는 ‘께서’나 ‘께’를 사용한다.","④ 높임의 뜻이 있는 낱말을 사용한다.","[그림 1] 손자가 할아버지께 달려가며 — “할아버지, 그동안 잘 지내셨어요?”","[그림 2] 공부하던 친구가 짝에게 — “이 내용은 선생님께 여쭈어보자.”"],"title":"『국어활동』 58쪽 실력 키우기 1"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_challenge#8','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C6',4,'blank','auto','지운이의 쪽지에서 친구가 「‘먹으면’ 대신에 (     )을/를 사용했어.」라고 말했어요. 빈칸에 들어갈 말은 무엇인가요?',ARRAY['K3-2-u4-X35','K3-2-u4-X07','K3-2-u4-X08']::text[],false,'{"seq":8,"concept":"K3-2-u4-C6","difficulty":4,"kind":"blank","stem":"지운이의 쪽지에서 친구가 「‘먹으면’ 대신에 (     )을/를 사용했어.」라고 말했어요. 빈칸에 들어갈 말은 무엇인가요?","options":[{"t":"잡수시면","correct":true},{"t":"먹으시면","mis":"K3-2-u4-X35"},{"t":"드리면","mis":"K3-2-u4-X07"},{"t":"먹으면요","mis":"K3-2-u4-X08"}],"explanation":["떡을 먹을 분은 할머니, 할아버지예요.","‘먹다’에는 높임의 뜻이 있는 낱말 ‘잡수시다’가 따로 있어요.","‘-시-’만 붙인 ‘먹으시면’보다 ‘잡수시면’이 알맞아요."],"asset":{"type":"passage","lines":["할머니, 할아버지께","안녕하세요?","저는 옆집에 이사 온 김지운입니다.","직접 인사하고 싶었지만 집에 안 계셔서 이렇게 쪽지를 남겨요.","이건 저희 부모님께서 할머니, 할아버지께 드리는 떡이세요.","맛있게 잡수시면 좋겠어요.","안녕히 계세요.","김지운 올림"],"title":"지운이가 쓴 쪽지 — 『국어』 187쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_challenge#9','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C9',4,'essay','teacher','종수와 윤아 어머니의 대화에서 높임 표현이 잘못 사용된 부분을 두 군데 찾아 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C9","difficulty":4,"kind":"essay","stem":"종수와 윤아 어머니의 대화에서 높임 표현이 잘못 사용된 부분을 두 군데 찾아 바르게 고쳐 쓰세요.","answer_guide":{"answer":"① “윤아 어머니, 한번 먹어 볼래요?” → “윤아 어머니, 한번 드셔 보시겠어요?” ② “우리 엄마가 만들었어요.” → “우리 엄마께서 만드셨어요.”","scoring_points":["잘못된 부분 두 군데를 바르게 찾았는가","‘먹다’를 높임의 뜻이 있는 낱말(드시다·잡수시다)로 고쳤는가","‘께서’와 ‘-시-’를 써서 엄마를 높였는가"]},"explanation":["높임의 대상이 누구인지 먼저 찾아요.","떡을 먹을 분은 윤아 어머니, 떡을 만든 분은 종수 엄마예요.","‘드시다’, ‘께서’, ‘-시-’를 써서 고쳐요."],"asset":{"type":"speech","turns":[{"who":"상황","text":"종수가 길을 걸어가다가 윤아와 윤아 어머니를 만났어요."},{"who":"종수","text":"“윤아야, 안녕? 윤아 어머니, 안녕하세요?”"},{"who":"윤아","text":"“종수야, 안녕? 너 손에 들고 있는 건 뭐니?”"},{"who":"종수","text":"“아, 이건 떡이야. 윤아 어머니, 한번 먹어 볼래요?”"},{"who":"윤아 어머니","text":"“종수야, 고맙구나. 누가 만든 거니?”"},{"who":"종수","text":"“우리 엄마가 만들었어요.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L03_challenge#10','kor',3,2,'u4','L03','tb_g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C8',4,'mc','auto','「선생님께서 하시는 일이 잘되셨으면 좋겠어요.」는 써도 되지만, 「주문하신 커피 나오셨습니다.」는 잘못이에요. 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X10','K3-2-u4-X05']::text[],false,'{"seq":10,"concept":"K3-2-u4-C8","difficulty":4,"kind":"mc","stem":"「선생님께서 하시는 일이 잘되셨으면 좋겠어요.」는 써도 되지만, 「주문하신 커피 나오셨습니다.」는 잘못이에요. 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"앞은 선생님께서 하시는 일이라 선생님을 높이는 것이지만, 뒤는 커피라는 물건 자체를 높였기 때문","correct":true},{"t":"둘 다 맞다 — 높임은 많이 붙일수록 공손하기 때문","mis":"K3-2-u4-X09"},{"t":"둘 다 틀렸다 — 사람이 아닌 낱말 뒤에는 높임을 쓰지 않기 때문","mis":"K3-2-u4-X10"},{"t":"앞은 일, 뒤는 커피라서 둘 다 사람을 높였기 때문","mis":"K3-2-u4-X05"}],"explanation":["‘일’은 선생님께서 하시는 것이라 선생님과 이어져 있어요.","커피는 손님과 상관없이 물건 그 자체예요.","물건을 높이는 ‘-시-’는 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_basic#1','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C2',1,'mc','auto','「아드님, 진지 드세요」 제목 속 ‘진지’는 무슨 뜻인가요?',ARRAY['K3-2-u4-X07','K3-2-u4-X36']::text[],false,'{"seq":1,"concept":"K3-2-u4-C2","difficulty":1,"kind":"mc","stem":"「아드님, 진지 드세요」 제목 속 ‘진지’는 무슨 뜻인가요?","options":[{"t":"‘밥’을 높여 이르는 말","correct":true},{"t":"장난이 아니라 참된 마음","mis":"K3-2-u4-X07"},{"t":"‘밥’보다 낮추어 이르는 말","mis":"K3-2-u4-X36"},{"t":"아침에 먹는 간식","mis":"K3-2-u4-X07"}],"explanation":["“밥 먹으세요.”와 “진지 드세요.”를 견주어 보아요.","‘진지’는 웃어른께 쓰는 ‘밥’의 높임말이에요.","‘먹다’도 ‘드시다’로 높였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_basic#2','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C2',1,'mc','auto','『국어』 195쪽 내용 알기예요. 범수의 반말을 고치려고 엄마와 할머니께서는 어떻게 하셨나요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":2,"concept":"K3-2-u4-C2","difficulty":1,"kind":"mc","stem":"『국어』 195쪽 내용 알기예요. 범수의 반말을 고치려고 엄마와 할머니께서는 어떻게 하셨나요?","options":[{"t":"비밀 모의를 하고 범수에게 높임말을 쓰셨다","correct":true},{"t":"범수의 용돈을 줄이셨다","mis":"K3-2-u4-X33"},{"t":"범수를 크게 꾸중하셨다","mis":"K3-2-u4-X33"},{"t":"범수에게 반말을 더 많이 쓰셨다","mis":"K3-2-u4-X33"}],"explanation":["엄마는 할머니와 속닥속닥 비밀 모의를 했어요.","그리고 범수를 “아드님”, “손자님”이라고 부르며 높임말을 썼어요.","범수가 스스로 깨닫게 하려는 특별한 방법이었어요."],"asset":{"type":"passage","lines":["(간추림) 범수가 반말을 고치지 않자 엄마는 할머니와 비밀 모의를 했다.","“아드님, 학교 다녀오시느라 힘드셨지요?”","“손자님! 가방은 제가 정리할게요.”","(간추림) 범수는 왕자가 된 것 같아 엄마의 높임말을 계속 받기로 했다."],"title":"「아드님, 진지 드세요」 비밀 모의 — 『국어』 189~190쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_basic#3','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C2',1,'mc','auto','마트로 향하는 범수의 발걸음이 통통 튀어 오른 까닭은 무엇인가요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":3,"concept":"K3-2-u4-C2","difficulty":1,"kind":"mc","stem":"마트로 향하는 범수의 발걸음이 통통 튀어 오른 까닭은 무엇인가요?","options":[{"t":"엄마와 할머니께서 높임말을 해 주시니 왕자가 된 것처럼 기분이 좋았기 때문","correct":true},{"t":"마트에서 과자를 많이 샀기 때문","mis":"K3-2-u4-X33"},{"t":"엄마가 다시 반말을 해 주었기 때문","mis":"K3-2-u4-X33"},{"t":"태권도장에 늦지 않았기 때문","mis":"K3-2-u4-X33"}],"explanation":["범수는 높임말을 듣고 왕자가 된 것 같았어요.","구름 위를 오른 듯 붕붕 뜬 느낌이었어요.","그래서 발걸음이 하늘에 닿을 듯 통통 튀어 올랐어요."],"asset":{"type":"passage","lines":["(간추림) 범수가 반말을 고치지 않자 엄마는 할머니와 비밀 모의를 했다.","“아드님, 학교 다녀오시느라 힘드셨지요?”","“손자님! 가방은 제가 정리할게요.”","(간추림) 범수는 왕자가 된 것 같아 엄마의 높임말을 계속 받기로 했다."],"title":"「아드님, 진지 드세요」 비밀 모의 — 『국어』 189~190쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_basic#4','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C2',1,'sa','auto','이야기 끝에서 범수는 엄마와 할머니께 무엇을 약속했나요? 짧게 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u4-C2","difficulty":1,"kind":"sa","stem":"이야기 끝에서 범수는 엄마와 할머니께 무엇을 약속했나요? 짧게 쓰세요.","answer":["누구에게나 높임말을 잘 쓰겠다","높임말을 잘 쓰겠다","누구에게나 높임말을 잘 쓰겠다고 약속했다","높임말을 잘 쓰겠다고","높임말 잘 쓰기"],"explanation":["엄마가 “그럼 약속하세요.”라고 말했어요.","범수는 새끼손가락을 걸고 약속했어요.","누구에게나 높임말을 잘 쓰겠다는 약속이에요."],"asset":{"type":"passage","lines":["“그럼 약속하세요. 이제부터 누구에게나 높임말을 잘 쓰겠다고요.”","“약속할게……요. 앞으로 높임말 잘 쓸게……요.”","(간추림) 엄마가 해 주는 ‘아들’이란 말이 달콤하게 들렸고,","(간추림) 엄마가 해 주는 반말이 푹신한 솜이불처럼 편안했다."],"title":"「아드님, 진지 드세요」 마지막 장면 — 『국어』 194쪽"},"mis":"K3-2-u4-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_basic#5','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C12',2,'match','auto','『국어』 195쪽 낱말 알기예요. 두 낱말 사이의 관계를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u4-C12","difficulty":2,"kind":"match","stem":"『국어』 195쪽 낱말 알기예요. 두 낱말 사이의 관계를 알맞게 이으세요.","pairs":[{"l":"식탁 — 가구","r":"한 낱말이 다른 낱말의 뜻을 포함하는 관계"},{"l":"고치다 — 바로잡다","r":"서로 뜻이 비슷한 관계"},{"l":"가르치다 — 배우다","r":"서로 뜻이 반대인 관계"}],"mis":"K3-2-u4-X15","explanation":["식탁은 가구 가운데 하나예요(가구가 식탁을 포함해요).","‘고치다’와 ‘바로잡다’는 뜻이 비슷해요.","‘가르치다’와 ‘배우다’는 뜻이 반대예요."],"asset":{"type":"passage","lines":["범수는 식탁에서 벌떡 일어났어요.","범수는 반말을 고치고 싶은 마음이 전혀 없었어요.","“우리 범수가 이참에 단단히 배우겠구먼.”"],"title":"「아드님, 진지 드세요」 낱말 알기 — 『국어』 195쪽","hi":["식탁","고치고","배우겠구먼"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_basic#6','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C2',2,'mc','auto','이야기의 흐름에 따라 범수의 마음은 어떻게 바뀌었나요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":6,"concept":"K3-2-u4-C2","difficulty":2,"kind":"mc","stem":"이야기의 흐름에 따라 범수의 마음은 어떻게 바뀌었나요?","options":[{"t":"어색함 → 왕자가 된 듯 좋음 → 창피하고 부끄러움 → 잘못을 뉘우침","correct":true},{"t":"좋음 → 어색함 → 화남 → 좋음","mis":"K3-2-u4-X33"},{"t":"부끄러움 → 어색함 → 좋음 → 화남","mis":"K3-2-u4-X33"},{"t":"처음부터 끝까지 왕자가 된 듯 좋음","mis":"K3-2-u4-X33"}],"explanation":["처음 높임말을 들었을 때는 어색하고 이상했어요.","왕자가 된 것 같아 좋았다가 태권도장에서 창피를 당했어요.","마지막에는 울면서 잘못을 뉘우쳤어요."],"asset":{"type":"passage","lines":["(간추림) ① 아침 — 범수는 엄마에게 짜증을 내며 반말을 했다.","(간추림) ② 학교에서 돌아오니 엄마와 할머니가 높임말을 썼다.","(간추림) ③ 마트 — 모르는 할머니가 범수의 반말을 꾸짖었다.","(간추림) ④ 집 — 좋아하는 떡볶이도 맛이 없었다.","(간추림) ⑤ 태권도장 — 아이들이 놀리자 범수는 뛰쳐나왔다.","(간추림) ⑥ 집 — 범수는 울며 높임말을 잘 쓰겠다고 약속했다."],"title":"「아드님, 진지 드세요」 간추린 흐름 — 『국어』 188~194쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_basic#7','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C9',2,'mc','auto','『국어』 196쪽 장면 ㉮예요. 범수의 말 “밥 안 먹어. 더 잘 거야.”를 높임 표현을 바르게 사용해 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X35','K3-2-u4-X10']::text[],false,'{"seq":7,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"『국어』 196쪽 장면 ㉮예요. 범수의 말 “밥 안 먹어. 더 잘 거야.”를 높임 표현을 바르게 사용해 고친 것은 무엇인가요?","options":[{"t":"“밥은 이따가 먹고 싶어요. 저 조금만 더 잘래요.”","correct":true},{"t":"“밥 안 드셔. 더 주무실 거야.”","mis":"K3-2-u4-X11"},{"t":"“진지 안 먹어. 더 잘 거야.”","mis":"K3-2-u4-X35"},{"t":"“밥 안 먹어. 더 잘 거야, 엄마.”","mis":"K3-2-u4-X10"}],"explanation":["범수가 말하는 상대는 엄마예요.","말끝에 ‘요’를 붙이고 ‘나’ 대신 ‘저’를 써요.","먹고 자는 사람은 범수라서 ‘드시다·주무시다’를 쓰지 않아요."],"asset":{"type":"passage","lines":["“밥 안 먹어. 더 잘 거야.”","“그러다 지각하겠다. 얼른 일어나야지!”"],"title":"「아드님, 진지 드세요」 장면 ㉮ — 『국어』 196쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_basic#8','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C11',2,'mc','auto','『국어』 197쪽이에요. 지호가 효빈이에게 한 말 “효빈아, 선생님이 너 오래.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X14','K3-2-u4-X11']::text[],false,'{"seq":8,"concept":"K3-2-u4-C11","difficulty":2,"kind":"mc","stem":"『국어』 197쪽이에요. 지호가 효빈이에게 한 말 “효빈아, 선생님이 너 오래.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“효빈아, 선생님께서 너 오라고 하셔.”","correct":true},{"t":"“효빈아, 선생님이 너 오시래.”","mis":"K3-2-u4-X14"},{"t":"“효빈님, 선생님이 너 오래요.”","mis":"K3-2-u4-X11"},{"t":"“효빈아, 선생님께서 너 오래.”","mis":"K3-2-u4-X14"}],"explanation":["그 말씀을 처음 하신 분은 선생님이에요.","말을 옮길 때도 ‘께서’와 ‘하셔’로 선생님을 높여요.","말을 옮겨 받는 효빈이는 높이지 않아요."],"asset":{"type":"speech","turns":[{"who":"① 선생님 → 지호","text":"“지호야, 효빈이 좀 교실에 들어오라고 해 줘.”"},{"who":"지호","text":"“네.”"},{"who":"② 지호 → 효빈","text":"“효빈아, 선생님이 너 오래.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_basic#9','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C2',2,'mc','auto','마트에서 처음 보는 할머니가 혀를 차며 호통을 친 까닭은 무엇인가요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":9,"concept":"K3-2-u4-C2","difficulty":2,"kind":"mc","stem":"마트에서 처음 보는 할머니가 혀를 차며 호통을 친 까닭은 무엇인가요?","options":[{"t":"엄마는 아들에게 높임말을 하는데 아들은 엄마에게 반말을 했기 때문","correct":true},{"t":"범수가 마트에서 뛰어다녔기 때문","mis":"K3-2-u4-X33"},{"t":"엄마가 할머니께 반말을 했기 때문","mis":"K3-2-u4-X33"},{"t":"범수가 과자를 너무 많이 골랐기 때문","mis":"K3-2-u4-X33"}],"explanation":["할머니는 엄마와 범수를 번갈아 쳐다보았어요.","엄마는 꼬박꼬박 높임말을, 범수는 반말을 했어요.","그 모습을 보고 꾸짖은 거예요."],"asset":{"type":"passage","lines":["(간추림) 마트에서 처음 보는 머리 하얀 할머니가 혀를 차며 호통을 쳤다.","(간추림) 엄마는 아들에게 높임말을 하는데 아들은 반말을 한다는 것이었다.","(간추림) 범수는 모르는 할머니께 사과하는 엄마가 못마땅해 물었다.","“모르는 분이더라도 어르신이 말씀하시니 귀 기울여 들어야지요.”"],"title":"「아드님, 진지 드세요」 마트 장면 — 『국어』 191~192쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_basic#10','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C2',3,'mc','auto','태권도장에서 돌아온 범수가 “나한테 다시 반말 써.”라고 엄마와 할머니께 사정한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":10,"concept":"K3-2-u4-C2","difficulty":3,"kind":"mc","stem":"태권도장에서 돌아온 범수가 “나한테 다시 반말 써.”라고 엄마와 할머니께 사정한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"친구들이 놀려 창피했고, 엄마에게 반말하는 자신이 부끄러워졌기 때문","correct":true},{"t":"엄마의 높임말이 틀린 말이었기 때문","mis":"K3-2-u4-X33"},{"t":"사범님이 범수를 혼냈기 때문","mis":"K3-2-u4-X33"},{"t":"떡볶이가 맛이 없었기 때문","mis":"K3-2-u4-X33"}],"explanation":["아이들이 “너희 엄마는 네 부하냐?” 하며 놀렸어요.","범수는 얼굴이 빨개지고 엄마가 창피해 눈도 못 마주쳤어요.","자기 반말이 얼마나 이상한지 깨닫고 부끄러워졌어요."],"asset":{"type":"passage","lines":["“사범님, 죄송해요. 우리 범수 아드님이 조금 늦으셨죠?”","(간추림) 아이들이 “너희 엄마는 네 부하냐?” 하며 놀리자 범수는 뛰쳐나왔다.","“엄마, 내가 잘못했어. 나한테 다시 반말 써. 할머니도, 응?”"],"title":"「아드님, 진지 드세요」 태권도장 장면 — 『국어』 193쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_challenge#1','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C12',2,'mc','auto','‘식탁 — 가구’처럼 한 낱말이 다른 낱말의 뜻을 포함하는 관계인 것은 무엇인가요?',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":1,"concept":"K3-2-u4-C12","difficulty":2,"kind":"mc","stem":"‘식탁 — 가구’처럼 한 낱말이 다른 낱말의 뜻을 포함하는 관계인 것은 무엇인가요?","options":[{"t":"사과 — 과일","correct":true},{"t":"크다 — 작다","mis":"K3-2-u4-X15"},{"t":"돕다 — 거들다","mis":"K3-2-u4-X15"},{"t":"묻다 — 대답하다","mis":"K3-2-u4-X15"}],"explanation":["사과는 과일 가운데 하나예요.","‘과일’이 ‘사과’의 뜻을 포함해요.","크다-작다는 반대, 돕다-거들다는 비슷한 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_challenge#2','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C12',2,'ox','auto','‘가르치다’와 ‘배우다’는 서로 뜻이 비슷한 관계예요.',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":2,"concept":"K3-2-u4-C12","difficulty":2,"kind":"ox","stem":"‘가르치다’와 ‘배우다’는 서로 뜻이 비슷한 관계예요.","answer":"X","reason_options":[{"t":"‘가르치다’와 ‘배우다’는 서로 뜻이 반대인 관계예요.","correct":true},{"t":"둘 다 공부와 관련된 말이니 뜻이 비슷해요.","mis":"K3-2-u4-X15"}],"mis":"K3-2-u4-X15","explanation":["가르치는 사람이 있으면 배우는 사람이 있어요.","두 낱말은 서로 뜻이 반대예요.","할머니는 “범수가 이참에 단단히 배우겠구먼.”이라고 했어요."],"asset":{"type":"passage","lines":["범수는 식탁에서 벌떡 일어났어요.","범수는 반말을 고치고 싶은 마음이 전혀 없었어요.","“우리 범수가 이참에 단단히 배우겠구먼.”"],"title":"「아드님, 진지 드세요」 낱말 알기 — 『국어』 195쪽","hi":["식탁","고치고","배우겠구먼"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_challenge#3','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C9',3,'mc','auto','『국어』 196쪽 장면 ㉰예요. 범수의 말을 높임 표현을 바르게 사용해 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X23','K3-2-u4-X10']::text[],false,'{"seq":3,"concept":"K3-2-u4-C9","difficulty":3,"kind":"mc","stem":"『국어』 196쪽 장면 ㉰예요. 범수의 말을 높임 표현을 바르게 사용해 고친 것은 무엇인가요?","options":[{"t":"“할머니, 잘못했어요. 손자님이라고 부르지 말아 주세요. 그냥 ‘범수’라고 불러 주세요, 네?”","correct":true},{"t":"“할머니께서, 잘못하셨어요. 손자님이라고 부르지 마세요.”","mis":"K3-2-u4-X11"},{"t":"“할머니, 잘못했어. 손자님이라고 부르지 마요. 그냥 ‘범수’라고 해, 응?”","mis":"K3-2-u4-X23"},{"t":"“할머니, 잘못했어. 손자님이라고 부르지 마.”","mis":"K3-2-u4-X10"}],"explanation":["범수가 말하는 상대는 할머니예요.","말끝마다 ‘요’를 붙이고 ‘부르지 마’를 ‘부르지 말아 주세요’로 바꾸어요.","잘못한 사람은 범수라서 ‘잘못하셨어요’라고 하지 않아요."],"asset":{"type":"passage","lines":["“아이고, 우리 손자님 왜 그러세요?”","“할머니, 잘못했어. 손자님이라고 부르지 마. 그냥 ‘범수’라고 해, 응?”"],"title":"「아드님, 진지 드세요」 장면 ㉰ — 『국어』 196쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_challenge#4','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C9',3,'mc','auto','『국어』 196쪽 장면 ㉯예요. 범수의 말 “오늘 저녁 반찬은 뭐야?”와 “떡갈비.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X10','K3-2-u4-X35']::text[],false,'{"seq":4,"concept":"K3-2-u4-C9","difficulty":3,"kind":"mc","stem":"『국어』 196쪽 장면 ㉯예요. 범수의 말 “오늘 저녁 반찬은 뭐야?”와 “떡갈비.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“오늘 저녁 반찬은 뭐예요?”, “떡갈비요.”","correct":true},{"t":"“오늘 저녁 반찬은 뭐세요?”, “떡갈비세요.”","mis":"K3-2-u4-X09"},{"t":"“오늘 저녁 반찬은 뭐니?”, “떡갈비야.”","mis":"K3-2-u4-X10"},{"t":"“오늘 저녁 진지는 뭐야?”, “떡갈비.”","mis":"K3-2-u4-X35"}],"explanation":["범수는 엄마께 묻고 대답해요.","듣는 엄마를 높이려면 ‘뭐예요?’, ‘떡갈비요.’처럼 ‘요’를 붙여요.","반찬은 물건이라 ‘-시-’를 넣지 않아요."],"asset":{"type":"passage","lines":["“오늘 저녁 반찬은 뭐야?”","“아드님은 뭐가 드시고 싶으세요?”","“떡갈비.”"],"title":"「아드님, 진지 드세요」 장면 ㉯ — 『국어』 196쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_challenge#5','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C11',3,'mc','auto','『국어』 197쪽 (3)이에요. 친구가 쉬는 시간에 한 말 “선생님이 조용히 하래.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X14','K3-2-u4-X08']::text[],false,'{"seq":5,"concept":"K3-2-u4-C11","difficulty":3,"kind":"mc","stem":"『국어』 197쪽 (3)이에요. 친구가 쉬는 시간에 한 말 “선생님이 조용히 하래.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“선생님께서 조용히 하라고 하셔.”","correct":true},{"t":"“선생님이 조용히 하시래.”","mis":"K3-2-u4-X14"},{"t":"“선생님께서 조용히 하래.”","mis":"K3-2-u4-X14"},{"t":"“선생님이 조용히 하래요.”","mis":"K3-2-u4-X08"}],"explanation":["조용히 하라고 말씀하신 분은 선생님이에요.","말을 옮길 때도 ‘께서’와 ‘하셔’로 선생님을 높여요.","‘요’는 듣는 친구를 높이는 것이라 선생님을 높이지 못해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"식당에서 “음식 나오셨습니다.”라고 말하는 것을 들었어. 음식도 높임의 대상이 될 수 있을까?"},{"who":"친구 2","text":"쉬는 시간에 친구가 “선생님이 조용히 하래.”라고 말하는 것을 들었어. 잘못된 표현인 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_challenge#6','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C9',3,'ox','auto','식당에서 들은 “음식 나오셨습니다.”처럼 음식도 높임의 대상이 될 수 있어요.',ARRAY['K3-2-u4-X09']::text[],false,'{"seq":6,"concept":"K3-2-u4-C9","difficulty":3,"kind":"ox","stem":"식당에서 들은 “음식 나오셨습니다.”처럼 음식도 높임의 대상이 될 수 있어요.","answer":"X","reason_options":[{"t":"음식은 물건이라 높임의 대상이 아니에요. “음식 나왔습니다.”라고 해요.","correct":true},{"t":"손님이 먹을 음식이니 음식도 높여야 공손해요.","mis":"K3-2-u4-X09"}],"mis":"K3-2-u4-X09","explanation":["높임의 대상은 사람이에요.","음식이나 커피 같은 물건에는 ‘-시-’를 붙이지 않아요.","“주문하신 음식 나왔습니다.”라고 바르게 말해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"식당에서 “음식 나오셨습니다.”라고 말하는 것을 들었어. 음식도 높임의 대상이 될 수 있을까?"},{"who":"친구 2","text":"쉬는 시간에 친구가 “선생님이 조용히 하래.”라고 말하는 것을 들었어. 잘못된 표현인 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_challenge#7','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C2',3,'mc','auto','마트에서 엄마는 “모르는 분이더라도 어르신이 말씀하시니 귀 기울여 들어야지요.”라고 했어요. 이 말에서 알 수 있는 엄마의 태도는 무엇인가요?',ARRAY['K3-2-u4-X33','K3-2-u4-X16']::text[],false,'{"seq":7,"concept":"K3-2-u4-C2","difficulty":3,"kind":"mc","stem":"마트에서 엄마는 “모르는 분이더라도 어르신이 말씀하시니 귀 기울여 들어야지요.”라고 했어요. 이 말에서 알 수 있는 엄마의 태도는 무엇인가요?","options":[{"t":"모르는 분이라도 웃어른의 말씀을 존중하며 듣는 태도","correct":true},{"t":"모르는 사람의 말은 듣지 않아도 된다는 태도","mis":"K3-2-u4-X33"},{"t":"어르신이 시키는 일은 무엇이든 다 해야 한다는 태도","mis":"K3-2-u4-X16"},{"t":"범수에게 높임말 쓰기를 그만두겠다는 태도","mis":"K3-2-u4-X33"}],"explanation":["엄마는 할머니께 혼나고도 공손하게 사과했어요.","모르는 분이어도 웃어른의 말씀을 귀 기울여 들었어요.","말을 존중하며 듣는 것도 높임 표현에 담긴 마음이에요."],"asset":{"type":"passage","lines":["(간추림) 마트에서 처음 보는 머리 하얀 할머니가 혀를 차며 호통을 쳤다.","(간추림) 엄마는 아들에게 높임말을 하는데 아들은 반말을 한다는 것이었다.","(간추림) 범수는 모르는 할머니께 사과하는 엄마가 못마땅해 물었다.","“모르는 분이더라도 어르신이 말씀하시니 귀 기울여 들어야지요.”"],"title":"「아드님, 진지 드세요」 마트 장면 — 『국어』 191~192쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_challenge#8','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C9',4,'essay','teacher','『국어』 196쪽 (2)예요. 장면 ㉮~㉰ 가운데에서 하나를 골라 잘못된 높임 표현과 바르게 고친 표현을 함께 쓰고, 고친 말을 들은 상대의 마음이 어떻게 달라질지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u4-C9","difficulty":4,"kind":"essay","stem":"『국어』 196쪽 (2)예요. 장면 ㉮~㉰ 가운데에서 하나를 골라 잘못된 높임 표현과 바르게 고친 표현을 함께 쓰고, 고친 말을 들은 상대의 마음이 어떻게 달라질지 쓰세요.","answer_guide":{"answer":"예: 장면 ㉰ — 잘못된 표현 “할머니, 잘못했어. 손자님이라고 부르지 마.” → 바른 표현 “할머니, 잘못했어요. 손자님이라고 부르지 말아 주세요.” 할머니는 범수가 진심으로 뉘우친다고 느껴 기쁘고 마음이 놓이실 것이다.","scoring_points":["장면 하나를 골라 잘못된 높임 표현을 썼는가","높임 표현을 바르게 사용해 고쳐 썼는가","고친 말을 들은 상대의 마음을 짐작해 썼는가"]},"explanation":["먼저 범수가 누구에게 말하는지 찾아요.","듣는 사람을 높이는 ‘요’, 높임의 뜻이 있는 낱말을 떠올려 고쳐요.","높임 표현을 듣는 상대의 마음을 짐작하며 표현해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_challenge#9','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C2',4,'essay','teacher','「아드님, 진지 드세요」를 읽고 높임 표현을 바르게 사용해야 하는 까닭을 쓰고, 자신의 언어생활에서 고치고 싶은 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C2","difficulty":4,"kind":"essay","stem":"「아드님, 진지 드세요」를 읽고 높임 표현을 바르게 사용해야 하는 까닭을 쓰고, 자신의 언어생활에서 고치고 싶은 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 높임 표현을 바르게 쓰지 않으면 듣는 사람이 존중받지 못한다고 느껴 마음이 상하고, 다른 사람들도 이상하게 본다. 나는 집에서 엄마께 짜증이 나면 반말을 하는데, 앞으로는 “엄마, 잠깐만 기다려 주세요.”처럼 높임 표현을 쓰겠다.","scoring_points":["높임 표현을 바르게 써야 하는 까닭을 이야기와 이어 썼는가","자신의 언어생활에서 고칠 점을 구체적으로 썼는가","고친 말의 예를 높임 표현에 맞게 썼는가"]},"explanation":["범수가 반말을 할 때 엄마와 할머니의 마음을 떠올려요.","마트·태권도장에서 다른 사람들의 반응도 생각해요.","나의 말버릇을 돌아보며 고칠 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L05_challenge#10','kor',3,2,'u4','L05','tb_g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C10',4,'mc','auto','범수는 약속하며 “약속할게……요. 앞으로 높임말 잘 쓸게……요.”라고 말끝을 머뭇거렸어요. 이 말에서 짐작할 수 있는 범수의 마음으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X12','K3-2-u4-X13','K3-2-u4-X33']::text[],false,'{"seq":10,"concept":"K3-2-u4-C10","difficulty":4,"kind":"mc","stem":"범수는 약속하며 “약속할게……요. 앞으로 높임말 잘 쓸게……요.”라고 말끝을 머뭇거렸어요. 이 말에서 짐작할 수 있는 범수의 마음으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"아직 서툴고 어색하지만 높임말을 쓰려고 애쓰는 마음","correct":true},{"t":"높임말이 틀릴까 봐 아예 말하지 않으려는 마음","mis":"K3-2-u4-X12"},{"t":"한 글자도 틀리지 않아야 해서 부끄러운 마음","mis":"K3-2-u4-X13"},{"t":"엄마를 놀리려는 장난스러운 마음","mis":"K3-2-u4-X33"}],"explanation":["범수는 늘 반말을 해서 높임말이 아직 어색해요.","그래도 ‘요’를 붙여 높임말을 쓰려고 애썼어요.","서툴러도 말을 건네는 마음이 중요해요."],"asset":{"type":"passage","lines":["“그럼 약속하세요. 이제부터 누구에게나 높임말을 잘 쓰겠다고요.”","“약속할게……요. 앞으로 높임말 잘 쓸게……요.”","(간추림) 엄마가 해 주는 ‘아들’이란 말이 달콤하게 들렸고,","(간추림) 엄마가 해 주는 반말이 푹신한 솜이불처럼 편안했다."],"title":"「아드님, 진지 드세요」 마지막 장면 — 『국어』 194쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_basic#1','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C14',1,'sa','auto','『국어』 198쪽 「효진이와 소영이의 부탁」이에요. 효진이가 동호를 부를 때 쓴 말을 그대로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C14","difficulty":1,"kind":"sa","stem":"『국어』 198쪽 「효진이와 소영이의 부탁」이에요. 효진이가 동호를 부를 때 쓴 말을 그대로 쓰세요.","answer":["야","야!","야! 이 책 좀 들어 봐"],"explanation":["효진이는 “야! 이 책 좀 들어 봐.”라고 했어요.","소영이는 “동호야.” 하고 이름을 불렀어요.","부르는 말에서부터 예절이 드러나요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"효진이는 책을 반납하러 가는 길이었어요. 책이 많아 혼자 들기 힘들었는데 마침 동호가 보였어요."},{"who":"효진","text":"“야! 이 책 좀 들어 봐.”"},{"who":"동호","text":"“나?”"},{"who":"효진","text":"(짜증 내며) “빨리 좀 들어 봐!”"},{"who":"동호","text":"(퉁명스레) “내가 왜? 나 바빠.”"}]},"mis":"K3-2-u4-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_basic#2','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C14',1,'mc','auto','효진이의 말을 들은 동호의 표정과 대답으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X27']::text[],false,'{"seq":2,"concept":"K3-2-u4-C14","difficulty":1,"kind":"mc","stem":"효진이의 말을 들은 동호의 표정과 대답으로 알맞은 것은 무엇인가요?","options":[{"t":"화난 표정 — “내가 왜? 나 바빠.”","correct":true},{"t":"웃는 표정 — “응, 알았어.”","mis":"K3-2-u4-X18"},{"t":"신난 표정 — “물론이지!”","mis":"K3-2-u4-X18"},{"t":"아무 표정 없이 — “그래.”","mis":"K3-2-u4-X27"}],"explanation":["효진이는 짜증 내며 “빨리 좀 들어 봐!”라고 했어요.","동호는 퉁명스레 “내가 왜? 나 바빠.”라고 대답했어요.","말하는 태도가 듣는 사람의 기분을 바꾸어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"효진이는 책을 반납하러 가는 길이었어요. 책이 많아 혼자 들기 힘들었는데 마침 동호가 보였어요."},{"who":"효진","text":"“야! 이 책 좀 들어 봐.”"},{"who":"동호","text":"“나?”"},{"who":"효진","text":"(짜증 내며) “빨리 좀 들어 봐!”"},{"who":"동호","text":"(퉁명스레) “내가 왜? 나 바빠.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_basic#3','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C13',1,'mc','auto','『국어』 200쪽 정리예요. 대화 예절의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X16','K3-2-u4-X17']::text[],false,'{"seq":3,"concept":"K3-2-u4-C13","difficulty":1,"kind":"mc","stem":"『국어』 200쪽 정리예요. 대화 예절의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"말하는 이와 듣는 이가 서로 말을 주고받을 때 지켜야 할 예절","correct":true},{"t":"웃어른과 이야기할 때만 지키는 예절","mis":"K3-2-u4-X02"},{"t":"남의 부탁을 모두 들어주는 것","mis":"K3-2-u4-X16"},{"t":"되도록 말을 하지 않는 것","mis":"K3-2-u4-X17"}],"explanation":["대화 예절은 말을 주고받을 때 지키는 예절이에요.","친구와도, 웃어른과도 지켜요.","상대를 배려하고 존중하려는 마음가짐이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_basic#4','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C13',1,'ox','auto','대화할 때에는 상대를 배려하고 존중하려는 마음가짐이 중요해요.',ARRAY['K3-2-u4-X18']::text[],false,'{"seq":4,"concept":"K3-2-u4-C13","difficulty":1,"kind":"ox","stem":"대화할 때에는 상대를 배려하고 존중하려는 마음가짐이 중요해요.","answer":"O","reason_options":[{"t":"『국어』 200쪽 정리에 상대를 배려하고 존중하려는 마음가짐이 중요하다고 했어요.","correct":true},{"t":"말의 내용만 맞으면 마음가짐은 상관없어요.","mis":"K3-2-u4-X18"}],"mis":"K3-2-u4-X18","explanation":["같은 부탁도 마음가짐에 따라 말이 달라져요.","배려하는 마음은 부르는 말·말투·표정에 드러나요.","그래서 대화 예절의 첫출발은 존중하는 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_basic#5','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C14',2,'mc','auto','『국어』 199쪽 (3)이에요. 효진이와 소영이의 말을 듣고 동호의 반응이 달랐던 까닭은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X33']::text[],false,'{"seq":5,"concept":"K3-2-u4-C14","difficulty":2,"kind":"mc","stem":"『국어』 199쪽 (3)이에요. 효진이와 소영이의 말을 듣고 동호의 반응이 달랐던 까닭은 무엇인가요?","options":[{"t":"효진이는 동호를 존중하지 않고 말했지만, 소영이는 동호를 배려하며 조심스럽게 부탁했기 때문","correct":true},{"t":"효진이의 책이 소영이의 책보다 더 많았기 때문","mis":"K3-2-u4-X18"},{"t":"동호가 소영이와 더 친하기 때문","mis":"K3-2-u4-X18"},{"t":"동호가 처음에는 기분이 나빴다가 나중에 좋아졌기 때문","mis":"K3-2-u4-X33"}],"explanation":["두 사람의 부탁 내용은 책을 들어 달라는 것으로 같아요.","효진이는 “야!”, 소영이는 “동호야, 지금 바빠?”라고 했어요.","부르는 말, 부탁하는 말, 말하는 태도가 달랐어요."],"asset":{"type":"speech","turns":[{"who":"소영","text":"“동호야, 지금 바빠? 이 책 좀 같이 들어 줄 수 있어?”"},{"who":"동호","text":"“응, 알았어. 그런데 나 지금 선생님 심부름 가는 길인데, 저기 계단까지만 들어 줘도 될까?”"},{"who":"소영","text":"“물론이지. 도와줘서 고마워.”"},{"who":"효진","text":"“왜 내 건 안 들어 주고 소영이 것만 들어 줘?”"},{"who":"동호","text":"“나는 네가 나한테 짜증만 내고 명령하듯이 말해서 들어 주고 싶지 않았어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_basic#6','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C13',2,'mc','auto','속담 「가는 말이 고와야 오는 말이 곱다」를 대화와 관련지어 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X04','K3-2-u4-X27']::text[],false,'{"seq":6,"concept":"K3-2-u4-C13","difficulty":2,"kind":"mc","stem":"속담 「가는 말이 고와야 오는 말이 곱다」를 대화와 관련지어 바르게 말한 것은 무엇인가요?","options":[{"t":"내가 상대를 존중하며 말해야 상대도 나를 존중하며 말한다","correct":true},{"t":"말은 크게 해야 상대가 잘 알아듣는다","mis":"K3-2-u4-X21"},{"t":"말은 길고 어려운 낱말을 써야 곱다","mis":"K3-2-u4-X04"},{"t":"내가 어떻게 말하든 상대의 대답은 똑같다","mis":"K3-2-u4-X27"}],"explanation":["고운 말을 하면 상대도 고운 말로 대답해요.","효진이와 소영이의 이야기도 그랬어요.","어떻게 말하느냐에 따라 상대의 반응이 달라져요."],"asset":{"type":"passage","lines":["㉮ 가는 말이 고와야 오는 말이 곱다","㉯ 말 한마디에 천 냥 빚도 갚는다","㉰ 쌀은 쏟고 주워도 말은 하고 못 줍는다","㉱ 아 해 다르고 어 해 다르다"],"title":"대화와 관련된 속담"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_basic#7','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C13',2,'match','auto','대화와 관련된 속담과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u4-C13","difficulty":2,"kind":"match","stem":"대화와 관련된 속담과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"가는 말이 고와야 오는 말이 곱다","r":"내가 고운 말을 해야 남도 나에게 고운 말을 한다"},{"l":"말 한마디에 천 냥 빚도 갚는다","r":"말만 잘해도 어려운 일을 풀 수 있다"},{"l":"쌀은 쏟고 주워도 말은 하고 못 줍는다","r":"한번 한 말은 다시 거두어들일 수 없으니 조심해야 한다"},{"l":"아 해 다르고 어 해 다르다","r":"같은 내용도 어떻게 말하느냐에 따라 듣는 느낌이 다르다"}],"mis":"K3-2-u4-X27","explanation":["네 속담 모두 말을 조심해서 해야 한다는 뜻을 담고 있어요.","어떻게 말하느냐에 따라 상대의 반응과 일의 결과가 달라져요.","그래서 대화할 때 예절을 지켜야 해요."],"asset":{"type":"passage","lines":["㉮ 가는 말이 고와야 오는 말이 곱다","㉯ 말 한마디에 천 냥 빚도 갚는다","㉰ 쌀은 쏟고 주워도 말은 하고 못 줍는다","㉱ 아 해 다르고 어 해 다르다"],"title":"대화와 관련된 속담"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_basic#8','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C13',2,'mc','auto','『국어』 200쪽 3번이에요. 대화할 때 예절을 지키면 어떤 점이 좋은가요?',ARRAY['K3-2-u4-X16','K3-2-u4-X37','K3-2-u4-X26']::text[],false,'{"seq":8,"concept":"K3-2-u4-C13","difficulty":2,"kind":"mc","stem":"『국어』 200쪽 3번이에요. 대화할 때 예절을 지키면 어떤 점이 좋은가요?","options":[{"t":"서로 존중받는 느낌이 들어 좋은 관계를 이어 갈 수 있고, 불필요한 오해가 생기지 않는다","correct":true},{"t":"상대가 내 부탁을 모두 들어주게 된다","mis":"K3-2-u4-X16"},{"t":"듣기 좋게 꾸민 말만 하면 되니 편하다","mis":"K3-2-u4-X37"},{"t":"언제나 내 생각대로 정할 수 있다","mis":"K3-2-u4-X26"}],"explanation":["예절을 지키면 듣는 사람이 존중받는다고 느껴요.","그러면 서로 좋은 관계를 이어 갈 수 있어요.","오해도 생기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_basic#9','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C14',2,'mc','auto','『국어』 200쪽 2번 「대화할 때 지켜야 할 예절」로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X27']::text[],false,'{"seq":9,"concept":"K3-2-u4-C14","difficulty":2,"kind":"mc","stem":"『국어』 200쪽 2번 「대화할 때 지켜야 할 예절」로 알맞지 않은 것은 무엇인가요?","options":[{"t":"친한 사이니까 친구가 듣기 싫어하는 별명으로 불러도 된다","correct":true},{"t":"듣는 사람의 기분을 헤아리며 말한다","mis":"K3-2-u4-X18"},{"t":"상대의 말을 귀 기울여 듣는다","mis":"K3-2-u4-X27"},{"t":"상대가 기분 나빠 하는 호칭으로 부르지 않는다","mis":"K3-2-u4-X18"}],"explanation":["친한 사이라도 듣기 싫어하는 별명은 상대를 기분 나쁘게 해요.","듣는 사람의 기분을 헤아리고 귀 기울여 들어요.","상대가 기분 나빠 하는 호칭으로 부르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_basic#10','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C14',3,'mc','auto','부탁하거나 거절할 때의 대화예요. 소영이의 말 “동호야, 지금 뭐 해? 나 좀 도와줄 수 있어?”에서 소영이가 지킨 대화 예절은 무엇인가요?',ARRAY['K3-2-u4-X39','K3-2-u4-X19']::text[],false,'{"seq":10,"concept":"K3-2-u4-C14","difficulty":3,"kind":"mc","stem":"부탁하거나 거절할 때의 대화예요. 소영이의 말 “동호야, 지금 뭐 해? 나 좀 도와줄 수 있어?”에서 소영이가 지킨 대화 예절은 무엇인가요?","options":[{"t":"부탁할 때에는 친구가 자신의 부탁을 들어줄 수 있는 상황인지 확인한다","correct":true},{"t":"부탁을 들어준 친구에게 고마운 마음을 표현한다","mis":"K3-2-u4-X39"},{"t":"거절할 때에는 미안한 마음과 까닭을 말한다","mis":"K3-2-u4-X19"},{"t":"부탁하는 내용을 명령하듯 짧게 말한다","mis":"K3-2-u4-X39"}],"explanation":["소영이는 먼저 “지금 뭐 해?” 하고 동호의 상황을 물었어요.","들어줄 수 있는지도 물었어요.","부탁하기 전에 상대의 상황을 확인하는 것이 예절이에요."],"asset":{"type":"speech","turns":[{"who":"소영","text":"“동호야, 지금 뭐 해? 나 좀 도와줄 수 있어?”"},{"who":"동호","text":"“미안해. 나 지금 선생님 심부름 가는 길이어서 안 될 것 같아.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_challenge#1','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C15',2,'mc','auto','동호의 말 “미안해. 나 지금 선생님 심부름 가는 길이어서 안 될 것 같아.”에서 동호가 지킨 대화 예절은 무엇인가요?',ARRAY['K3-2-u4-X16','K3-2-u4-X19','K3-2-u4-X20']::text[],false,'{"seq":1,"concept":"K3-2-u4-C15","difficulty":2,"kind":"mc","stem":"동호의 말 “미안해. 나 지금 선생님 심부름 가는 길이어서 안 될 것 같아.”에서 동호가 지킨 대화 예절은 무엇인가요?","options":[{"t":"거절할 때 미안한 마음을 표현하고, 도와줄 수 없는 까닭을 말했다","correct":true},{"t":"거절은 예절에 어긋나니 할 일을 미루고 부탁을 들어주었다","mis":"K3-2-u4-X16"},{"t":"까닭은 말하지 않고 “안 돼.”라고 짧게 거절했다","mis":"K3-2-u4-X19"},{"t":"하겠다고 대답하고 나중에 몰래 가 버렸다","mis":"K3-2-u4-X20"}],"explanation":["동호는 먼저 “미안해.”라고 했어요.","선생님 심부름을 가는 길이라는 까닭도 말했어요.","거절할 때에는 미안한 마음과 까닭을 함께 말해요."],"asset":{"type":"speech","turns":[{"who":"소영","text":"“동호야, 지금 뭐 해? 나 좀 도와줄 수 있어?”"},{"who":"동호","text":"“미안해. 나 지금 선생님 심부름 가는 길이어서 안 될 것 같아.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_challenge#2','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C15',2,'ox','auto','친구의 부탁을 거절하면 언제나 대화 예절을 어긴 것이에요.',ARRAY['K3-2-u4-X16']::text[],false,'{"seq":2,"concept":"K3-2-u4-C15","difficulty":2,"kind":"ox","stem":"친구의 부탁을 거절하면 언제나 대화 예절을 어긴 것이에요.","answer":"X","reason_options":[{"t":"들어줄 수 없을 때 거절해도 돼요. 미안한 마음과 까닭을 함께 말하면 예절을 지킨 것이에요.","correct":true},{"t":"대화 예절은 부탁을 모두 들어주는 것이에요.","mis":"K3-2-u4-X16"}],"mis":"K3-2-u4-X16","explanation":["부탁을 들어줄 수 없는 상황도 있어요.","그럴 때는 미안한 마음을 표현하고 까닭을 자세히 말해요.","거절당하는 사람의 마음을 헤아리는 것이 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_challenge#3','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C14',3,'mc','auto','동호는 효진이에게 “나는 네가 나한테 짜증만 내고 명령하듯이 말해서 들어 주고 싶지 않았어.”라고 했어요. 효진이가 고쳐야 할 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X21','K3-2-u4-X17']::text[],false,'{"seq":3,"concept":"K3-2-u4-C14","difficulty":3,"kind":"mc","stem":"동호는 효진이에게 “나는 네가 나한테 짜증만 내고 명령하듯이 말해서 들어 주고 싶지 않았어.”라고 했어요. 효진이가 고쳐야 할 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"이름을 불러 동호의 상황을 묻고, 시키지 않고 부탁하는 말로 말한다","correct":true},{"t":"책을 조금만 들고 다닌다","mis":"K3-2-u4-X18"},{"t":"목소리를 더 크게 해서 다시 말한다","mis":"K3-2-u4-X21"},{"t":"다음부터는 아무에게도 부탁하지 않는다","mis":"K3-2-u4-X17"}],"explanation":["동호는 효진이의 말투와 태도 때문에 들어 주기 싫었어요.","“야!” 대신 “동호야.”, “빨리 좀 들어 봐!” 대신 “들어 줄 수 있어?”라고 말해요.","예절은 부르는 말·부탁하는 말·태도에 드러나요."],"asset":{"type":"speech","turns":[{"who":"소영","text":"“동호야, 지금 바빠? 이 책 좀 같이 들어 줄 수 있어?”"},{"who":"동호","text":"“응, 알았어. 그런데 나 지금 선생님 심부름 가는 길인데, 저기 계단까지만 들어 줘도 될까?”"},{"who":"소영","text":"“물론이지. 도와줘서 고마워.”"},{"who":"효진","text":"“왜 내 건 안 들어 주고 소영이 것만 들어 줘?”"},{"who":"동호","text":"“나는 네가 나한테 짜증만 내고 명령하듯이 말해서 들어 주고 싶지 않았어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_challenge#4','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C14',3,'mc','auto','문을 닫아 달라는 여러 가지 말이에요. 상대의 입장을 먼저 헤아려 가장 공손하게 부탁한 말은 무엇인가요?',ARRAY['K3-2-u4-X39','K3-2-u4-X18']::text[],false,'{"seq":4,"concept":"K3-2-u4-C14","difficulty":3,"kind":"mc","stem":"문을 닫아 달라는 여러 가지 말이에요. 상대의 입장을 먼저 헤아려 가장 공손하게 부탁한 말은 무엇인가요?","options":[{"t":"d. 문 좀 닫아 주겠니?","correct":true},{"t":"a. 문 좀 닫아.","mis":"K3-2-u4-X39"},{"t":"b. 바람 들어온다.","mis":"K3-2-u4-X18"}],"explanation":["a는 시키는 말이라 듣는 사람이 기분 나쁠 수 있어요.","b는 돌려 말해서 무엇을 부탁하는지 알기 어려울 수 있어요.","d처럼 묻는 말로 부탁하면 상대를 존중하는 마음이 드러나요."],"asset":{"type":"passage","lines":["a. 문 좀 닫아.","b. 바람 들어온다.","c. 문 좀 닫을래?","d. 문 좀 닫아 주겠니?"],"title":"문을 닫아 달라는 여러 가지 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_challenge#5','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C15',3,'mc','auto','소영이의 말 “도서관에서 책을 많이 빌렸더니 너무 무거워서 혼자 옮기기가 힘드네. 혹시 같이 좀 들어 줄 수 있어?”에서 지킨 대화 예절은 무엇인가요?',ARRAY['K3-2-u4-X39','K3-2-u4-X19']::text[],false,'{"seq":5,"concept":"K3-2-u4-C15","difficulty":3,"kind":"mc","stem":"소영이의 말 “도서관에서 책을 많이 빌렸더니 너무 무거워서 혼자 옮기기가 힘드네. 혹시 같이 좀 들어 줄 수 있어?”에서 지킨 대화 예절은 무엇인가요?","options":[{"t":"부탁하는 까닭과 부탁하는 내용을 자세하게 말한다","correct":true},{"t":"부탁을 들어준 친구에게 고마운 마음을 표현한다","mis":"K3-2-u4-X39"},{"t":"거절할 때에는 미안한 마음을 표현한다","mis":"K3-2-u4-X19"},{"t":"부탁하는 내용은 빼고 까닭만 길게 말한다","mis":"K3-2-u4-X39"}],"explanation":["책이 무거워 혼자 옮기기 힘들다는 까닭을 말했어요.","같이 들어 달라는 부탁 내용도 분명히 말했어요.","까닭과 내용을 자세히 말하면 상대가 부탁을 잘 이해해요."],"asset":{"type":"speech","turns":[{"who":"동호","text":"“무슨 일이야?”"},{"who":"소영","text":"“도서관에서 책을 많이 빌렸더니 너무 무거워서 혼자 옮기기가 힘드네. 혹시 같이 좀 들어 줄 수 있어?”"},{"who":"동호","text":"“그래, 알았어.”"},{"who":"소영","text":"“도와줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_challenge#6','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C13',3,'ox','auto','대화 예절은 전하는 말의 내용에만 드러나고, 말투나 표정, 듣는 자세와는 상관없어요.',ARRAY['K3-2-u4-X18']::text[],false,'{"seq":6,"concept":"K3-2-u4-C13","difficulty":3,"kind":"ox","stem":"대화 예절은 전하는 말의 내용에만 드러나고, 말투나 표정, 듣는 자세와는 상관없어요.","answer":"X","reason_options":[{"t":"대화 예절은 말의 내용뿐 아니라 말투, 표정, 듣는 자세에도 드러나요.","correct":true},{"t":"말의 내용만 공손하면 표정이나 자세는 상관없어요.","mis":"K3-2-u4-X18"}],"mis":"K3-2-u4-X18","explanation":["대화 예절의 첫출발은 상대를 존중하고 배려하는 태도예요.","이 태도는 말의 내용뿐 아니라 말투와 표정에도 드러나요.","귀 기울여 듣는 자세도 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_challenge#7','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C13',3,'error','auto','세 친구가 일상에서 대화 예절을 지키는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X23','K3-2-u4-X25','K3-2-u4-X26']::text[],false,'{"seq":7,"concept":"K3-2-u4-C13","difficulty":3,"kind":"error","stem":"세 친구가 일상에서 대화 예절을 지키는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안: 아버지가 출근하실 때 누워서 인사해도 “다녀오세요.”라고만 하면 예절을 지킨 거야.","correct":true,"mis_target":"K3-2-u4-X23"},{"t":"현우: 할아버지와 통화할 때 할아버지가 끊으시기 전에 먼저 끊지 않아야 해.","mis":"K3-2-u4-X25"},{"t":"서하: 친구가 의견을 말할 때 끼어들지 않고 끝까지 들어야 해.","mis":"K3-2-u4-X26"}],"explanation":["말끝에 ‘요’를 붙여도 누운 채 인사하면 예절에 어긋나요.","자세와 태도에도 존중하는 마음이 드러나야 해요.","전화를 먼저 끊지 않기, 끼어들지 않기도 대화 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_challenge#8','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C14',4,'essay','teacher','효진이의 말 “야! 이 책 좀 들어 봐.”와 “빨리 좀 들어 봐!”를 대화 예절을 지켜 바꾸어 쓰세요. 부르는 말, 상대의 상황을 묻는 말, 부탁하는 말이 드러나게 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u4-C14","difficulty":4,"kind":"essay","stem":"효진이의 말 “야! 이 책 좀 들어 봐.”와 “빨리 좀 들어 봐!”를 대화 예절을 지켜 바꾸어 쓰세요. 부르는 말, 상대의 상황을 묻는 말, 부탁하는 말이 드러나게 쓰세요.","answer_guide":{"answer":"예: “동호야, 지금 바빠? 책이 많아서 혼자 들기 힘든데, 이 책 좀 같이 들어 줄 수 있어?”","scoring_points":["부르는 말을 이름으로 바꾸었는가","상대가 부탁을 들어줄 수 있는 상황인지 물었는가","명령하는 말 대신 부탁하는 말로 바꾸고 까닭을 함께 말했는가"]},"explanation":["“야!” 대신 친구의 이름을 불러요.","“지금 바빠?”처럼 상대의 상황을 먼저 물어요.","“들어 줄 수 있어?”처럼 묻는 말로 부탁해요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"효진이는 책을 반납하러 가는 길이었어요. 책이 많아 혼자 들기 힘들었는데 마침 동호가 보였어요."},{"who":"효진","text":"“야! 이 책 좀 들어 봐.”"},{"who":"동호","text":"“나?”"},{"who":"효진","text":"(짜증 내며) “빨리 좀 들어 봐!”"},{"who":"동호","text":"(퉁명스레) “내가 왜? 나 바빠.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_challenge#9','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C13',4,'essay','teacher','대화 예절을 지켜서 기분 좋았던 경험이나 지키지 않아서 기분이 나빴던 경험을 하나 쓰고, 그때 상대의 마음이 어땠을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C13","difficulty":4,"kind":"essay","stem":"대화 예절을 지켜서 기분 좋았던 경험이나 지키지 않아서 기분이 나빴던 경험을 하나 쓰고, 그때 상대의 마음이 어땠을지 쓰세요.","answer_guide":{"answer":"예: 짝에게 지우개를 빌릴 때 “야, 지우개 줘.”라고 했더니 짝이 기분 나빠하며 안 빌려주었다. 짝은 내가 자기를 존중하지 않는다고 느껴 속상했을 것이다. 다음에는 “지우개 좀 빌려줄 수 있어?”라고 말하겠다.","scoring_points":["대화 예절과 관련된 경험을 구체적으로 썼는가","그때 상대의 마음을 짐작해 썼는가","경험에서 깨달은 점이나 고칠 점을 썼는가"]},"explanation":["부탁할 때, 대답할 때, 모둠 활동을 할 때를 떠올려요.","내 말을 들은 상대의 기분을 헤아려 보아요.","깨달은 점을 다음 대화에 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L07_challenge#10','kor',3,2,'u4','L07','tb_g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C15',4,'mc','auto','효진이가 “왜 내 건 안 들어 주고 소영이 것만 들어 줘?”라며 속상해했어요. 효진이에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X16','K3-2-u4-X33']::text[],false,'{"seq":10,"concept":"K3-2-u4-C15","difficulty":4,"kind":"mc","stem":"효진이가 “왜 내 건 안 들어 주고 소영이 것만 들어 줘?”라며 속상해했어요. 효진이에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“동호를 부르는 말과 부탁하는 말이 소영이와 달랐어. 다음에는 동호의 상황을 묻고 부드럽게 부탁해 봐.”","correct":true},{"t":"“소영이 책이 더 가벼워서 그래. 책을 줄이면 돼.”","mis":"K3-2-u4-X18"},{"t":"“동호는 모든 부탁을 들어주어야 하는데 안 들어주었으니 동호가 잘못했어.”","mis":"K3-2-u4-X16"},{"t":"“동호가 원래 소영이만 좋아해서 그래.”","mis":"K3-2-u4-X33"}],"explanation":["동호는 효진이의 말투가 명령하는 것 같아 들어 주기 싫었어요.","부탁을 꼭 들어주어야 하는 것은 아니에요.","부르는 말과 부탁하는 말을 바꾸면 반응도 달라져요."],"asset":{"type":"speech","turns":[{"who":"소영","text":"“동호야, 지금 바빠? 이 책 좀 같이 들어 줄 수 있어?”"},{"who":"동호","text":"“응, 알았어. 그런데 나 지금 선생님 심부름 가는 길인데, 저기 계단까지만 들어 줘도 될까?”"},{"who":"소영","text":"“물론이지. 도와줘서 고마워.”"},{"who":"효진","text":"“왜 내 건 안 들어 주고 소영이 것만 들어 줘?”"},{"who":"동호","text":"“나는 네가 나한테 짜증만 내고 명령하듯이 말해서 들어 주고 싶지 않았어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_basic#1','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C16',1,'mc','auto','『국어』 201쪽 「주현이와 지환이의 대화」예요. 대화 ㉮에서 주현이가 큰 소리로 불렀을 때 지환이는 뭐라고 했나요?',ARRAY['K3-2-u4-X22','K3-2-u4-X33']::text[],false,'{"seq":1,"concept":"K3-2-u4-C16","difficulty":1,"kind":"mc","stem":"『국어』 201쪽 「주현이와 지환이의 대화」예요. 대화 ㉮에서 주현이가 큰 소리로 불렀을 때 지환이는 뭐라고 했나요?","options":[{"t":"“네 목소리 정말 크다. 멀리서도 잘 들려.”","correct":true},{"t":"“주현아, 목소리가 너무 커.”","mis":"K3-2-u4-X22"},{"t":"“조용히 해. 여기는 도서관이잖아.”","mis":"K3-2-u4-X22"},{"t":"“왜 불렀어? 나 바빠.”","mis":"K3-2-u4-X33"}],"explanation":["대화 ㉮는 운동장에서 나눈 대화예요.","지환이는 외투를 챙겨 준 주현이에게 고마워했어요.","멀리서도 잘 들린다며 큰 목소리를 반겼어요."],"asset":{"type":"speech","turns":[{"who":"㉮ 운동장 — 주현","text":"(큰 소리로) “지환아, 외투 가져가야지.”"},{"who":"지환","text":"(웃으며) “아, 맞다. 챙겨 줘서 고마워. 그런데 네 목소리 정말 크다. 멀리서도 잘 들려.”"},{"who":"㉯ 도서관 — 주현","text":"(크게 부르며) “지환아, 이 책 좀 봐.”"},{"who":"지환","text":"(찡그리며) “주현아, 목소리가 너무 커. 여기는 도서관이잖아.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_basic#2','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C16',1,'mc','auto','대화 ㉮와 ㉯에서 주현이의 목소리 크기는 같은데 지환이의 반응이 다른 까닭은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X18','K3-2-u4-X33']::text[],false,'{"seq":2,"concept":"K3-2-u4-C16","difficulty":1,"kind":"mc","stem":"대화 ㉮와 ㉯에서 주현이의 목소리 크기는 같은데 지환이의 반응이 다른 까닭은 무엇인가요?","options":[{"t":"운동장과 달리 도서관에서는 조용히 말해야 하기 때문","correct":true},{"t":"주현이가 ㉯에서 더 크게 소리쳤기 때문","mis":"K3-2-u4-X21"},{"t":"㉯에서 보여 준 책이 재미없었기 때문","mis":"K3-2-u4-X18"},{"t":"지환이가 ㉯에서만 주현이를 싫어했기 때문","mis":"K3-2-u4-X33"}],"explanation":["두 대화에서 주현이의 목소리 크기는 같아요.","달라진 것은 대화하는 장소예요.","도서관에서는 다른 사람에게 방해가 되지 않게 조용히 말해요."],"asset":{"type":"speech","turns":[{"who":"㉮ 운동장 — 주현","text":"(큰 소리로) “지환아, 외투 가져가야지.”"},{"who":"지환","text":"(웃으며) “아, 맞다. 챙겨 줘서 고마워. 그런데 네 목소리 정말 크다. 멀리서도 잘 들려.”"},{"who":"㉯ 도서관 — 주현","text":"(크게 부르며) “지환아, 이 책 좀 봐.”"},{"who":"지환","text":"(찡그리며) “주현아, 목소리가 너무 커. 여기는 도서관이잖아.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_basic#3','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C16',1,'blank','auto','『국어』 201쪽 정리예요. 「대화 상황은 대화하는 상대, 시간이나 장소, 대화의 (     )이나 방식에 따라 다양해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X18','K3-2-u4-X21']::text[],false,'{"seq":3,"concept":"K3-2-u4-C16","difficulty":1,"kind":"blank","stem":"『국어』 201쪽 정리예요. 「대화 상황은 대화하는 상대, 시간이나 장소, 대화의 (     )이나 방식에 따라 다양해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"목적","correct":true},{"t":"길이","mis":"K3-2-u4-X22"},{"t":"내용","mis":"K3-2-u4-X18"},{"t":"빠르기","mis":"K3-2-u4-X21"}],"explanation":["대화 상황을 이루는 것은 상대, 시간이나 장소, 목적이나 방식이에요.","목적은 무엇을 하려고 대화하는지예요.","상황에 따라 알맞은 대화 예절을 지켜야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_basic#4','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C17',1,'match','auto','『국어』 202쪽 「태수의 대화」예요. 대화 ㉮~㉰에서 태수가 대화하는 상황을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u4-C17","difficulty":1,"kind":"match","stem":"『국어』 202쪽 「태수의 대화」예요. 대화 ㉮~㉰에서 태수가 대화하는 상황을 알맞게 이으세요.","pairs":[{"l":"대화 ㉮","r":"할아버지께 가위의 위치를 알려 드리는 상황"},{"l":"대화 ㉯","r":"친구와 수업 중에 모둠 활동을 하는 상황"},{"l":"대화 ㉰","r":"여럿이 함께 노는 상황"}],"mis":"K3-2-u4-X22","explanation":["㉮는 할아버지와 집에서 나눈 대화예요.","㉯는 공공 기관 조사를 정하는 모둠 활동이에요.","㉰는 태수의 방에서 친구들과 노는 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_basic#5','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C17',2,'mc','auto','대화 ㉮에서 할아버지께서 “할아버지와 대화할 때에는 공손하게 말해야지.”라고 말씀하신 까닭은 무엇인가요?',ARRAY['K3-2-u4-X23','K3-2-u4-X33','K3-2-u4-X21']::text[],false,'{"seq":5,"concept":"K3-2-u4-C17","difficulty":2,"kind":"mc","stem":"대화 ㉮에서 할아버지께서 “할아버지와 대화할 때에는 공손하게 말해야지.”라고 말씀하신 까닭은 무엇인가요?","options":[{"t":"태수가 누운 채로 성의 없는 말투로 대답해서 자세와 말투가 공손하지 못했기 때문","correct":true},{"t":"태수가 말끝에 ‘요’를 붙이지 않았기 때문","mis":"K3-2-u4-X23"},{"t":"태수가 가위가 어디 있는지 몰랐기 때문","mis":"K3-2-u4-X33"},{"t":"태수의 목소리가 너무 작았기 때문","mis":"K3-2-u4-X21"}],"explanation":["태수는 “서랍장에요.”라고 말끝에 ‘요’를 붙였어요.","하지만 소파에 누운 채 할아버지를 보지도 않고 성의 없이 말했어요.","웃어른과 대화할 때에는 자세와 말투도 공손해야 해요."],"asset":{"type":"speech","turns":[{"who":"할아버지","text":"“태수야, 가위가 어디 있니?”"},{"who":"태수","text":"(소파에 누운 채 성의 없는 말투로) “서랍장에요.”"},{"who":"할아버지","text":"“태수야, 할아버지와 대화할 때에는 공손하게 말해야지.”"},{"who":"태수","text":"“아, 죄송해요. 저기 서랍장 안에 있어요. 가져다드릴까요?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_basic#6','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C17',2,'mc','auto','대화 ㉯에서 혜진이가 “지금 모둠 활동 중이잖아.”라고 말한 까닭은 무엇인가요?',ARRAY['K3-2-u4-X17','K3-2-u4-X26','K3-2-u4-X21']::text[],false,'{"seq":6,"concept":"K3-2-u4-C17","difficulty":2,"kind":"mc","stem":"대화 ㉯에서 혜진이가 “지금 모둠 활동 중이잖아.”라고 말한 까닭은 무엇인가요?","options":[{"t":"태수가 모둠 활동과 관련 없는 이야기를 했기 때문","correct":true},{"t":"태수가 아무 말도 하지 않았기 때문","mis":"K3-2-u4-X17"},{"t":"태수가 혜진이의 의견에 찬성했기 때문","mis":"K3-2-u4-X26"},{"t":"태수가 너무 작게 말했기 때문","mis":"K3-2-u4-X21"}],"explanation":["모둠은 공공 기관 가운데 어디를 조사할지 정하고 있었어요.","태수는 갑자기 급식 메뉴를 물었어요.","대화하는 목적을 생각해서 주제와 관련한 말을 해야 해요."],"asset":{"type":"speech","turns":[{"who":"혜진","text":"“우리 모둠은 공공 기관 가운데에서 어디를 조사해 볼까?”"},{"who":"태수","text":"“혜진아, 그런데 오늘 급식 메뉴가 뭐지? 배고프다.”"},{"who":"혜진","text":"“지금 모둠 활동 중이잖아.”"},{"who":"태수","text":"“아, 미안. 이제 대화에 집중할게.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_basic#7','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C17',2,'mc','auto','대화 ㉰에서 인혜와 진성이가 귓속말을 할 때 태수는 기분이 어땠을까요?',ARRAY['K3-2-u4-X24','K3-2-u4-X33']::text[],false,'{"seq":7,"concept":"K3-2-u4-C17","difficulty":2,"kind":"mc","stem":"대화 ㉰에서 인혜와 진성이가 귓속말을 할 때 태수는 기분이 어땠을까요?","options":[{"t":"자기만 빼고 이야기하는 것 같아 소외되는 기분이 들었을 것이다","correct":true},{"t":"친구들이 조용히 말해 주어 고마웠을 것이다","mis":"K3-2-u4-X24"},{"t":"귓속말은 상관없어서 아무렇지 않았을 것이다","mis":"K3-2-u4-X24"},{"t":"놀이를 빨리 골라서 신났을 것이다","mis":"K3-2-u4-X33"}],"explanation":["태수는 “나만 빼고 너네끼리 무슨 얘기 해?”라고 말했어요.","여럿이 함께 노는데 두 사람만 귓속말을 했어요.","귓속말은 다른 친구가 소외감을 느끼게 할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"태수","text":"“여기가 내 방이야. 무슨 놀이를 할까? 여기에서 골라 봐.”"},{"who":"인혜","text":"(귓속말로) “넌 뭐 하고 싶어?”"},{"who":"진성","text":"(귓속말로) “난 저거.”"},{"who":"태수","text":"“나만 빼고 너네끼리 무슨 얘기 해?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_basic#8','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C17',2,'match','auto','『국어』 203쪽 3번이에요. 상황에 알맞은 대화 예절이 되도록 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u4-C17","difficulty":2,"kind":"match","stem":"『국어』 203쪽 3번이에요. 상황에 알맞은 대화 예절이 되도록 알맞게 이으세요.","pairs":[{"l":"공공장소에서는","r":"조용히 대화한다."},{"l":"웃어른과 대화할 때에는","r":"공손한 태도로 대화한다."},{"l":"대화하는 목적을 생각해서","r":"주제와 관련한 말을 한다."},{"l":"여럿이 놀 때에는","r":"귓속말을 하지 않도록 주의한다."}],"mis":"K3-2-u4-X22","explanation":["보기는 공손한 · 귓속말 · 공공장소 · 주제예요.","「공공장소에서는 조용히」, 「웃어른과는 공손한 태도로」, 「목적을 생각해 주제와 관련한 말」이에요.","여럿이 놀 때는 귓속말을 주의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_basic#9','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C18',2,'mc','auto','『국어』 204쪽 4번이에요. 전화 대화의 특징으로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":9,"concept":"K3-2-u4-C18","difficulty":2,"kind":"mc","stem":"『국어』 204쪽 4번이에요. 전화 대화의 특징으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"상대의 표정과 상황을 눈으로 보며 말할 수 있다","correct":true},{"t":"전화를 거는 사람과 받는 사람이 있다","mis":"K3-2-u4-X25"},{"t":"“여보세요?”, “이만 끊을게.”처럼 자주 쓰는 말이 있다","mis":"K3-2-u4-X25"},{"t":"상대의 상황을 정확히 알 수 없다","mis":"K3-2-u4-X25"}],"explanation":["전화 대화는 직접 만나지 않고 매체를 이용해 나누는 대화예요.","상대의 얼굴과 상황을 볼 수 없어요.","그래서 전화에서 지켜야 할 예절이 따로 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_basic#10','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C18',3,'mc','auto','『국어』 204쪽 대화 ㉮에서 할머니께서 전화를 받으셨을 때 인영이가 “할머니, 저 인영이예요.”라고 말한 까닭은 무엇일까요?',ARRAY['K3-2-u4-X33','K3-2-u4-X25','K3-2-u4-X21']::text[],false,'{"seq":10,"concept":"K3-2-u4-C18","difficulty":3,"kind":"mc","stem":"『국어』 204쪽 대화 ㉮에서 할머니께서 전화를 받으셨을 때 인영이가 “할머니, 저 인영이예요.”라고 말한 까닭은 무엇일까요?","options":[{"t":"전화로 대화할 때에는 상대를 볼 수 없어서 상대를 확인하고 자신을 밝히려고","correct":true},{"t":"할머니께서 인영이를 잊어버리셨기 때문에","mis":"K3-2-u4-X33"},{"t":"전화를 걸면 바로 하고 싶은 말부터 해야 하기 때문에","mis":"K3-2-u4-X25"},{"t":"학교 전화기는 소리가 작기 때문에","mis":"K3-2-u4-X21"}],"explanation":["전화는 얼굴이 보이지 않아요.","그래서 “할머니,” 하고 상대를 확인하고 “저 인영이예요.” 하고 자신을 밝혀요.","누가 전화를 걸었는지 알면 상대가 편하게 대화할 수 있어요."],"asset":{"type":"passage","lines":["㉮ 할머니: “여보세요?”","인영: “할머니, 저 인영이예요.”","㉯ 인영: “지금 통화하기 괜찮아?”","친구: “저녁 식사 중이라 지금은 좀 어려워. 이따가 내가 다시 연락할게.”","㉰ 인영: “준비물 알려 줘서 고마워. 그럼 내일 보자. 안녕.”","친구: “응, 안녕.”"],"title":"인영이의 전화 대화 ㉮~㉰ — 『국어』 204쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_challenge#1','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C18',2,'mc','auto','대화 ㉯에서 인영이가 친구에게 “지금 통화하기 괜찮아?”라고 물은 까닭은 무엇일까요?',ARRAY['K3-2-u4-X33','K3-2-u4-X25']::text[],false,'{"seq":1,"concept":"K3-2-u4-C18","difficulty":2,"kind":"mc","stem":"대화 ㉯에서 인영이가 친구에게 “지금 통화하기 괜찮아?”라고 물은 까닭은 무엇일까요?","options":[{"t":"상대가 통화하기 괜찮은 상황인지 눈으로 확인할 수 없기 때문","correct":true},{"t":"친구가 전화를 받지 않았기 때문","mis":"K3-2-u4-X33"},{"t":"친구와 오래 통화하고 싶어서","mis":"K3-2-u4-X25"},{"t":"친구가 인영이를 몰랐기 때문","mis":"K3-2-u4-X33"}],"explanation":["전화로는 상대가 지금 무엇을 하는지 볼 수 없어요.","친구는 저녁 식사 중이었어요.","그래서 통화하기 괜찮은지 먼저 물어요."],"asset":{"type":"passage","lines":["㉮ 할머니: “여보세요?”","인영: “할머니, 저 인영이예요.”","㉯ 인영: “지금 통화하기 괜찮아?”","친구: “저녁 식사 중이라 지금은 좀 어려워. 이따가 내가 다시 연락할게.”","㉰ 인영: “준비물 알려 줘서 고마워. 그럼 내일 보자. 안녕.”","친구: “응, 안녕.”"],"title":"인영이의 전화 대화 ㉮~㉰ — 『국어』 204쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_challenge#2','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C18',2,'sa','auto','대화 ㉰에서 인영이는 통화를 마칠 때 어떤 끝인사를 했나요? 인영이가 한 말 가운데 끝인사 부분을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u4-C18","difficulty":2,"kind":"sa","stem":"대화 ㉰에서 인영이는 통화를 마칠 때 어떤 끝인사를 했나요? 인영이가 한 말 가운데 끝인사 부분을 쓰세요.","answer":["그럼 내일 보자. 안녕.","그럼 내일 보자 안녕","내일 보자. 안녕.","내일 보자 안녕","안녕"],"explanation":["인영이는 먼저 “준비물 알려 줘서 고마워.”라고 했어요.","그리고 “그럼 내일 보자. 안녕.”이라고 끝인사를 했어요.","통화를 마칠 때에는 끝인사를 하고 끊어요."],"asset":{"type":"passage","lines":["㉮ 할머니: “여보세요?”","인영: “할머니, 저 인영이예요.”","㉯ 인영: “지금 통화하기 괜찮아?”","친구: “저녁 식사 중이라 지금은 좀 어려워. 이따가 내가 다시 연락할게.”","㉰ 인영: “준비물 알려 줘서 고마워. 그럼 내일 보자. 안녕.”","친구: “응, 안녕.”"],"title":"인영이의 전화 대화 ㉮~㉰ — 『국어』 204쪽"},"mis":"K3-2-u4-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_challenge#3','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C18',3,'mc','auto','『국어』 205쪽 6번이에요. 전화로 대화할 때 지켜야 할 예절로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":3,"concept":"K3-2-u4-C18","difficulty":3,"kind":"mc","stem":"『국어』 205쪽 6번이에요. 전화로 대화할 때 지켜야 할 예절로 알맞지 않은 것은 무엇인가요?","options":[{"t":"하고 싶은 말을 다 했으면 언제든 전화를 끊는다","correct":true},{"t":"자신이 누구인지 밝히고, 상대가 누구인지 확인한다","mis":"K3-2-u4-X25"},{"t":"상대가 통화하기 괜찮은 상황인지 확인한다","mis":"K3-2-u4-X25"},{"t":"통화를 마칠 때에는 끝인사를 한다","mis":"K3-2-u4-X25"}],"explanation":["내 말을 다 했다고 바로 끊으면 상대는 할 말을 못 할 수 있어요.","끝인사를 하고 끊어요.","상대가 받을 때까지 계속 거는 것도 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_challenge#4','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C19',3,'mc','auto','모둠 대화를 할 때의 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X38']::text[],false,'{"seq":4,"concept":"K3-2-u4-C19","difficulty":3,"kind":"mc","stem":"모둠 대화를 할 때의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"주제 확인하기 → 의견 마련하기 → 의견 모으기 → 의견 결정하기","correct":true},{"t":"의견 결정하기 → 주제 확인하기 → 의견 마련하기 → 의견 모으기","mis":"K3-2-u4-X38"},{"t":"의견 마련하기 → 의견 모으기 → 주제 확인하기 → 의견 결정하기","mis":"K3-2-u4-X38"},{"t":"주제 확인하기 → 의견 결정하기 → 의견 마련하기 → 의견 모으기","mis":"K3-2-u4-X38"}],"explanation":["먼저 무엇을 이야기할지 주제를 확인해요.","저마다 의견을 마련하고 모둠에서 의견을 모아요.","마지막으로 모은 의견 가운데에서 결정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_challenge#5','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C19',3,'mc','auto','모둠 친구들과 의견을 나눌 때 지켜야 할 대화 예절로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u4-X26','K3-2-u4-X17']::text[],false,'{"seq":5,"concept":"K3-2-u4-C19","difficulty":3,"kind":"mc","stem":"모둠 친구들과 의견을 나눌 때 지켜야 할 대화 예절로 알맞지 않은 것은 무엇인가요?","options":[{"t":"내 생각이 옳다면 다른 친구의 말을 끊고 끝까지 밀고 간다","correct":true},{"t":"다른 사람의 말을 중간에 끊지 않고 귀 기울여 듣는다","mis":"K3-2-u4-X26"},{"t":"자신의 생각만 옳다고 강요하지 않는다","mis":"K3-2-u4-X26"},{"t":"모둠 대화에 책임감을 가지고 적극적으로 참여한다","mis":"K3-2-u4-X17"}],"explanation":["모둠 대화는 이기려는 것이 아니라 함께 답을 찾는 것이에요.","다른 사람의 말을 끝까지 듣고 내 생각도 말해요.","책임감을 가지고 적극적으로 참여해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_challenge#6','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C19',3,'ox','auto','모둠 대화에서 다툼이 생기지 않으려면 아무 말도 하지 않고 가만히 있는 것이 가장 좋은 예절이에요.',ARRAY['K3-2-u4-X17']::text[],false,'{"seq":6,"concept":"K3-2-u4-C19","difficulty":3,"kind":"ox","stem":"모둠 대화에서 다툼이 생기지 않으려면 아무 말도 하지 않고 가만히 있는 것이 가장 좋은 예절이에요.","answer":"X","reason_options":[{"t":"모둠 대화는 함께 문제를 해결하는 것이라 내 생각도 말하며 적극적으로 참여해야 해요.","correct":true},{"t":"말하지 않으면 다툼이 없으니 가장 예절 바른 거예요.","mis":"K3-2-u4-X17"}],"mis":"K3-2-u4-X17","explanation":["모둠 대화에 책임감을 가지고 참여해요.","아무 말도 하지 않으면 함께 답을 찾을 수 없어요.","끝까지 듣고, 내 생각도 공손하게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_challenge#7','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C17',3,'mc','auto','『국어활동』 60쪽 ㉮ 학급 회의에서 발표한 친구가 잘 지킨 대화 예절은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X24']::text[],false,'{"seq":7,"concept":"K3-2-u4-C17","difficulty":3,"kind":"mc","stem":"『국어활동』 60쪽 ㉮ 학급 회의에서 발표한 친구가 잘 지킨 대화 예절은 무엇인가요?","options":[{"t":"대화하는 목적을 고려해 주제와 관련 있는 말을 한다","correct":true},{"t":"공공장소에서는 조용히 대화한다","mis":"K3-2-u4-X22"},{"t":"웃어른과 대화할 때에는 공손한 태도로 말한다","mis":"K3-2-u4-X22"},{"t":"친구에게 귓속말로 의견을 전한다","mis":"K3-2-u4-X24"}],"explanation":["회의 주제는 친구들과 사이좋게 지내기 위해 노력할 점이에요.","발표한 친구는 별명으로 부르지 말자는, 주제에 맞는 의견을 말했어요.","목적을 생각하면 주제와 관련한 말을 하게 돼요."],"asset":{"type":"passage","lines":["㉮ 학급 회의 — 사회자: “친구들과 사이좋게 지내기 위해 노력할 점을 발표해 주십시오.”","발표자: “친구가 기분 나빠 하는 별명으로 부르지 말아야 합니다.”","㉯ 버스 안 — (작은 목소리로) “형, 우리 집에 가는 길에 과자 사서 먹자.”"],"title":"『국어활동』 60쪽 — 잘 지킨 대화 예절 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_challenge#8','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C18',4,'mc','auto','『국어활동』 61쪽 ㉰와 ㉱에서 잘 지킨 전화 예절을 바르게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X25']::text[],false,'{"seq":8,"concept":"K3-2-u4-C18","difficulty":4,"kind":"mc","stem":"『국어활동』 61쪽 ㉰와 ㉱에서 잘 지킨 전화 예절을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"㉰ 자신이 누구인지 밝히고 상대가 누구인지 확인함 · ㉱ 상대가 통화하기 괜찮은 상황인지 확인함","correct":true},{"t":"㉰ 상대가 통화하기 괜찮은 상황인지 확인함 · ㉱ 자신이 누구인지 밝힘","mis":"K3-2-u4-X22"},{"t":"㉰ 통화를 마칠 때 끝인사를 함 · ㉱ 통화를 마칠 때 끝인사를 함","mis":"K3-2-u4-X25"},{"t":"㉰ 받자마자 하고 싶은 말부터 함 · ㉱ 상대가 받을 때까지 계속 전화를 검","mis":"K3-2-u4-X25"}],"explanation":["㉰의 희지는 “수찬아,” 하고 상대를 확인하고 “나 희지야.” 하고 자신을 밝혔어요.","㉱의 손녀는 “지금 통화 괜찮으세요?” 하고 할머니의 상황을 여쭈었어요.","㉱는 높임 표현도 함께 써서 할머니를 높였어요."],"asset":{"type":"passage","lines":["㉰ 수찬: “여보세요?”","희지: “수찬아, 안녕? 나 희지야.”","㉱ 손녀: “할머니, 지금 통화 괜찮으세요?”","할머니: “응, 괜찮아. 그동안 잘 지냈니?”"],"title":"『국어활동』 61쪽 — 전화 대화에서 잘 지킨 예절"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_challenge#9','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C17',4,'essay','teacher','1모둠(태수와 할아버지), 2모둠(태수와 친구들), 3모둠(인영이의 전화) 가운데 한 모둠을 골라, 그 상황에서 지켜야 할 대화 예절을 모둠 토의 결과처럼 두 가지 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C17","difficulty":4,"kind":"essay","stem":"1모둠(태수와 할아버지), 2모둠(태수와 친구들), 3모둠(인영이의 전화) 가운데 한 모둠을 골라, 그 상황에서 지켜야 할 대화 예절을 모둠 토의 결과처럼 두 가지 정리해 쓰세요.","answer_guide":{"answer":"예: 1모둠 — ① 웃어른이시니 누워서 말씀드리지 않고 앉거나 서서 할아버지를 바라보며 말씀드린다. ② 높임 표현을 쓰면서 공손한 태도와 말투로 말한다.","scoring_points":["한 모둠의 상황을 골랐는가","그 상황에 알맞은 대화 예절을 두 가지 썼는가","대화 상대·목적·방식 가운데 상황의 특징과 이어 썼는가"]},"explanation":["1모둠은 웃어른과 대화하는 상황이에요.","2모둠은 여럿이 함께 노는 상황, 3모둠은 전화로 대화하는 상황이에요.","상황의 특징을 생각하면 지켜야 할 예절이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L08_challenge#10','kor',3,2,'u4','L08','tb_g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C19',4,'essay','teacher','모둠 대화를 마치고 활동을 평가해요. 모둠 대화에서 자신이 잘 지킨 대화 예절 한 가지와 다음에 더 잘 지키고 싶은 대화 예절 한 가지를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u4-C19","difficulty":4,"kind":"essay","stem":"모둠 대화를 마치고 활동을 평가해요. 모둠 대화에서 자신이 잘 지킨 대화 예절 한 가지와 다음에 더 잘 지키고 싶은 대화 예절 한 가지를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 잘 지킨 예절 — 친구가 의견을 말할 때 끝까지 들었다. 그래서 친구 의견을 잘 이해할 수 있었다. 더 지키고 싶은 예절 — 의견이 달라도 공손하게 말하기. 오늘은 “그건 아니야.”라고 말해 친구가 서운해했기 때문이다.","scoring_points":["모둠 대화에서 잘 지킨 예절을 썼는가","다음에 더 지키고 싶은 예절을 썼는가","각각의 까닭을 실제 대화 장면과 이어 썼는가"]},"explanation":["끝까지 듣기, 주제와 관련한 말 하기, 적극적으로 참여하기를 떠올려요.","잘한 점과 고칠 점을 모두 찾아요.","평가는 다음 대화를 더 잘하려고 하는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_basic#1','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C20',1,'sa','auto','『국어』 206쪽 상황 ㉮의 대화 방식은 무엇인가요? 짧게 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C20","difficulty":1,"kind":"sa","stem":"『국어』 206쪽 상황 ㉮의 대화 방식은 무엇인가요? 짧게 쓰세요.","answer":["전화 대화","전화","전화로 대화","전화 통화","전화로"],"explanation":["상황 ㉮는 친구와 만날 약속을 정하는 상황이에요.","두 친구는 전화로 이야기해요.","대화 방식은 전화 대화예요."],"asset":{"type":"passage","lines":["상황 ㉮ — 친구와 언제 어디에서 만날지 전화로 약속을 정하는 상황","상황 ㉯ — 어머니께서 분리배출을 도와 달라고 하시는데","도와드릴 수 없는 상황"],"title":"『국어』 206쪽 대화 상황"},"mis":"K3-2-u4-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_basic#2','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C20',1,'match','auto','『국어』 206쪽 상황 ㉮와 ㉯를 분석했어요. 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u4-C20","difficulty":1,"kind":"match","stem":"『국어』 206쪽 상황 ㉮와 ㉯를 분석했어요. 알맞게 이으세요.","pairs":[{"l":"상황 ㉮의 대화 목적","r":"만날 약속을 하려고"},{"l":"상황 ㉯의 대화 목적","r":"어머니의 부탁을 거절하려고"},{"l":"상황 ㉮의 대화 방식","r":"전화 대화"},{"l":"상황 ㉯의 대화 방식","r":"직접 만나서 대화"}],"mis":"K3-2-u4-X22","explanation":["상황을 분석할 때에는 대화 상대, 목적, 방식을 살펴요.","㉮는 친구와 전화로 만날 약속을 해요.","㉯는 어머니와 직접 만나 부탁을 거절하는 상황이에요."],"asset":{"type":"passage","lines":["상황 ㉮ — 친구와 언제 어디에서 만날지 전화로 약속을 정하는 상황","상황 ㉯ — 어머니께서 분리배출을 도와 달라고 하시는데","도와드릴 수 없는 상황"],"title":"『국어』 206쪽 대화 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_basic#3','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C21',1,'mc','auto','‘응답하라 1, 2, 3’이에요. 할아버지께 감사한 마음을 전하려는 지욱이의 응답으로 알맞은 것은 누구의 응답인가요?',ARRAY['K3-2-u4-X27']::text[],false,'{"seq":3,"concept":"K3-2-u4-C21","difficulty":1,"kind":"mc","stem":"‘응답하라 1, 2, 3’이에요. 할아버지께 감사한 마음을 전하려는 지욱이의 응답으로 알맞은 것은 누구의 응답인가요?","options":[{"t":"학생 1 — 즐거운 말투로 “감사합니다.”","correct":true},{"t":"학생 2 — 화내는 말투로 “감사합니다.”","mis":"K3-2-u4-X27"},{"t":"학생 3 — 울먹이는 말투로 “감사합니다.”","mis":"K3-2-u4-X27"}],"explanation":["세 학생은 모두 “감사합니다.”라고 같은 말을 했어요.","그런데 말투가 서로 달랐어요.","감사한 마음은 즐거운 말투에 잘 드러나요."],"asset":{"type":"passage","lines":["할아버지께서 “지욱아, 맛있는 거 사 먹어라.” 하시며 용돈을 주셨어요.","학생 1: (즐거운 말투로) “감사합니다.”","학생 2: (화내는 말투로) “감사합니다.”","학생 3: (울먹이는 말투로) “감사합니다.”"],"title":"응답하라 1, 2, 3"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_basic#4','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C21',1,'ox','auto','같은 말이라도 말하는 이의 표정, 몸짓, 말투에 따라 듣는 이의 기분이 달라질 수 있어요.',ARRAY['K3-2-u4-X27']::text[],false,'{"seq":4,"concept":"K3-2-u4-C21","difficulty":1,"kind":"ox","stem":"같은 말이라도 말하는 이의 표정, 몸짓, 말투에 따라 듣는 이의 기분이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"『국어』 208쪽 정리 그대로예요. 표정, 몸짓, 말투에 따라 듣는 이의 기분이 달라져요.","correct":true},{"t":"말의 내용이 같으면 표정이나 말투는 아무 상관이 없어요.","mis":"K3-2-u4-X27"}],"mis":"K3-2-u4-X27","explanation":["화내는 말투로 “감사합니다.”라고 하면 고마운 마음이 전해지지 않아요.","표정과 몸짓에도 마음이 드러나요.","그래서 상황에 어울리는 표정, 몸짓, 말투로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_basic#5','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C20',2,'mc','auto','상황 ㉯처럼 어머니의 부탁을 거절할 때 지켜야 할 대화 예절로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X20','K3-2-u4-X19','K3-2-u4-X16']::text[],false,'{"seq":5,"concept":"K3-2-u4-C20","difficulty":2,"kind":"mc","stem":"상황 ㉯처럼 어머니의 부탁을 거절할 때 지켜야 할 대화 예절로 가장 알맞은 것은 무엇인가요?","options":[{"t":"공손한 태도로 높임 표현을 쓰고, 죄송한 마음과 도와드릴 수 없는 까닭을 말씀드린다","correct":true},{"t":"하겠다고 대답하고 나중에 몰래 나간다","mis":"K3-2-u4-X20"},{"t":"“싫어요.”라고만 말하고 방으로 들어간다","mis":"K3-2-u4-X19"},{"t":"어머니의 부탁이니 친구와의 약속을 말없이 어긴다","mis":"K3-2-u4-X16"}],"explanation":["어머니는 웃어른이시니 높임 표현과 공손한 태도로 말해요.","거절할 때에는 거절당하는 사람의 마음을 잘 헤아려요.","죄송한 마음과 까닭을 함께 말씀드려요."],"asset":{"type":"passage","lines":["상황 ㉮ — 친구와 언제 어디에서 만날지 전화로 약속을 정하는 상황","상황 ㉯ — 어머니께서 분리배출을 도와 달라고 하시는데","도와드릴 수 없는 상황"],"title":"『국어』 206쪽 대화 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_basic#6','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C20',2,'mc','auto','상황 ㉮처럼 친구와 전화로 약속을 정할 때 지켜야 할 대화 예절로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X25','K3-2-u4-X26']::text[],false,'{"seq":6,"concept":"K3-2-u4-C20","difficulty":2,"kind":"mc","stem":"상황 ㉮처럼 친구와 전화로 약속을 정할 때 지켜야 할 대화 예절로 가장 알맞은 것은 무엇인가요?","options":[{"t":"친구가 통화할 수 있는 상황인지 살피고, 자신이 누구인지 밝힌다","correct":true},{"t":"친구가 받자마자 내 할 말부터 한다","mis":"K3-2-u4-X25"},{"t":"약속을 정했으면 끝인사 없이 바로 끊는다","mis":"K3-2-u4-X25"},{"t":"친구의 의견은 듣지 않고 내가 정한 곳만 말한다","mis":"K3-2-u4-X26"}],"explanation":["전화로는 상대의 상황을 볼 수 없어요.","자신을 밝히고 통화할 수 있는지 먼저 물어요.","의견을 나눌 때는 상대의 말을 끊거나 무시하지 않아요."],"asset":{"type":"passage","lines":["상황 ㉮ — 친구와 언제 어디에서 만날지 전화로 약속을 정하는 상황","상황 ㉯ — 어머니께서 분리배출을 도와 달라고 하시는데","도와드릴 수 없는 상황"],"title":"『국어』 206쪽 대화 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_basic#7','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C21',2,'mc','auto','『국어』 208쪽 (2)예요. 전화로 대화할 때 내가 잘 듣고 있다는 것을 상대에게 알리는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X27','K3-2-u4-X21']::text[],false,'{"seq":7,"concept":"K3-2-u4-C21","difficulty":2,"kind":"mc","stem":"『국어』 208쪽 (2)예요. 전화로 대화할 때 내가 잘 듣고 있다는 것을 상대에게 알리는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"“응.”, “그렇구나.”라고 한 번씩 말하며 통화에 집중한다","correct":true},{"t":"얼굴이 보이지 않으니 아무 말 없이 듣기만 한다","mis":"K3-2-u4-X27"},{"t":"다른 일을 하면서 듣는다","mis":"K3-2-u4-X27"},{"t":"상대보다 더 크게 말한다","mis":"K3-2-u4-X21"}],"explanation":["전화에서는 고개를 끄덕여도 상대가 볼 수 없어요.","“응.”, “그렇구나.” 같은 짧은 말로 듣고 있음을 알려요.","다른 일을 하지 않고 통화에 집중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_basic#8','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C20',2,'mc','auto','『국어』 207쪽 역할놀이 대본이에요. 은혜가 지킨 전화 대화 예절은 무엇인가요?',ARRAY['K3-2-u4-X26','K3-2-u4-X25']::text[],false,'{"seq":8,"concept":"K3-2-u4-C20","difficulty":2,"kind":"mc","stem":"『국어』 207쪽 역할놀이 대본이에요. 은혜가 지킨 전화 대화 예절은 무엇인가요?","options":[{"t":"자신이 누구인지 밝히고, 지금 통화가 괜찮은지 물었다","correct":true},{"t":"다인이의 의견을 묻지 않고 약속 장소를 정했다","mis":"K3-2-u4-X26"},{"t":"끝인사 없이 전화를 끊었다","mis":"K3-2-u4-X25"},{"t":"받자마자 약속 이야기부터 했다","mis":"K3-2-u4-X25"}],"explanation":["은혜는 “다인아, 나 은혜야.”라고 자신을 밝혔어요.","“지금 통화 괜찮아?”라고 상황도 물었어요.","언제 어디에서 볼지 다인이의 의견을 묻고 끝인사도 했어요."],"asset":{"type":"passage","lines":["다인: 여보세요?","은혜: 다인아, 나 은혜야. 지금 통화 괜찮아?","다인: 응, 은혜구나. 무슨 일이야?","은혜: 우리 내일 만나기로 했잖아. 언제 어디에서 볼까?","다인: 점심 먹고 만나자. 2시에 놀이터 괜찮아?","은혜: 응, 좋아. 그럼 내일 보자.","다인: 그래, 안녕."],"title":"역할놀이 대본 — 상황 ㉮ (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_basic#9','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C22',2,'mc','auto','『국어』 209쪽 점검표에서 짝과 함께 확인하는 세 가지는 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X28','K3-2-u4-X18']::text[],false,'{"seq":9,"concept":"K3-2-u4-C22","difficulty":2,"kind":"mc","stem":"『국어』 209쪽 점검표에서 짝과 함께 확인하는 세 가지는 무엇인가요?","options":[{"t":"대화 상대·대화 목적·대화 방식에 알맞은 대화 예절을 지켰는지","correct":true},{"t":"목소리 크기·말 빠르기·대본 길이","mis":"K3-2-u4-X21"},{"t":"대본을 몇 줄 썼는지·칸을 모두 채웠는지·점수가 높은지","mis":"K3-2-u4-X28"},{"t":"대화 내용·물건·친한 정도","mis":"K3-2-u4-X18"}],"explanation":["점검표는 대화 상대, 목적, 방식에 알맞은 예절을 확인해요.","나와 짝의 역할놀이를 모두 살펴요.","부족한 부분을 찾아 고치려고 확인해요."],"asset":{"type":"passage","lines":["대화 상대에 알맞은 대화 예절을 지켰나요?   나 ○○○ · 짝 ○○○","대화 목적에 알맞은 대화 예절을 지켰나요?   나 ○○○ · 짝 ○○○","대화 방식에 알맞은 대화 예절을 지켰나요?   나 ○○○ · 짝 ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"역할놀이 점검표 — 『국어』 209쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_basic#10','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C21',3,'mc','auto','‘응답하라 1, 2, 3’의 또 다른 상황이에요. 친구에게 미안한 마음을 전하려는 혜인이의 응답으로 가장 알맞은 것은 누구의 응답인가요?',ARRAY['K3-2-u4-X27']::text[],false,'{"seq":10,"concept":"K3-2-u4-C21","difficulty":3,"kind":"mc","stem":"‘응답하라 1, 2, 3’의 또 다른 상황이에요. 친구에게 미안한 마음을 전하려는 혜인이의 응답으로 가장 알맞은 것은 누구의 응답인가요?","options":[{"t":"학생 3 — 어쩔 줄 몰라 하는 말투로","correct":true},{"t":"학생 1 — 신나는 말투로","mis":"K3-2-u4-X27"},{"t":"학생 2 — 화내는 말투로","mis":"K3-2-u4-X27"}],"explanation":["세 학생 모두 “미안해. 괜찮아?”라고 했어요.","신나거나 화내는 말투로는 미안한 마음이 전해지지 않아요.","어쩔 줄 몰라 하는 말투에 미안한 마음이 드러나요."],"asset":{"type":"passage","lines":["실수로 친구의 발을 밟았어요. 친구가 “아야! 혜인아, 네가 방금 내 발 밟았어.","좀 조심해 줘.”라고 말했어요.","학생 1: (신나는 말투로) “미안해. 괜찮아?”","학생 2: (화내는 말투로) “미안해. 괜찮아?”","학생 3: (어쩔 줄 몰라 하는 말투로) “미안해. 괜찮아?”"],"title":"응답하라 1, 2, 3 — 또 다른 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_challenge#1','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C20',2,'mc','auto','상황 ㉯ 예시 대본에서 지원이의 말 “아…… 어떡하죠? 저 친구랑 만나기로 약속한 시간이라 나가 봐야 하거든요.”에 들어 있는 것은 무엇인가요?',ARRAY['K3-2-u4-X20','K3-2-u4-X33']::text[],false,'{"seq":1,"concept":"K3-2-u4-C20","difficulty":2,"kind":"mc","stem":"상황 ㉯ 예시 대본에서 지원이의 말 “아…… 어떡하죠? 저 친구랑 만나기로 약속한 시간이라 나가 봐야 하거든요.”에 들어 있는 것은 무엇인가요?","options":[{"t":"도와드릴 수 없는 까닭","correct":true},{"t":"부탁을 들어드리겠다는 약속","mis":"K3-2-u4-X20"},{"t":"어머니께 다시 부탁하라는 말","mis":"K3-2-u4-X33"},{"t":"친구에게 전화하라는 부탁","mis":"K3-2-u4-X33"}],"explanation":["지원이는 친구와 만나기로 약속한 시간이라고 말했어요.","그래서 분리배출을 도와드릴 수 없어요.","거절할 때에는 까닭을 자세히 말씀드려요."],"asset":{"type":"passage","lines":["어머니: 지원아, 지금 시간 괜찮니? 분리배출하는 것 좀 도와줄래?","지원: 아…… 어떡하죠? 저 친구랑 만나기로 약속한 시간이라","나가 봐야 하거든요.","어머니: 그렇구나, 알았어.","지원: 죄송해요. 다음에는 꼭 도와드릴게요."],"title":"역할놀이 대본 — 상황 ㉯ (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_challenge#2','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C21',2,'ox','auto','전화 대화는 서로 볼 수 없으니 표정, 몸짓, 말투는 전혀 신경 쓰지 않아도 돼요.',ARRAY['K3-2-u4-X27']::text[],false,'{"seq":2,"concept":"K3-2-u4-C21","difficulty":2,"kind":"ox","stem":"전화 대화는 서로 볼 수 없으니 표정, 몸짓, 말투는 전혀 신경 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"전화에서도 말투에 마음이 드러나고, 통화에 집중하며 “응.”, “그렇구나.”로 호응해야 해요.","correct":true},{"t":"보이지 않으니 표정과 말투는 아무 뜻이 없어요.","mis":"K3-2-u4-X27"}],"mis":"K3-2-u4-X27","explanation":["얼굴은 안 보여도 목소리의 말투는 들려요.","평소보다 또박또박 말하면 상대가 잘 들을 수 있어요.","짧은 호응으로 잘 듣고 있다는 것을 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_challenge#3','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C15',3,'mc','auto','지원이는 마지막에 “죄송해요. 다음에는 꼭 도와드릴게요.”라고 했어요. 이 말에 담긴 마음으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X33','K3-2-u4-X19','K3-2-u4-X16']::text[],false,'{"seq":3,"concept":"K3-2-u4-C15","difficulty":3,"kind":"mc","stem":"지원이는 마지막에 “죄송해요. 다음에는 꼭 도와드릴게요.”라고 했어요. 이 말에 담긴 마음으로 알맞은 것은 무엇인가요?","options":[{"t":"거절하면서도 어머니께 미안한 마음과 다음에 돕고 싶은 마음","correct":true},{"t":"지금 바로 도와드리겠다는 마음","mis":"K3-2-u4-X33"},{"t":"다시는 부탁하지 마시라는 마음","mis":"K3-2-u4-X19"},{"t":"거절했으니 예절을 어겼다는 마음","mis":"K3-2-u4-X16"}],"explanation":["지원이는 도와드리지 못해 죄송했어요.","그래서 다음에는 꼭 돕겠다고 말씀드렸어요.","거절당하는 사람의 마음을 헤아린 말이에요."],"asset":{"type":"passage","lines":["어머니: 지원아, 지금 시간 괜찮니? 분리배출하는 것 좀 도와줄래?","지원: 아…… 어떡하죠? 저 친구랑 만나기로 약속한 시간이라","나가 봐야 하거든요.","어머니: 그렇구나, 알았어.","지원: 죄송해요. 다음에는 꼭 도와드릴게요."],"title":"역할놀이 대본 — 상황 ㉯ (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_challenge#4','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C20',3,'mc','auto','상황 ㉮에서 친구와 언제 어디에서 만날지 의견을 나눌 때 지켜야 할 대화 예절로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X26','K3-2-u4-X17','K3-2-u4-X24']::text[],false,'{"seq":4,"concept":"K3-2-u4-C20","difficulty":3,"kind":"mc","stem":"상황 ㉮에서 친구와 언제 어디에서 만날지 의견을 나눌 때 지켜야 할 대화 예절로 알맞은 것은 무엇인가요?","options":[{"t":"상대의 말을 끊고 자신의 말만 하지 않고, 상대의 의견을 무시하거나 내 의견만 강요하지 않는다","correct":true},{"t":"내가 정한 시간과 장소를 친구에게 그대로 따르게 한다","mis":"K3-2-u4-X26"},{"t":"의견이 다르면 아무 말도 하지 않는다","mis":"K3-2-u4-X17"},{"t":"친구가 말할 때 다른 이야기로 바꾼다","mis":"K3-2-u4-X24"}],"explanation":["약속은 두 사람이 함께 정하는 것이에요.","상대의 말을 끝까지 듣고 내 의견도 말해요.","내 의견만 강요하면 상대의 기분이 상할 수 있어요."],"asset":{"type":"passage","lines":["상황 ㉮ — 친구와 언제 어디에서 만날지 전화로 약속을 정하는 상황","상황 ㉯ — 어머니께서 분리배출을 도와 달라고 하시는데","도와드릴 수 없는 상황"],"title":"『국어』 206쪽 대화 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_challenge#5','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C22',3,'mc','auto','역할놀이 대본을 쓸 때 가장 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u4-X28','K3-2-u4-X30','K3-2-u4-X22']::text[],false,'{"seq":5,"concept":"K3-2-u4-C22","difficulty":3,"kind":"mc","stem":"역할놀이 대본을 쓸 때 가장 알맞은 방법은 무엇인가요?","options":[{"t":"말차례를 두 번 이상 주고받으며, 상황에 알맞은 대화 예절이 들어가게 쓴다","correct":true},{"t":"칸만 채우게 한마디씩 짧게 쓴다","mis":"K3-2-u4-X28"},{"t":"친구들이 웃을 만한 재미있는 말만 넣는다","mis":"K3-2-u4-X30"},{"t":"상황은 살피지 않고 생각나는 대로 쓴다","mis":"K3-2-u4-X22"}],"explanation":["대본은 단답식이 아니라 말을 여러 번 주고받게 써요.","대화 상대·목적·방식을 분석한 내용이 들어가야 해요.","역할놀이에만 관심을 두지 말고 배울 예절을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_challenge#6','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C21',3,'error','auto','『국어』 208쪽 (2)에서 표정, 몸짓, 말투에 주의하며 대화하는 방법을 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X27','K3-2-u4-X23']::text[],false,'{"seq":6,"concept":"K3-2-u4-C21","difficulty":3,"kind":"error","stem":"『국어』 208쪽 (2)에서 표정, 몸짓, 말투에 주의하며 대화하는 방법을 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서: 전화는 얼굴이 안 보이니 끄덕여도 소용없고, 아무 말 없이 듣기만 하면 돼.","correct":true,"mis_target":"K3-2-u4-X27"},{"t":"예린: 어른과 대화할 때에는 공손한 말투가 좋겠어.","mis":"K3-2-u4-X23"},{"t":"하준: 도와드리지 못해 죄송한 마음이 표정에 드러나면 좋겠어.","mis":"K3-2-u4-X27"}],"explanation":["전화에서는 “응.”, “그렇구나.”로 잘 듣고 있음을 알려요.","어른께는 공손한 말투로 말해요.","죄송한 마음은 표정에도 드러나야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_challenge#7','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C22',3,'mc','auto','점검표에서 짝의 ‘대화 목적에 알맞은 대화 예절’ 칸이 ●(보통임)이었어요. 가장 알맞게 한 것은 무엇인가요?',ARRAY['K3-2-u4-X28','K3-2-u4-X27']::text[],false,'{"seq":7,"concept":"K3-2-u4-C22","difficulty":3,"kind":"mc","stem":"점검표에서 짝의 ‘대화 목적에 알맞은 대화 예절’ 칸이 ●(보통임)이었어요. 가장 알맞게 한 것은 무엇인가요?","options":[{"t":"짝과 함께 부족한 부분을 찾고 어떻게 고칠지 이야기한다","correct":true},{"t":"짝이 속상하지 않게 ●●●로 바꾸어 칠해 준다","mis":"K3-2-u4-X28"},{"t":"점검표를 다 칠했으니 그대로 끝낸다","mis":"K3-2-u4-X28"},{"t":"짝에게 역할놀이를 잘 못한다고 말한다","mis":"K3-2-u4-X27"}],"explanation":["점검표는 칸을 채우거나 점수를 고치려는 것이 아니에요.","부족한 부분을 어떻게 고칠지 생각하려고 보는 것이에요.","짝의 기분을 헤아리며 고칠 점을 함께 찾아요."],"asset":{"type":"passage","lines":["대화 상대에 알맞은 대화 예절을 지켰나요?   나 ○○○ · 짝 ○○○","대화 목적에 알맞은 대화 예절을 지켰나요?   나 ○○○ · 짝 ○○○","대화 방식에 알맞은 대화 예절을 지켰나요?   나 ○○○ · 짝 ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"역할놀이 점검표 — 『국어』 209쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_challenge#8','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C20',4,'essay','teacher','상황 ㉯(어머니께서 분리배출을 도와 달라고 하시는데 도와드릴 수 없는 상황)를 골라 역할놀이 대본을 쓰세요. 말차례를 두 번 이상 주고받고, 거절할 때의 예절이 드러나게 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u4-C20","difficulty":4,"kind":"essay","stem":"상황 ㉯(어머니께서 분리배출을 도와 달라고 하시는데 도와드릴 수 없는 상황)를 골라 역할놀이 대본을 쓰세요. 말차례를 두 번 이상 주고받고, 거절할 때의 예절이 드러나게 쓰세요.","answer_guide":{"answer":"예: 어머니: 지원아, 분리배출하는 것 좀 도와줄 수 있니? / 나: 어머니, 죄송해요. 지금 숙제를 학교에 내야 해서 마무리하는 중이에요. / 어머니: 그래? 아쉽지만 어쩔 수 없네. / 나: 숙제 다 하고 나서 남은 것은 제가 정리해 드릴게요. / 어머니: 그래, 알았어.","scoring_points":["말차례를 두 번 이상 주고받았는가","높임 표현과 공손한 태도로 말했는가","죄송한 마음과 도와드릴 수 없는 까닭을 말했는가"]},"explanation":["어머니는 웃어른이시니 높임 표현을 써요.","거절할 때에는 죄송한 마음과 까닭을 함께 말해요.","할 수 있는 만큼 돕겠다는 말도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_challenge#9','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C21',4,'essay','teacher','상황 ㉮(전화로 약속 정하기)와 상황 ㉯(어머니의 부탁 거절하기)에서 각각 어울리는 표정·몸짓·말투를 한 가지씩 쓰고, 그렇게 하면 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C21","difficulty":4,"kind":"essay","stem":"상황 ㉮(전화로 약속 정하기)와 상황 ㉯(어머니의 부탁 거절하기)에서 각각 어울리는 표정·몸짓·말투를 한 가지씩 쓰고, 그렇게 하면 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 상황 ㉮ — 평소보다 또박또박 말하고 “응.”, “그렇구나.”로 호응한다. 얼굴이 보이지 않아도 잘 듣고 있다는 것을 알릴 수 있다. 상황 ㉯ — 어머니를 바라보며 죄송한 표정과 공손한 말투로 말한다. 거절당하는 어머니의 마음이 덜 서운하시도록.","scoring_points":["상황 ㉮에 어울리는 말투나 호응을 썼는가","상황 ㉯에 어울리는 표정·몸짓·말투를 썼는가","각각 그렇게 하면 좋은 까닭을 썼는가"]},"explanation":["전화는 얼굴이 보이지 않는 대화예요.","웃어른의 부탁을 거절할 때는 죄송한 마음이 표정에 드러나야 해요.","같은 말도 표정, 몸짓, 말투에 따라 다르게 들려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L10_challenge#10','kor',3,2,'u4','L10','tb_g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C20',4,'mc','auto','상황 ㉮ 역할놀이 대본 쓰기예요. 마지막 친구의 말 다음에 ‘나’가 할 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X25','K3-2-u4-X37']::text[],false,'{"seq":10,"concept":"K3-2-u4-C20","difficulty":4,"kind":"mc","stem":"상황 ㉮ 역할놀이 대본 쓰기예요. 마지막 친구의 말 다음에 ‘나’가 할 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“응, 알았어. 그럼 내일 2시에 놀이터에서 보자. 안녕.”","correct":true},{"t":"(아무 말 없이 전화를 끊는다.)","mis":"K3-2-u4-X25"},{"t":"“잠깐, 그런데 내 얘기 더 들어 봐. 어제 있었던 일인데…….”","mis":"K3-2-u4-X37"},{"t":"“그래.” (바로 끊는다.)","mis":"K3-2-u4-X25"}],"explanation":["친구는 동생이 불러서 가 봐야 한다고 했어요.","친구의 상황을 헤아려 약속을 다시 확인하고 끝인사를 해요.","끝인사 없이 끊거나 붙잡고 내 말만 하지 않아요."],"asset":{"type":"passage","lines":["친구: 여보세요?","나: (            )","친구: (     )(이)구나. 무슨 일이야?","나: (            )","친구: 그럼 2시에 놀이터에서 볼까? 괜찮아?","나: (            )","친구: 나도 좋아. 난 동생이 불러서 가 봐야 할 것 같아. 내일 놀이터에서 보자.","나: (            )"],"title":"역할놀이 대본 쓰기 — 상황 ㉮"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_basic#1','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C24',1,'mc','auto','『국어』 210~211쪽 「이런 활동 어때요」에 나온 두 가지 활동은 무엇인가요?',ARRAY['K3-2-u4-X30']::text[],false,'{"seq":1,"concept":"K3-2-u4-C24","difficulty":1,"kind":"mc","stem":"『국어』 210~211쪽 「이런 활동 어때요」에 나온 두 가지 활동은 무엇인가요?","options":[{"t":"높임의 뜻이 있는 낱말 기억 놀이 하기 · 대화 예절을 실천하는 다짐판 만들기","correct":true},{"t":"가장 빨리 끝나는 그림 그리기 · 받아쓰기 시합","mis":"K3-2-u4-X30"},{"t":"높임의 뜻이 있는 낱말 기억 놀이 하기 · 가장 재미있는 만화 보기","mis":"K3-2-u4-X30"},{"t":"대화 예절을 실천하는 다짐판 만들기 · 줄넘기 시합","mis":"K3-2-u4-X30"}],"explanation":["이런 활동 1은 높임의 뜻이 있는 낱말 기억 놀이예요.","이런 활동 2는 대화 예절을 실천하는 다짐판 만들기예요.","두 활동 모두 이 단원에서 배운 것을 실천하는 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_basic#2','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C24',1,'mc','auto','낱말 기억 놀이에서 뒤집은 두 카드가 ‘밥’과 ‘진지’처럼 본래의 낱말과 높임의 뜻이 있는 낱말의 뜻이 같으면 어떻게 하나요?',ARRAY['K3-2-u4-X07']::text[],false,'{"seq":2,"concept":"K3-2-u4-C24","difficulty":1,"kind":"mc","stem":"낱말 기억 놀이에서 뒤집은 두 카드가 ‘밥’과 ‘진지’처럼 본래의 낱말과 높임의 뜻이 있는 낱말의 뜻이 같으면 어떻게 하나요?","options":[{"t":"카드를 가져간다","correct":true},{"t":"카드를 다시 뒤집어 놓는다","mis":"K3-2-u4-X07"},{"t":"카드를 짝에게 준다","mis":"K3-2-u4-X07"}],"explanation":["놀이 방법 ④를 다시 읽어요.","뜻이 같으면 카드를 가져가고, 다르면 다시 뒤집어 놓아요.","카드를 많이 가져간 사람이 이겨요."],"asset":{"type":"passage","lines":["① 카드를 뒤집어 색깔별로 가지런히 놓는다.","② 짝과 가위바위보를 한다.","③ 이긴 사람이 먼저 카드를 색깔별로 각각 한 장씩 뒤집는다.","④ 본래의 낱말과 높임의 뜻이 있는 낱말의 뜻이 같으면 카드를 가져가고,","뜻이 다르면 카드를 다시 뒤집어 놓는다.","⑤ 카드를 많이 가져간 사람이 이긴다."],"title":"높임의 뜻이 있는 낱말 기억 놀이 — 『국어』 210쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_basic#3','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C6',1,'match','auto','낱말 기억 놀이를 하기 전에 본래의 낱말과 높임의 뜻이 있는 낱말을 짝 지어 보세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u4-C6","difficulty":1,"kind":"match","stem":"낱말 기억 놀이를 하기 전에 본래의 낱말과 높임의 뜻이 있는 낱말을 짝 지어 보세요.","pairs":[{"l":"밥","r":"진지"},{"l":"말","r":"말씀"},{"l":"먹다","r":"드시다"},{"l":"주다","r":"드리다"}],"mis":"K3-2-u4-X07","explanation":["「아드님, 진지 드세요」에 나온 높임 낱말 짝이에요.","밥-진지, 말-말씀, 먹다-드시다, 주다-드리다예요.","카드의 위치를 기억하며 짝을 맞추면 낱말도 기억돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_basic#4','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C23',1,'mc','auto','『국어』 211쪽 실천 다짐판에는 무엇을 쓰나요?',ARRAY['K3-2-u4-X29','K3-2-u4-X30']::text[],false,'{"seq":4,"concept":"K3-2-u4-C23","difficulty":1,"kind":"mc","stem":"『국어』 211쪽 실천 다짐판에는 무엇을 쓰나요?","options":[{"t":"꼭 실천하고 싶은 대화 예절 한 가지를 간단한 문장으로","correct":true},{"t":"이 단원에서 배운 대화 예절을 모두","mis":"K3-2-u4-X29"},{"t":"친구가 쓴 다짐을 그대로","mis":"K3-2-u4-X29"},{"t":"가장 재미있었던 활동의 이름","mis":"K3-2-u4-X30"}],"explanation":["다짐판에는 꼭 실천하고 싶은 대화 예절 한 가지를 써요.","오유찬은 “친구의 말을 존중하고 고운 말을 사용하겠습니다.”라고 썼어요.","어떤 예절을 고를지는 사람마다 달라요."],"asset":{"type":"passage","lines":["실천 다짐판 (오유찬) — 친구의 말을 존중하고 고운 말을 사용하겠습니다.","실천 다짐판 (김수빈) — 친구의 말을 끝까지 귀담아듣겠습니다.","[다짐판 아래] 목·금·토·일 칸에 붙임딱지 — 잘했을 때 · 보통일 때 · 노력이 필요할 때"],"title":"대화 예절을 실천하는 다짐판 — 『국어』 211쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_basic#5','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C23',2,'mc','auto','실천 다짐판에 쓸 다짐으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X29']::text[],false,'{"seq":5,"concept":"K3-2-u4-C23","difficulty":2,"kind":"mc","stem":"실천 다짐판에 쓸 다짐으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"쉬는 시간에 친구가 말할 때 끝까지 듣고 나서 내 말을 하겠습니다.","correct":true},{"t":"착한 사람이 되겠습니다.","mis":"K3-2-u4-X29"},{"t":"모든 대화 예절을 다 지키겠습니다.","mis":"K3-2-u4-X29"},{"t":"친구와 똑같은 다짐을 쓰겠습니다.","mis":"K3-2-u4-X29"}],"explanation":["다짐은 구체적인 상황과 지킬 점이 드러나게 써요.","언제(쉬는 시간), 무엇을(끝까지 듣기) 할지 드러나야 해요.","그래야 실천했는지 점검할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_basic#6','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C23',2,'mc','auto','다짐판 아래 목·금·토·일 칸에 붙임딱지를 붙이는 까닭은 무엇인가요?',ARRAY['K3-2-u4-X28','K3-2-u4-X30']::text[],false,'{"seq":6,"concept":"K3-2-u4-C23","difficulty":2,"kind":"mc","stem":"다짐판 아래 목·금·토·일 칸에 붙임딱지를 붙이는 까닭은 무엇인가요?","options":[{"t":"날마다 대화 예절을 실천했는지 스스로 점검하며 습관이 되게 하려고","correct":true},{"t":"칸을 모두 예쁘게 채우려고","mis":"K3-2-u4-X28"},{"t":"잘하지 못한 날에도 잘했을 때 붙임딱지를 붙여 점수를 높이려고","mis":"K3-2-u4-X28"},{"t":"붙임딱지를 가장 많이 모은 사람이 이기려고","mis":"K3-2-u4-X30"}],"explanation":["잘했을 때·보통일 때·노력이 필요할 때 붙임딱지가 달라요.","솔직하게 붙여야 고칠 점을 알 수 있어요.","점검하며 실천하면 대화 예절이 습관이 돼요."],"asset":{"type":"passage","lines":["실천 다짐판 (오유찬) — 친구의 말을 존중하고 고운 말을 사용하겠습니다.","실천 다짐판 (김수빈) — 친구의 말을 끝까지 귀담아듣겠습니다.","[다짐판 아래] 목·금·토·일 칸에 붙임딱지 — 잘했을 때 · 보통일 때 · 노력이 필요할 때"],"title":"대화 예절을 실천하는 다짐판 — 『국어』 211쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_basic#7','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C24',2,'mc','auto','우리 반에서 할 실천 활동을 정할 때 가장 알맞은 기준은 무엇인가요?',ARRAY['K3-2-u4-X30']::text[],false,'{"seq":7,"concept":"K3-2-u4-C24","difficulty":2,"kind":"mc","stem":"우리 반에서 할 실천 활동을 정할 때 가장 알맞은 기준은 무엇인가요?","options":[{"t":"이 단원에서 배운 높임 표현이나 대화 예절을 익히고 실천할 수 있는 활동","correct":true},{"t":"가장 재미있어 보이는 활동","mis":"K3-2-u4-X30"},{"t":"가장 빨리 끝나는 활동","mis":"K3-2-u4-X30"},{"t":"준비물이 없는 활동이면 무엇이든","mis":"K3-2-u4-X30"}],"explanation":["실천 시간은 배운 내용을 생활에서 써 보는 시간이에요.","재미와 빠르기보다 단원의 학습 목표에 맞는지 살펴요.","높임 표현이나 대화 예절 가운데 한 가지에 초점을 두어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_basic#8','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C9',2,'mc','auto','우리 반에서 정한 활동 예시 1 만화예요. 불퉁이의 말 “할머니, 생일 축하해. 올해 나이가 몇 살이야?”를 알맞은 높임 표현으로 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X35','K3-2-u4-X11','K3-2-u4-X10']::text[],false,'{"seq":8,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"우리 반에서 정한 활동 예시 1 만화예요. 불퉁이의 말 “할머니, 생일 축하해. 올해 나이가 몇 살이야?”를 알맞은 높임 표현으로 고친 것은 무엇인가요?","options":[{"t":"“할머니, 생신 축하드려요. 올해 연세가 어떻게 되세요?”","correct":true},{"t":"“할머니, 생일 축하해요. 올해 나이가 몇 살이세요?”","mis":"K3-2-u4-X35"},{"t":"“할머니께서, 생신 축하하셔. 올해 연세가 몇 살이야?”","mis":"K3-2-u4-X11"},{"t":"“할머니, 생신 축하해. 올해 연세가 몇 살이야?”","mis":"K3-2-u4-X10"}],"explanation":["‘생일’은 ‘생신’, ‘나이’는 ‘연세’로 높여요.","‘축하해’는 ‘축하드려요’로 바꾸어요.","연세는 “몇 살이세요?”보다 “어떻게 되세요?”라고 여쭈어요."],"asset":{"type":"passage","lines":["불퉁: “할머니, 생일 축하해. 올해 나이가 몇 살이야?”","엄마: “불퉁아, 할머니께 반말하면 못써.”","불퉁: “알았어. 아빠 안 먹어? 나 먼저 먹는다?”","아빠: “안 되겠다. 지금 당장 배워야지!”"],"title":"「서로서로 통하는 말」 만화 가운데 (박은정 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_basic#9','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C9',2,'mc','auto','불퉁이의 말 “알았어. 아빠 안 먹어? 나 먼저 먹는다?”를 알맞은 높임 표현으로 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X35','K3-2-u4-X40']::text[],false,'{"seq":9,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"불퉁이의 말 “알았어. 아빠 안 먹어? 나 먼저 먹는다?”를 알맞은 높임 표현으로 고친 것은 무엇인가요?","options":[{"t":"“알겠어요. 아빠는 안 드세요? 저 먼저 먹을게요.”","correct":true},{"t":"“알았어요. 아빠 안 잡수셔? 나 먼저 잡수신다?”","mis":"K3-2-u4-X11"},{"t":"“알았어. 아빠 진지 안 먹어? 나 먼저 먹는다?”","mis":"K3-2-u4-X35"},{"t":"“알았어요. 아빠 안 먹어요? 나 먼저 먹으실게요.”","mis":"K3-2-u4-X40"}],"explanation":["먹는 사람이 아빠일 때는 ‘드시다’를 써요.","먹는 사람이 나일 때는 ‘먹다’를 쓰고 ‘나’는 ‘저’로 낮추어요.","말끝에 ‘요’를 붙여 듣는 아빠를 높여요."],"asset":{"type":"passage","lines":["불퉁: “할머니, 생일 축하해. 올해 나이가 몇 살이야?”","엄마: “불퉁아, 할머니께 반말하면 못써.”","불퉁: “알았어. 아빠 안 먹어? 나 먼저 먹는다?”","아빠: “안 되겠다. 지금 당장 배워야지!”"],"title":"「서로서로 통하는 말」 만화 가운데 (박은정 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_basic#10','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C24',3,'mc','auto','우리 반에서 정한 활동 예시 2 「대화 예절을 생각하며 공익 광고 감상하기」에서 할 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X30','K3-2-u4-X18']::text[],false,'{"seq":10,"concept":"K3-2-u4-C24","difficulty":3,"kind":"mc","stem":"우리 반에서 정한 활동 예시 2 「대화 예절을 생각하며 공익 광고 감상하기」에서 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"광고를 보며 느낀 점과 인물들이 지켜야 할 대화 예절을 생각하고, 인물들에게 해 주고 싶은 말을 편지로 쓴다","correct":true},{"t":"광고 노래를 따라 부르기만 한다","mis":"K3-2-u4-X30"},{"t":"광고에 나온 물건의 값을 알아본다","mis":"K3-2-u4-X18"},{"t":"가장 웃긴 장면만 골라 흉내 낸다","mis":"K3-2-u4-X30"}],"explanation":["공익 광고는 사람들에게 알리고 싶은 생각을 담은 광고예요.","광고 속 인물들이 지켜야 할 대화 예절을 생각해요.","인물들에게 해 주고 싶은 말을 편지로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_challenge#1','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C26',2,'mc','auto','『국어』 215쪽 글씨 쓰기예요. ‘얘기’의 첫 글자에 쓰인 모음자는 무엇인가요?',ARRAY['K3-2-u4-X32']::text[],false,'{"seq":1,"concept":"K3-2-u4-C26","difficulty":2,"kind":"mc","stem":"『국어』 215쪽 글씨 쓰기예요. ‘얘기’의 첫 글자에 쓰인 모음자는 무엇인가요?","options":[{"t":"ㅒ","correct":true},{"t":"ㅐ","mis":"K3-2-u4-X32"},{"t":"ㅔ","mis":"K3-2-u4-X32"},{"t":"ㅖ","mis":"K3-2-u4-X32"}],"explanation":["‘얘’는 ㅇ과 ㅒ가 만난 글자예요.","ㅒ는 ㅐ에 짧은 획이 하나 더 있어 짧은 획이 두 개예요.","ㅖ는 ‘예절’의 ‘예’에 쓰여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_challenge#2','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C26',2,'mc','auto','‘배려 · 샘물 · 메다’ 가운데 ‘메다’의 첫 글자에 쓰인 모음자는 무엇인가요?',ARRAY['K3-2-u4-X32']::text[],false,'{"seq":2,"concept":"K3-2-u4-C26","difficulty":2,"kind":"mc","stem":"‘배려 · 샘물 · 메다’ 가운데 ‘메다’의 첫 글자에 쓰인 모음자는 무엇인가요?","options":[{"t":"ㅔ","correct":true},{"t":"ㅐ","mis":"K3-2-u4-X32"},{"t":"ㅖ","mis":"K3-2-u4-X32"}],"explanation":["‘배’와 ‘샘’에는 ㅐ가 쓰였어요.","‘메다’의 ‘메’에는 ㅔ가 쓰였어요.","ㅐ와 ㅔ는 가로획의 자리가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_challenge#3','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C25',3,'mc','auto','『국어』 214쪽이에요. 방언의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X31']::text[],false,'{"seq":3,"concept":"K3-2-u4-C25","difficulty":3,"kind":"mc","stem":"『국어』 214쪽이에요. 방언의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"어느 한 지역에서만 쓰는, 표준어가 아닌 말","correct":true},{"t":"잘못 배워서 틀리게 쓰는 말","mis":"K3-2-u4-X31"},{"t":"옛날에만 쓰고 지금은 쓰지 않는 말","mis":"K3-2-u4-X31"},{"t":"아무 뜻 없이 지어낸 말","mis":"K3-2-u4-X31"}],"explanation":["방언은 어느 한 지역에서만 쓰는 말이에요.","표준어가 아닐 뿐 틀린 말이 아니에요.","같은 것을 지역마다 다르게 부르기도 해요."],"asset":{"type":"passage","lines":["방언: 가우, 가새, 가시개  →  표준어: (     )","방언: 개구락지, 까구리, 깨구리  →  표준어: (     )","방언이란 어느 한 지역에서만 쓰는, 표준어가 아닌 말을 뜻해요."],"title":"기초 다지기 2 — 『국어』 214쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_challenge#4','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C25',3,'sa','auto','‘가우, 가새, 가시개’는 지역마다 다르게 부르는 방언이에요. 표준어로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u4-C25","difficulty":3,"kind":"sa","stem":"‘가우, 가새, 가시개’는 지역마다 다르게 부르는 방언이에요. 표준어로 쓰세요.","answer":["가위"],"explanation":["세 방언은 모두 같은 물건을 가리켜요.","종이를 자를 때 쓰는 물건이에요.","표준어는 ‘가위’예요."],"asset":{"type":"passage","lines":["방언: 가우, 가새, 가시개  →  표준어: (     )","방언: 개구락지, 까구리, 깨구리  →  표준어: (     )","방언이란 어느 한 지역에서만 쓰는, 표준어가 아닌 말을 뜻해요."],"title":"기초 다지기 2 — 『국어』 214쪽"},"mis":"K3-2-u4-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_challenge#5','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C25',3,'ox','auto','방언은 표준어가 아니니까 틀린 말이에요.',ARRAY['K3-2-u4-X31']::text[],false,'{"seq":5,"concept":"K3-2-u4-C25","difficulty":3,"kind":"ox","stem":"방언은 표준어가 아니니까 틀린 말이에요.","answer":"X","reason_options":[{"t":"방언은 어느 한 지역에서만 쓰는 말일 뿐 틀린 말이 아니에요.","correct":true},{"t":"표준어가 아닌 말은 모두 틀린 말이에요.","mis":"K3-2-u4-X31"}],"mis":"K3-2-u4-X31","explanation":["방언은 그 지역 사람들이 오랫동안 써 온 말이에요.","다른 것은 틀린 것이 아니에요.","여러 사람이 함께하는 자리에서는 표준어를 쓰기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_challenge#6','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C18',3,'mc','auto','『국어』 214쪽 기초 다지기 1이에요. 다른 사람과 전화로 대화할 때 지켜야 할 예절로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X25','K3-2-u4-X27']::text[],false,'{"seq":6,"concept":"K3-2-u4-C18","difficulty":3,"kind":"mc","stem":"『국어』 214쪽 기초 다지기 1이에요. 다른 사람과 전화로 대화할 때 지켜야 할 예절로 알맞지 않은 것은 무엇인가요?","options":[{"t":"상대가 전화를 받으면 자신이 하고 싶은 말부터 먼저 한다","correct":true},{"t":"공공장소에서는 작은 목소리로 통화한다","mis":"K3-2-u4-X21"},{"t":"상대의 상황을 생각하여 대화한다","mis":"K3-2-u4-X25"},{"t":"상대가 말할 때에는 귀 기울여 듣는다","mis":"K3-2-u4-X27"}],"explanation":["전화가 연결되면 먼저 자신이 누구인지 밝히고 상대를 확인해요.","받자마자 내 말부터 하면 상대가 당황할 수 있어요.","전화를 끊고 싶다고 언제든 바로 끊는 것도 알맞지 않아요."],"asset":{"type":"passage","lines":["① 자신이 누구인지 밝히고 상대를 확인한다.","② 전화를 끊고 싶으면 언제든지 바로 전화를 끊는다.","③ 상대가 전화를 받으면 자신이 하고 싶은 말부터 먼저 한다.","④ 공공장소에서는 작은 목소리로 통화한다.","⑤ 상대가 말할 때에는 귀 기울여 듣는다.","⑥ 상대의 상황을 생각하여 대화한다."],"title":"기초 다지기 1 — 『국어』 214쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_challenge#7','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C23',3,'mc','auto','『국어』 213쪽 생활 속으로예요. 김민수의 다짐 “부탁을 들어준 친구에게 고마운 마음을 표현하겠습니다.”가 실천하기 좋은 까닭은 무엇인가요?',ARRAY['K3-2-u4-X29']::text[],false,'{"seq":7,"concept":"K3-2-u4-C23","difficulty":3,"kind":"mc","stem":"『국어』 213쪽 생활 속으로예요. 김민수의 다짐 “부탁을 들어준 친구에게 고마운 마음을 표현하겠습니다.”가 실천하기 좋은 까닭은 무엇인가요?","options":[{"t":"어떤 상황에서 어떤 내용을 실천할지 구체적으로 드러나 있기 때문","correct":true},{"t":"가장 길게 쓴 다짐이기 때문","mis":"K3-2-u4-X29"},{"t":"다른 친구의 다짐과 똑같기 때문","mis":"K3-2-u4-X29"},{"t":"지킬 점이 여러 가지 들어 있기 때문","mis":"K3-2-u4-X29"}],"explanation":["‘부탁을 들어준 친구에게’ — 어떤 상황인지 드러나요.","‘고마운 마음을 표현하겠습니다’ — 무엇을 할지 드러나요.","이렇게 써야 실천하고 점검하기 쉬워요."],"asset":{"type":"passage","lines":["정한솔 — 부모님이나 선생님과 대화할 때 높임 표현을 바르게 사용하겠습니다.","최연재 — 친구들과 대화할 때 상황에 맞는 대화 예절을 지키도록 노력하겠습니다.","김민수 — 부탁을 들어준 친구에게 고마운 마음을 표현하겠습니다."],"title":"생활 속으로 — 우리 모두 대화 예절을 실천할 것을 다짐해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_challenge#8','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C23',4,'essay','teacher','꼭 실천하고 싶은 대화 예절을 한 가지 골라 실천 다짐판에 쓸 문장을 쓰고, 언제 어떻게 실천했는지 점검할 방법도 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u4-C23","difficulty":4,"kind":"essay","stem":"꼭 실천하고 싶은 대화 예절을 한 가지 골라 실천 다짐판에 쓸 문장을 쓰고, 언제 어떻게 실천했는지 점검할 방법도 쓰세요.","answer_guide":{"answer":"예: 다짐 — 할머니와 통화할 때 할머니께서 먼저 끊으신 뒤에 전화를 끊겠습니다. 점검 — 통화할 때마다 다짐판의 그날 칸에 잘했을 때·보통일 때·노력이 필요할 때 붙임딱지를 솔직하게 붙인다.","scoring_points":["실천하고 싶은 대화 예절을 한 가지 골랐는가","구체적인 상황과 지킬 점이 드러나게 문장을 썼는가","실천 결과를 점검할 방법을 썼는가"]},"explanation":["이 단원에서 배운 대화 예절 가운데 내가 꼭 지키고 싶은 것을 골라요.","언제, 무엇을 할지 드러나게 한 문장으로 써요.","붙임딱지로 날마다 점검하면 습관이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_challenge#9','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C9',4,'essay','teacher','우리 반에서 정한 활동 예시 1 만화에서 알맞지 않은 높임 표현을 두 군데 찾아 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C9","difficulty":4,"kind":"essay","stem":"우리 반에서 정한 활동 예시 1 만화에서 알맞지 않은 높임 표현을 두 군데 찾아 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: ① “할머니, 생일 축하해. 올해 나이가 몇 살이야?” → “할머니, 생신 축하드려요. 올해 연세가 어떻게 되세요?” ② “알았어. 아빠 안 먹어? 나 먼저 먹는다?” → “알겠어요. 아빠는 안 드세요? 저 먼저 먹을게요.”","scoring_points":["알맞지 않은 높임 표현을 두 군데 찾았는가","높임의 뜻이 있는 낱말(생신·연세·드시다)로 고쳤는가","듣는 사람을 높이는 ‘요’와 나를 낮추는 ‘저’를 알맞게 썼는가"]},"explanation":["불퉁이가 누구에게 말하는지 먼저 찾아요.","할머니와 아빠께 쓰는 높임의 뜻이 있는 낱말을 떠올려요.","내가 하는 일에는 ‘-시-’를 붙이지 않아요."],"asset":{"type":"passage","lines":["불퉁: “할머니, 생일 축하해. 올해 나이가 몇 살이야?”","엄마: “불퉁아, 할머니께 반말하면 못써.”","불퉁: “알았어. 아빠 안 먹어? 나 먼저 먹는다?”","아빠: “안 되겠다. 지금 당장 배워야지!”"],"title":"「서로서로 통하는 말」 만화 가운데 (박은정 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_L12_challenge#10','kor',3,2,'u4','L12','tb_g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C25',4,'mc','auto','방언을 더 알아보려고 ‘나만의 방언 사전’을 만들어요. 가장 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u4-X31']::text[],false,'{"seq":10,"concept":"K3-2-u4-C25","difficulty":4,"kind":"mc","stem":"방언을 더 알아보려고 ‘나만의 방언 사전’을 만들어요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"누리집을 찾아보거나 둘레 어른께 여쭈어 실제로 쓰는 방언을 조사하고, 표준어와 뜻을 함께 정리한다","correct":true},{"t":"그럴듯한 낱말을 지어내서 방언이라고 쓴다","mis":"K3-2-u4-X31"},{"t":"방언은 틀린 말이니 표준어로 고친 말만 쓴다","mis":"K3-2-u4-X31"},{"t":"방언 낱말만 많이 적고 뜻은 적지 않는다","mis":"K3-2-u4-X31"}],"explanation":["방언은 실제로 그 지역에서 쓰는 말이라 지어내지 않아요.","조사한 방언과 표준어, 그 뜻을 함께 정리해요.","낱말을 찾는 데서 그치지 않고 뜻을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#1','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C7',1,'ox','auto','『국어』 213쪽 스스로 확인하기 ①이에요. 「대화하는 상대가 웃어른일 때에는 ‘-시-’, ‘-습니다’와 같은 높임 표현을 사용한다.」는 알맞은 설명이에요.',ARRAY['K3-2-u4-X10']::text[],false,'{"seq":1,"concept":"K3-2-u4-C7","difficulty":1,"kind":"ox","stem":"『국어』 213쪽 스스로 확인하기 ①이에요. 「대화하는 상대가 웃어른일 때에는 ‘-시-’, ‘-습니다’와 같은 높임 표현을 사용한다.」는 알맞은 설명이에요.","answer":"O","reason_options":[{"t":"웃어른과 대화할 때에는 ‘-시-’, ‘-습니다’ 같은 높임 표현을 써요.","correct":true},{"t":"웃어른과 대화할 때에도 높임 표현은 쓰지 않아도 돼요.","mis":"K3-2-u4-X10"}],"mis":"K3-2-u4-X10","explanation":["웃어른께는 높임 표현을 사용해야 해요.","‘-시-’는 움직임을 하는 분을, ‘-습니다’는 듣는 분을 높여요.","이 설명은 색칠할 사과예요."],"asset":{"type":"passage","lines":["① 대화하는 상대가 웃어른일 때에는 ‘-시-’, ‘-습니다’와 같은 높임 표현을 사용한다.","② 언제 어디에서든 자신의 말이 잘 들릴 수 있도록 큰 소리로 대화한다.","③ ‘밥’, ‘생일’은 높임의 뜻이 있는 낱말이다.","④ 통화를 마칠 때에는 끝인사를 한다."],"title":"스스로 확인하기 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#2','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C2',1,'mc','auto','높임 표현에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X04','K3-2-u4-X02','K3-2-u4-X09']::text[],false,'{"seq":2,"concept":"K3-2-u4-C2","difficulty":1,"kind":"mc","stem":"높임 표현에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"대상을 높이는 표현으로, 존중과 공경의 마음이 담겨 있다","correct":true},{"t":"말을 길고 어렵게 하는 방법이다","mis":"K3-2-u4-X04"},{"t":"나이가 많은 사람에게만 쓰는 말이다","mis":"K3-2-u4-X02"},{"t":"물건을 소중히 여길 때 쓰는 말이다","mis":"K3-2-u4-X09"}],"explanation":["높임 표현은 누군가를 높이는 표현이에요.","그 안에 존중과 공경의 마음이 담겨 있어요.","나이만이 아니라 상황과 관계에 따라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#3','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C6',1,'mc','auto','할머니께 나이를 여쭐 때 ‘나이’ 대신 쓰는 높임의 뜻이 있는 낱말은 무엇인가요?',ARRAY['K3-2-u4-X07']::text[],false,'{"seq":3,"concept":"K3-2-u4-C6","difficulty":1,"kind":"mc","stem":"할머니께 나이를 여쭐 때 ‘나이’ 대신 쓰는 높임의 뜻이 있는 낱말은 무엇인가요?","options":[{"t":"연세","correct":true},{"t":"성함","mis":"K3-2-u4-X07"},{"t":"진지","mis":"K3-2-u4-X07"},{"t":"말씀","mis":"K3-2-u4-X07"}],"explanation":["‘성함’은 이름, ‘진지’는 밥, ‘말씀’은 말을 높인 낱말이에요.","‘나이’의 높임말은 ‘연세’예요.","“할머니, 연세가 어떻게 되세요?”처럼 여쭈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#4','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C5',1,'blank','auto','「할머니(     ) 오늘 우리 집에 오신대요.」 빈칸에 들어갈 알맞은 높임 표현은 무엇인가요?',ARRAY['K3-2-u4-X06']::text[],false,'{"seq":4,"concept":"K3-2-u4-C5","difficulty":1,"kind":"blank","stem":"「할머니(     ) 오늘 우리 집에 오신대요.」 빈칸에 들어갈 알맞은 높임 표현은 무엇인가요?","options":[{"t":"께서","correct":true},{"t":"가","mis":"K3-2-u4-X06"},{"t":"께","mis":"K3-2-u4-X06"},{"t":"에게","mis":"K3-2-u4-X06"}],"explanation":["오시는 분은 할머니예요.","‘이/가’ 자리에서 높일 때에는 ‘께서’를 써요.","‘오신대요’의 ‘-시-’와 함께 써서 할머니를 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#5','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C13',1,'mc','auto','「효진이와 소영이의 부탁」을 듣고 동호가 부탁을 들어준 사람은 누구인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X16']::text[],false,'{"seq":5,"concept":"K3-2-u4-C13","difficulty":1,"kind":"mc","stem":"「효진이와 소영이의 부탁」을 듣고 동호가 부탁을 들어준 사람은 누구인가요?","options":[{"t":"소영","correct":true},{"t":"효진","mis":"K3-2-u4-X18"},{"t":"효진이와 소영이 둘 다","mis":"K3-2-u4-X16"}],"explanation":["효진이에게는 “내가 왜? 나 바빠.”라고 했어요.","소영이에게는 “응, 알았어.”라고 했어요.","소영이는 배려하며 조심스럽게 부탁했어요."],"asset":{"type":"speech","turns":[{"who":"소영","text":"“동호야, 지금 바빠? 이 책 좀 같이 들어 줄 수 있어?”"},{"who":"동호","text":"“응, 알았어. 그런데 나 지금 선생님 심부름 가는 길인데, 저기 계단까지만 들어 줘도 될까?”"},{"who":"소영","text":"“물론이지. 도와줘서 고마워.”"},{"who":"효진","text":"“왜 내 건 안 들어 주고 소영이 것만 들어 줘?”"},{"who":"동호","text":"“나는 네가 나한테 짜증만 내고 명령하듯이 말해서 들어 주고 싶지 않았어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#6','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C16',1,'sa','auto','「주현이와 지환이의 대화」에서 대화 ㉯를 나눈 장소는 어디인가요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u4-C16","difficulty":1,"kind":"sa","stem":"「주현이와 지환이의 대화」에서 대화 ㉯를 나눈 장소는 어디인가요? 한 낱말로 쓰세요.","answer":["도서관","도서관에서"],"explanation":["지환이는 “여기는 도서관이잖아.”라고 했어요.","대화 ㉮는 운동장에서 나눈 대화예요.","장소가 달라지면 알맞은 목소리도 달라져요."],"asset":{"type":"speech","turns":[{"who":"㉮ 운동장 — 주현","text":"(큰 소리로) “지환아, 외투 가져가야지.”"},{"who":"지환","text":"(웃으며) “아, 맞다. 챙겨 줘서 고마워. 그런데 네 목소리 정말 크다. 멀리서도 잘 들려.”"},{"who":"㉯ 도서관 — 주현","text":"(크게 부르며) “지환아, 이 책 좀 봐.”"},{"who":"지환","text":"(찡그리며) “주현아, 목소리가 너무 커. 여기는 도서관이잖아.”"}]},"mis":"K3-2-u4-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#7','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C18',1,'mc','auto','전화로 대화할 때 지켜야 할 예절로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":7,"concept":"K3-2-u4-C18","difficulty":1,"kind":"mc","stem":"전화로 대화할 때 지켜야 할 예절로 알맞은 것은 무엇인가요?","options":[{"t":"자신이 누구인지 밝히고, 상대가 누구인지 확인한다","correct":true},{"t":"상대가 전화를 받을 때까지 계속해서 전화를 건다","mis":"K3-2-u4-X25"},{"t":"하고 싶은 말을 다 했으면 언제든 전화를 끊는다","mis":"K3-2-u4-X25"},{"t":"받자마자 내 할 말부터 한다","mis":"K3-2-u4-X25"}],"explanation":["전화는 상대의 얼굴을 볼 수 없어요.","먼저 자신을 밝히고 상대를 확인해요.","통화가 괜찮은지 묻고, 끝인사를 하고 끊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#8','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C25',1,'mc','auto','‘개구락지, 까구리, 깨구리’는 어떤 표준어의 방언인가요?',ARRAY['K3-2-u4-X31']::text[],false,'{"seq":8,"concept":"K3-2-u4-C25","difficulty":1,"kind":"mc","stem":"‘개구락지, 까구리, 깨구리’는 어떤 표준어의 방언인가요?","options":[{"t":"개구리","correct":true},{"t":"까마귀","mis":"K3-2-u4-X31"},{"t":"개미","mis":"K3-2-u4-X31"},{"t":"거북이","mis":"K3-2-u4-X31"}],"explanation":["세 낱말은 지역마다 다르게 부르는 같은 동물이에요.","연못에서 폴짝폴짝 뛰는 동물이에요.","표준어는 ‘개구리’예요."],"asset":{"type":"passage","lines":["방언: 가우, 가새, 가시개  →  표준어: (     )","방언: 개구락지, 까구리, 깨구리  →  표준어: (     )","방언이란 어느 한 지역에서만 쓰는, 표준어가 아닌 말을 뜻해요."],"title":"기초 다지기 2 — 『국어』 214쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#9','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C4',2,'mc','auto','대화 ㉠에서 민수의 말 “어머니, 오늘 할머니께서 우리 집에 오나요?”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X06','K3-2-u4-X11']::text[],false,'{"seq":9,"concept":"K3-2-u4-C4","difficulty":2,"kind":"mc","stem":"대화 ㉠에서 민수의 말 “어머니, 오늘 할머니께서 우리 집에 오나요?”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“어머니, 오늘 할머니께서 우리 집에 오시나요?”","correct":true},{"t":"“어머니, 오늘 할머니께서 우리 집에 오나?”","mis":"K3-2-u4-X10"},{"t":"“어머니께서, 오늘 할머니가 우리 집에 오나요?”","mis":"K3-2-u4-X06"},{"t":"“어머니, 오늘 할머니께서 우리 댁에 오나요?”","mis":"K3-2-u4-X11"}],"explanation":["오시는 분은 할머니예요.","‘께서’를 썼으니 ‘오나요’에도 ‘-시-’를 넣어 ‘오시나요’라고 해요.","‘우리 집’은 우리 가족의 집이라 ‘댁’으로 바꾸지 않아요."],"asset":{"type":"passage","lines":["㉠ 민수: 어머니, 오늘 할머니께서 우리 집에 오나요?","어머니: 맞아. 오늘 오실 거야.","㉡ 민수: 그럼 제가 데리러 갈게요.","어머니: 그래. 할머니께서 정말 좋아하시겠구나.","㉢ 민수: 그런데 할머니가 몇 시쯤 오세요?","어머니: 오후 세 시쯤 오실 거야.","㉣ 민수: 그럼 나갈 준비를 미리 할게.","어머니: 그렇게 하자."],"title":"높임 표현을 바르게 사용하기 — 대화 ㉠~㉣"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#10','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C8',2,'mc','auto','동영상 속 “……매진되셨어요.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X10']::text[],false,'{"seq":10,"concept":"K3-2-u4-C8","difficulty":2,"kind":"mc","stem":"동영상 속 “……매진되셨어요.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“……매진되었어요.”","correct":true},{"t":"“……매진되시었어요.”","mis":"K3-2-u4-X09"},{"t":"“……매진되셨습니다.”","mis":"K3-2-u4-X09"},{"t":"“……매진됐어.”","mis":"K3-2-u4-X10"}],"explanation":["매진된 것은 물건이에요.","물건에는 ‘-시-’를 넣지 않아요.","듣는 손님을 높이려고 ‘요’는 그대로 써요."],"asset":{"type":"passage","lines":["[동영상] 가게에서 물건과 음료를 높이는 말이 들린다 — 『국어』 186쪽","신발 가게 — “……제품이시고요.”","카페 — “……아메리카노 나오셨습니다.”","“……매진되셨어요.”","[그림] 커다란 신발이 놀라서 — “뭐? 내가 제품이시라고?”"],"title":"동영상 속 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#11','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C2',2,'mc','auto','범수가 엄마의 높임말을 계속 받기로 한 까닭은 무엇인가요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":11,"concept":"K3-2-u4-C2","difficulty":2,"kind":"mc","stem":"범수가 엄마의 높임말을 계속 받기로 한 까닭은 무엇인가요?","options":[{"t":"엄마가 꼬박꼬박 높임말을 해 주니 왕자가 된 것처럼 기분이 좋았기 때문","correct":true},{"t":"엄마의 높임말이 무서웠기 때문","mis":"K3-2-u4-X33"},{"t":"할머니께서 그렇게 하라고 시키셨기 때문","mis":"K3-2-u4-X33"},{"t":"엄마가 용돈을 주겠다고 했기 때문","mis":"K3-2-u4-X33"}],"explanation":["범수는 높임말을 듣고 “어? 기분이 나쁘지는 않은데?” 하고 생각했어요.","왕자가 된 것처럼 붕붕 뜬 느낌이었어요.","그래서 높임말을 계속 받기로 했어요."],"asset":{"type":"passage","lines":["(간추림) 범수가 반말을 고치지 않자 엄마는 할머니와 비밀 모의를 했다.","“아드님, 학교 다녀오시느라 힘드셨지요?”","“손자님! 가방은 제가 정리할게요.”","(간추림) 범수는 왕자가 된 것 같아 엄마의 높임말을 계속 받기로 했다."],"title":"「아드님, 진지 드세요」 비밀 모의 — 『국어』 189~190쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#12','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C15',2,'mc','auto','소영이가 동호에게 “도와줘서 고마워.”라고 한 말에서 지킨 대화 예절은 무엇인가요?',ARRAY['K3-2-u4-X39','K3-2-u4-X19']::text[],false,'{"seq":12,"concept":"K3-2-u4-C15","difficulty":2,"kind":"mc","stem":"소영이가 동호에게 “도와줘서 고마워.”라고 한 말에서 지킨 대화 예절은 무엇인가요?","options":[{"t":"부탁을 들어준 친구에게 고마운 마음을 표현한다","correct":true},{"t":"부탁하는 까닭과 내용을 자세하게 말한다","mis":"K3-2-u4-X39"},{"t":"거절할 때에는 미안한 마음을 표현한다","mis":"K3-2-u4-X19"},{"t":"친구가 들어줄 수 있는 상황인지 확인한다","mis":"K3-2-u4-X39"}],"explanation":["동호는 “그래, 알았어.” 하며 부탁을 들어주었어요.","소영이는 고마운 마음을 말로 표현했어요.","부탁을 들어준 뒤에는 고마움을 표현해요."],"asset":{"type":"speech","turns":[{"who":"동호","text":"“무슨 일이야?”"},{"who":"소영","text":"“도서관에서 책을 많이 빌렸더니 너무 무거워서 혼자 옮기기가 힘드네. 혹시 같이 좀 들어 줄 수 있어?”"},{"who":"동호","text":"“그래, 알았어.”"},{"who":"소영","text":"“도와줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#13','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C17',2,'mc','auto','2모둠은 귓속말에 대해 토의했어요. 친구가 귓속말하는 모습을 신경 쓸 때 할 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X24','K3-2-u4-X33']::text[],false,'{"seq":13,"concept":"K3-2-u4-C17","difficulty":2,"kind":"mc","stem":"2모둠은 귓속말에 대해 토의했어요. 친구가 귓속말하는 모습을 신경 쓸 때 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"친구가 오해하지 않도록 무슨 이야기였는지 설명해 준다","correct":true},{"t":"친구가 신경 쓰든 말든 계속 귓속말을 한다","mis":"K3-2-u4-X24"},{"t":"귓속말을 들킨 친구를 모르는 척한다","mis":"K3-2-u4-X24"},{"t":"그 친구와는 더 이상 놀지 않는다","mis":"K3-2-u4-X33"}],"explanation":["귓속말은 다른 친구에게 오해를 불러일으킬 수 있어요.","되도록 귓속말을 하지 않는 것이 좋아요.","친구가 신경 쓰면 오해하지 않게 설명해 줘요."],"asset":{"type":"speech","turns":[{"who":"태수","text":"“여기가 내 방이야. 무슨 놀이를 할까? 여기에서 골라 봐.”"},{"who":"인혜","text":"(귓속말로) “넌 뭐 하고 싶어?”"},{"who":"진성","text":"(귓속말로) “난 저거.”"},{"who":"태수","text":"“나만 빼고 너네끼리 무슨 얘기 해?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#14','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C21',2,'mc','auto','친구가 “남수야, 나 이번에 미술 대회에서 상 받았어!”라고 했어요. 축하하는 마음을 전하려는 남수의 응답으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X27']::text[],false,'{"seq":14,"concept":"K3-2-u4-C21","difficulty":2,"kind":"mc","stem":"친구가 “남수야, 나 이번에 미술 대회에서 상 받았어!”라고 했어요. 축하하는 마음을 전하려는 남수의 응답으로 알맞은 것은 무엇인가요?","options":[{"t":"(기뻐하는 말투로) “축하해.”","correct":true},{"t":"(짜증 나는 말투로) “축하해.”","mis":"K3-2-u4-X27"},{"t":"(울먹이는 말투로) “축하해.”","mis":"K3-2-u4-X27"}],"explanation":["세 응답 모두 “축하해.”라는 같은 말이에요.","짜증 나거나 울먹이는 말투로는 축하하는 마음이 전해지지 않아요.","기뻐하는 말투로 말해야 마음이 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#15','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C12',2,'mc','auto','「범수는 반말을 고치고 싶은 마음이 전혀 없었어요.」의 ‘고치다’와 뜻이 비슷한 관계인 낱말은 무엇인가요?',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":15,"concept":"K3-2-u4-C12","difficulty":2,"kind":"mc","stem":"「범수는 반말을 고치고 싶은 마음이 전혀 없었어요.」의 ‘고치다’와 뜻이 비슷한 관계인 낱말은 무엇인가요?","options":[{"t":"바로잡다","correct":true},{"t":"망가뜨리다","mis":"K3-2-u4-X15"},{"t":"그대로 두다","mis":"K3-2-u4-X15"},{"t":"배우다","mis":"K3-2-u4-X15"}],"explanation":["‘고치다’는 잘못된 것을 바르게 하는 거예요.","‘바로잡다’도 같은 뜻이라 서로 뜻이 비슷한 관계예요.","『국어』 195쪽 낱말 알기에 나온 낱말이에요."],"asset":{"type":"passage","lines":["범수는 식탁에서 벌떡 일어났어요.","범수는 반말을 고치고 싶은 마음이 전혀 없었어요.","“우리 범수가 이참에 단단히 배우겠구먼.”"],"title":"「아드님, 진지 드세요」 낱말 알기 — 『국어』 195쪽","hi":["식탁","고치고","배우겠구먼"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#16','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C24',2,'mc','auto','낱말 기억 놀이에서 가위바위보를 한 다음에는 누가 먼저 카드를 뒤집나요?',ARRAY['K3-2-u4-X07','K3-2-u4-X30']::text[],false,'{"seq":16,"concept":"K3-2-u4-C24","difficulty":2,"kind":"mc","stem":"낱말 기억 놀이에서 가위바위보를 한 다음에는 누가 먼저 카드를 뒤집나요?","options":[{"t":"가위바위보에서 이긴 사람이 색깔별로 한 장씩 뒤집는다","correct":true},{"t":"진 사람이 한 장만 뒤집는다","mis":"K3-2-u4-X07"},{"t":"두 사람이 동시에 모든 카드를 뒤집는다","mis":"K3-2-u4-X30"}],"explanation":["놀이 방법 ②, ③을 다시 읽어요.","이긴 사람이 먼저 카드를 색깔별로 한 장씩 뒤집어요.","뜻이 같으면 가져가고, 다르면 다시 뒤집어 놓아요."],"asset":{"type":"passage","lines":["① 카드를 뒤집어 색깔별로 가지런히 놓는다.","② 짝과 가위바위보를 한다.","③ 이긴 사람이 먼저 카드를 색깔별로 각각 한 장씩 뒤집는다.","④ 본래의 낱말과 높임의 뜻이 있는 낱말의 뜻이 같으면 카드를 가져가고,","뜻이 다르면 카드를 다시 뒤집어 놓는다.","⑤ 카드를 많이 가져간 사람이 이긴다."],"title":"높임의 뜻이 있는 낱말 기억 놀이 — 『국어』 210쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#17','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C4',3,'mc','auto','「할아버지께서는 귀가 참 밝으시다.」에서 ‘밝으시다’의 ‘-시-’로 높인 사람은 누구인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X11','K3-2-u4-X08']::text[],false,'{"seq":17,"concept":"K3-2-u4-C4","difficulty":3,"kind":"mc","stem":"「할아버지께서는 귀가 참 밝으시다.」에서 ‘밝으시다’의 ‘-시-’로 높인 사람은 누구인가요?","options":[{"t":"할아버지","correct":true},{"t":"귀","mis":"K3-2-u4-X09"},{"t":"말하는 나","mis":"K3-2-u4-X11"},{"t":"듣는 친구","mis":"K3-2-u4-X08"}],"explanation":["귀는 높임의 대상이 아니지만 할아버지의 몸이에요.","할아버지의 귀를 높여 말해서 할아버지를 높였어요.","물건 자체를 높이는 “커피 나오셨습니다.”와는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#18','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C9',3,'error','auto','세 친구가 지운이의 쪽지를 고쳤어요. 잘못 고친 친구는 누구인가요?',ARRAY['K3-2-u4-X35','K3-2-u4-X07','K3-2-u4-X09']::text[],false,'{"seq":18,"concept":"K3-2-u4-C9","difficulty":3,"kind":"error","stem":"세 친구가 지운이의 쪽지를 고쳤어요. 잘못 고친 친구는 누구인가요?","options":[{"t":"은재: ‘안녕히 계세요’를 ‘안녕히 있으세요’로 고쳤어.","correct":true,"mis_target":"K3-2-u4-X35"},{"t":"태윤: ‘집’을 ‘댁’으로 고쳤어.","mis":"K3-2-u4-X07"},{"t":"하린: ‘떡이세요’를 ‘떡이에요’로 고쳤어.","mis":"K3-2-u4-X09"}],"explanation":["‘계세요’는 ‘있다’의 높임말 ‘계시다’를 바르게 쓴 말이에요.","‘있으세요’로 바꾸면 오히려 어색해져요.","‘집 → 댁’, ‘떡이세요 → 떡이에요’는 바르게 고쳤어요."],"asset":{"type":"passage","lines":["할머니, 할아버지께","안녕하세요?","저는 옆집에 이사 온 김지운입니다.","직접 인사하고 싶었지만 집에 안 계셔서 이렇게 쪽지를 남겨요.","이건 저희 부모님께서 할머니, 할아버지께 드리는 떡이세요.","맛있게 잡수시면 좋겠어요.","안녕히 계세요.","김지운 올림"],"title":"지운이가 쓴 쪽지 — 『국어』 187쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#19','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C20',3,'mc','auto','할머니께 전화로 안부를 여쭈려고 대화 계획을 세워요. 계획을 바르게 세운 것은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X21']::text[],false,'{"seq":19,"concept":"K3-2-u4-C20","difficulty":3,"kind":"mc","stem":"할머니께 전화로 안부를 여쭈려고 대화 계획을 세워요. 계획을 바르게 세운 것은 무엇인가요?","options":[{"t":"나누는 사람 — 할머니 · 대화 방식 — 전화 대화 · 대화 목적 — 안부 여쭈기","correct":true},{"t":"나누는 사람 — 전화 · 대화 방식 — 할머니 · 대화 목적 — 안부 여쭈기","mis":"K3-2-u4-X22"},{"t":"나누는 사람 — 할머니 · 대화 방식 — 안부 여쭈기 · 대화 목적 — 전화 대화","mis":"K3-2-u4-X22"},{"t":"나누는 사람 — 할머니 · 대화 방식 — 큰 목소리 · 대화 목적 — 빨리 끊기","mis":"K3-2-u4-X21"}],"explanation":["대화를 나누는 사람은 대화 상대예요.","대화 방식은 어떻게(전화로) 대화하는지예요.","대화 목적은 무엇을 하려고(안부 여쭈기) 대화하는지예요."],"asset":{"type":"passage","lines":["1. 대화 계획 — 대화를 나누는 사람 · 대화 방식 · 대화 목적 · 대화 주제","2. 계획을 바탕으로 대화 예절을 지키며 대화하기","3. 스스로 확인하기","· 대화하는 상대에 따라 알맞은 높임 표현과 태도로 대화했나요?","· 대화 목적에 알맞은 대화 예절을 지키며 대화했나요?","· 상황에 어울리는 표정, 몸짓, 말투로 대화했나요?"],"title":"대화 예절을 지키며 대화하기 — 평가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#20','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C3',3,'mc','auto','다음 가운데 친구 사이라도 높임 표현을 쓰는 것이 알맞은 상황은 무엇인가요?',ARRAY['K3-2-u4-X03','K3-2-u4-X11']::text[],false,'{"seq":20,"concept":"K3-2-u4-C3","difficulty":3,"kind":"mc","stem":"다음 가운데 친구 사이라도 높임 표현을 쓰는 것이 알맞은 상황은 무엇인가요?","options":[{"t":"학급 회의에서 사회자가 친구에게 의견을 말해 달라고 할 때","correct":true},{"t":"쉬는 시간에 짝과 놀이를 정할 때","mis":"K3-2-u4-X03"},{"t":"운동장에서 친구에게 공을 달라고 할 때","mis":"K3-2-u4-X03"},{"t":"집에서 동생과 숙제를 할 때","mis":"K3-2-u4-X11"}],"explanation":["학급 회의는 공식적인 상황이에요.","공식적인 상황에서는 친구에게도 높임 표현을 써요.","쉬는 시간처럼 편한 상황에서는 친구끼리 반말을 해도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#21','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C13',3,'mc','auto','동영상 「우리의 상황을 헤아려 주는 참 좋은 말」에서 말하는 ‘참 좋은 말’은 무엇인가요?',ARRAY['K3-2-u4-X37','K3-2-u4-X04','K3-2-u4-X21']::text[],false,'{"seq":21,"concept":"K3-2-u4-C13","difficulty":3,"kind":"mc","stem":"동영상 「우리의 상황을 헤아려 주는 참 좋은 말」에서 말하는 ‘참 좋은 말’은 무엇인가요?","options":[{"t":"상대의 상황이나 처지를 헤아리고 배려하는 말","correct":true},{"t":"듣기 좋게 꾸민 칭찬하는 말","mis":"K3-2-u4-X37"},{"t":"어려운 낱말을 많이 쓴 말","mis":"K3-2-u4-X04"},{"t":"큰 목소리로 또렷하게 하는 말","mis":"K3-2-u4-X21"}],"explanation":["‘참 좋은 말’은 듣기 좋은 말이 아니에요.","상대의 처지를 헤아려 주는 말이에요.","대화 예절은 결국 상대의 기분을 헤아리는 태도에서 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#22','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C2',3,'mc','auto','『국어』 196쪽 장면 ㉯의 엄마 말 “아드님은 뭐가 드시고 싶으세요?”에 쓰인 높임 표현 방법을 바르게 모두 고른 것은 무엇인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X08','K3-2-u4-X34']::text[],false,'{"seq":22,"concept":"K3-2-u4-C2","difficulty":3,"kind":"mc","stem":"『국어』 196쪽 장면 ㉯의 엄마 말 “아드님은 뭐가 드시고 싶으세요?”에 쓰인 높임 표현 방법을 바르게 모두 고른 것은 무엇인가요?","options":[{"t":"높임의 뜻이 있는 낱말(아드님·드시다) · ‘-시-’ · ‘요’","correct":true},{"t":"‘께서’ · ‘께’ · ‘-습니다’","mis":"K3-2-u4-X06"},{"t":"‘요’만","mis":"K3-2-u4-X08"},{"t":"높임의 뜻이 있는 낱말만","mis":"K3-2-u4-X34"}],"explanation":["‘아드님’, ‘드시다’는 높임의 뜻이 있는 낱말이에요.","‘싶으세요’에 ‘-시-’와 ‘요’가 들어 있어요.","한 문장에 여러 가지 높임 방법이 함께 쓰였어요."],"asset":{"type":"passage","lines":["“오늘 저녁 반찬은 뭐야?”","“아드님은 뭐가 드시고 싶으세요?”","“떡갈비.”"],"title":"「아드님, 진지 드세요」 장면 ㉯ — 『국어』 196쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#23','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C9',4,'essay','teacher','대화 ㉠~㉣에서 높임 표현이 바르지 않은 부분을 각각 한 가지씩 찾아 알맞은 높임 표현으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u4-C9","difficulty":4,"kind":"essay","stem":"대화 ㉠~㉣에서 높임 표현이 바르지 않은 부분을 각각 한 가지씩 찾아 알맞은 높임 표현으로 고쳐 쓰세요.","answer_guide":{"answer":"㉠ 오나요 → 오시나요 · ㉡ 데리러 → 모시러 · ㉢ 할머니가 → 할머니께서 · ㉣ 할게 → 할게요","scoring_points":["네 대화에서 바르지 않은 부분을 하나씩 찾았는가","‘-시-’·높임의 뜻이 있는 낱말·‘께서’·‘요’를 알맞게 써서 고쳤는가","높임의 대상(할머니·어머니)을 바르게 판단했는가"]},"explanation":["높임의 대상이 누구인지 먼저 찾아요.","말 속의 할머니와 말을 듣는 어머니를 각각 높여요.","알맞은 높임 방법을 골라 고쳐요."],"asset":{"type":"passage","lines":["㉠ 민수: 어머니, 오늘 할머니께서 우리 집에 오나요?","어머니: 맞아. 오늘 오실 거야.","㉡ 민수: 그럼 제가 데리러 갈게요.","어머니: 그래. 할머니께서 정말 좋아하시겠구나.","㉢ 민수: 그런데 할머니가 몇 시쯤 오세요?","어머니: 오후 세 시쯤 오실 거야.","㉣ 민수: 그럼 나갈 준비를 미리 할게.","어머니: 그렇게 하자."],"title":"높임 표현을 바르게 사용하기 — 대화 ㉠~㉣"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#24','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C20',4,'essay','teacher','대화 예절을 지키며 대화를 나누기 위한 계획을 세우세요. 대화를 나누는 사람·대화 방식·대화 목적·대화 주제를 정하고, 지킬 대화 예절을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u4-C20","difficulty":4,"kind":"essay","stem":"대화 예절을 지키며 대화를 나누기 위한 계획을 세우세요. 대화를 나누는 사람·대화 방식·대화 목적·대화 주제를 정하고, 지킬 대화 예절을 두 가지 쓰세요.","answer_guide":{"answer":"예: 나누는 사람 — 담임 선생님 · 방식 — 직접 만나서 · 목적 — 모르는 문제 여쭈어보기 · 주제 — 수학 숙제. 지킬 예절 — ① 선생님께서 바쁘지 않으신지 먼저 여쭌다. ② 높임 표현을 쓰고 선생님을 바라보며 공손한 태도로 말한다.","scoring_points":["대화를 나누는 사람·방식·목적·주제를 모두 정했는가","상황에 알맞은 대화 예절을 두 가지 썼는가","높임 표현이나 태도처럼 상황에 맞는 예절이 드러났는가"]},"explanation":["누구와, 어떻게, 무엇을 하려고, 무엇에 대해 대화할지 정해요.","상대·방식·목적에 따라 지킬 예절이 달라져요.","계획을 바탕으로 실제로 대화해 보아요."],"asset":{"type":"passage","lines":["1. 대화 계획 — 대화를 나누는 사람 · 대화 방식 · 대화 목적 · 대화 주제","2. 계획을 바탕으로 대화 예절을 지키며 대화하기","3. 스스로 확인하기","· 대화하는 상대에 따라 알맞은 높임 표현과 태도로 대화했나요?","· 대화 목적에 알맞은 대화 예절을 지키며 대화했나요?","· 상황에 어울리는 표정, 몸짓, 말투로 대화했나요?"],"title":"대화 예절을 지키며 대화하기 — 평가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_a#25','kor',3,2,'u4','','tb_g3_2_kor_u4_review_a','unit_review','K3-2-u4-C23',4,'essay','teacher','『국어』 213쪽 생활 속으로처럼, 이 단원에서 배운 내용을 생활 속에서 어떻게 실천할지 다짐을 쓰세요. 어떤 상황에서 어떤 내용을 실천할지 구체적으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u4-C23","difficulty":4,"kind":"essay","stem":"『국어』 213쪽 생활 속으로처럼, 이 단원에서 배운 내용을 생활 속에서 어떻게 실천할지 다짐을 쓰세요. 어떤 상황에서 어떤 내용을 실천할지 구체적으로 쓰세요.","answer_guide":{"answer":"예: 할머니와 통화할 때 “할머니, 지금 통화 괜찮으세요?” 하고 먼저 여쭈고, 높임 표현을 바르게 사용하겠습니다.","scoring_points":["어떤 상황에서 실천할지 썼는가","높임 표현이나 대화 예절 가운데 실천할 내용을 썼는가","실천했는지 알 수 있을 만큼 구체적으로 썼는가"]},"explanation":["정한솔, 최연재, 김민수의 다짐을 떠올려요.","언제, 누구와, 무엇을 할지 드러나게 써요.","다짐은 한 가지라도 꼭 지킬 수 있게 써요."],"asset":{"type":"passage","lines":["정한솔 — 부모님이나 선생님과 대화할 때 높임 표현을 바르게 사용하겠습니다.","최연재 — 친구들과 대화할 때 상황에 맞는 대화 예절을 지키도록 노력하겠습니다.","김민수 — 부탁을 들어준 친구에게 고마운 마음을 표현하겠습니다."],"title":"생활 속으로 — 우리 모두 대화 예절을 실천할 것을 다짐해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#1','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C16',1,'ox','auto','스스로 확인하기 ②예요. 「언제 어디에서든 자신의 말이 잘 들릴 수 있도록 큰 소리로 대화한다.」는 알맞은 설명이에요.',ARRAY['K3-2-u4-X21']::text[],false,'{"seq":1,"concept":"K3-2-u4-C16","difficulty":1,"kind":"ox","stem":"스스로 확인하기 ②예요. 「언제 어디에서든 자신의 말이 잘 들릴 수 있도록 큰 소리로 대화한다.」는 알맞은 설명이에요.","answer":"X","reason_options":[{"t":"도서관 같은 공공장소에서는 조용히 말하는 것처럼 장소에 맞는 목소리로 말해요.","correct":true},{"t":"어디에서든 크게 말할수록 예절 바른 거예요.","mis":"K3-2-u4-X21"}],"mis":"K3-2-u4-X21","explanation":["운동장에서는 큰 목소리가 반가울 수 있어요.","하지만 도서관에서는 다른 사람에게 방해가 돼요.","장소에 따라 알맞은 목소리 크기가 달라요."],"asset":{"type":"passage","lines":["① 대화하는 상대가 웃어른일 때에는 ‘-시-’, ‘-습니다’와 같은 높임 표현을 사용한다.","② 언제 어디에서든 자신의 말이 잘 들릴 수 있도록 큰 소리로 대화한다.","③ ‘밥’, ‘생일’은 높임의 뜻이 있는 낱말이다.","④ 통화를 마칠 때에는 끝인사를 한다."],"title":"스스로 확인하기 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#2','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C3',1,'blank','auto','『국어』 183쪽 정리 글의 ㉠이에요. 「먼저, (     )께는 높임 표현을 사용해야 합니다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u4-X03','K3-2-u4-X11','K3-2-u4-X09']::text[],false,'{"seq":2,"concept":"K3-2-u4-C3","difficulty":1,"kind":"blank","stem":"『국어』 183쪽 정리 글의 ㉠이에요. 「먼저, (     )께는 높임 표현을 사용해야 합니다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"웃어른","correct":true},{"t":"친구","mis":"K3-2-u4-X03"},{"t":"동생","mis":"K3-2-u4-X11"},{"t":"물건","mis":"K3-2-u4-X09"}],"explanation":["나이나 지위가 자기보다 높은 어른을 웃어른이라고 해요.","웃어른께는 높임 표현을 써야 해요.","그 밖에 공식적인 상황, 처음 만난 사이에서도 써요."],"asset":{"type":"passage","lines":["높임 표현은 여러 가지 상황에서 사용할 수 있습니다.","먼저, (  ㉠  )께는 높임 표현을 사용해야 합니다.","평소에는 반말을 하는 친구 사이일지라도 회의나 발표와 같은","(  ㉡  ) 상황에서는 높임 표현을 사용해야 합니다.","처음 만난 사이처럼 가깝지 않은 사이에서는 주로 높임 표현을 사용합니다.","상대와의 관계에 따라 (  ㉢  )을 표현하기 위해","나이와 관계없이 높임 표현을 사용하기도 합니다.","보기: 비공식적 · 공식적 · 존중 · 웃어른"],"title":"「높임 표현을 사용하는 상황」 — 『국어』 183쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#3','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C6',1,'sa','auto','지운이의 쪽지 「직접 인사하고 싶었지만 집에 안 계셔서」에서 ‘계셔서’의 본래 낱말(높이지 않은 말)을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u4-C6","difficulty":1,"kind":"sa","stem":"지운이의 쪽지 「직접 인사하고 싶었지만 집에 안 계셔서」에서 ‘계셔서’의 본래 낱말(높이지 않은 말)을 쓰세요.","answer":["있다","있어서"],"explanation":["‘계시다’는 ‘있다’를 높인 낱말이에요.","할머니, 할아버지께서 집에 있지 않으셨다는 뜻이에요.","‘있으시다’보다 ‘계시다’를 써요."],"asset":{"type":"passage","lines":["할머니, 할아버지께","안녕하세요?","저는 옆집에 이사 온 김지운입니다.","직접 인사하고 싶었지만 집에 안 계셔서 이렇게 쪽지를 남겨요.","이건 저희 부모님께서 할머니, 할아버지께 드리는 떡이세요.","맛있게 잡수시면 좋겠어요.","안녕히 계세요.","김지운 올림"],"title":"지운이가 쓴 쪽지 — 『국어』 187쪽"},"mis":"K3-2-u4-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#4','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C5',1,'blank','auto','스승의 날 일기 「작년 담임 선생님(     ) 편지를 썼다.」의 빈칸에 들어갈 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X06']::text[],false,'{"seq":4,"concept":"K3-2-u4-C5","difficulty":1,"kind":"blank","stem":"스승의 날 일기 「작년 담임 선생님(     ) 편지를 썼다.」의 빈칸에 들어갈 알맞은 말은 무엇인가요?","options":[{"t":"께","correct":true},{"t":"께서","mis":"K3-2-u4-X06"},{"t":"에게","mis":"K3-2-u4-X06"}],"explanation":["편지를 받는 분이 작년 담임 선생님이에요.","‘에게’ 자리에서 높일 때는 ‘께’를 써요.","‘께서’는 ‘이/가’ 자리에서 써요."],"asset":{"type":"passage","lines":["5월 15일 ○요일 날씨: 맑음","오늘은 스승의 날을 맞이해 작년 담임 선생님께 편지를 썼다.","편지를 다 쓰고 선생님께서 작년 담임 선생님께 편지를 주고 오라고 했다.","나랑 현승이는 작년에 같은 반이었기 때문에","함께 작년 담임 선생님에게 편지를 주고 왔다.","선생님이 기뻐하는 모습을 보니 뿌듯한 마음이 들었다."],"title":"어느 날의 일기 — 높임 표현을 살펴보아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#5','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C13',1,'ox','auto','대화 예절의 기본은 대화할 때 상대의 기분을 헤아리고 배려하는 태도예요.',ARRAY['K3-2-u4-X18']::text[],false,'{"seq":5,"concept":"K3-2-u4-C13","difficulty":1,"kind":"ox","stem":"대화 예절의 기본은 대화할 때 상대의 기분을 헤아리고 배려하는 태도예요.","answer":"O","reason_options":[{"t":"대화 예절은 상대의 기분을 헤아리고 배려하는 태도에서 출발해요.","correct":true},{"t":"대화 예절은 정해진 말을 외워서 말하면 그만이에요.","mis":"K3-2-u4-X18"}],"mis":"K3-2-u4-X18","explanation":["대화 예절의 첫출발은 존중과 배려예요.","같은 말도 상대의 기분을 헤아리면 다르게 하게 돼요.","그래서 말투, 표정, 듣는 자세도 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#6','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C16',1,'blank','auto','「대화 상황은 대화하는 상대, 시간이나 장소, 대화의 목적이나 (     )에 따라 다양해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X21','K3-2-u4-X18']::text[],false,'{"seq":6,"concept":"K3-2-u4-C16","difficulty":1,"kind":"blank","stem":"「대화 상황은 대화하는 상대, 시간이나 장소, 대화의 목적이나 (     )에 따라 다양해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"방식","correct":true},{"t":"길이","mis":"K3-2-u4-X22"},{"t":"소리","mis":"K3-2-u4-X21"},{"t":"물건","mis":"K3-2-u4-X18"}],"explanation":["대화 방식은 어떻게 대화하는지예요.","직접 만나서 하는 대화, 전화 대화처럼 방식이 다양해요.","방식이 달라지면 지켜야 할 예절도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#7','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C18',1,'blank','auto','『국어』 214쪽 기초 다지기 1에서 「공공장소에서는 (     ) 목소리로 통화한다.」의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X27']::text[],false,'{"seq":7,"concept":"K3-2-u4-C18","difficulty":1,"kind":"blank","stem":"『국어』 214쪽 기초 다지기 1에서 「공공장소에서는 (     ) 목소리로 통화한다.」의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"작은","correct":true},{"t":"큰","mis":"K3-2-u4-X21"},{"t":"화난","mis":"K3-2-u4-X27"}],"explanation":["공공장소에는 다른 사람들이 함께 있어요.","큰 목소리로 통화하면 다른 사람에게 방해가 돼요.","그래서 작은 목소리로 통화해요."],"asset":{"type":"passage","lines":["① 자신이 누구인지 밝히고 상대를 확인한다.","② 전화를 끊고 싶으면 언제든지 바로 전화를 끊는다.","③ 상대가 전화를 받으면 자신이 하고 싶은 말부터 먼저 한다.","④ 공공장소에서는 작은 목소리로 통화한다.","⑤ 상대가 말할 때에는 귀 기울여 듣는다.","⑥ 상대의 상황을 생각하여 대화한다."],"title":"기초 다지기 1 — 『국어』 214쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#8','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C26',1,'mc','auto','『국어』 215쪽 글씨 쓰기 ‘혜택’의 첫 글자에 쓰인 모음자는 무엇인가요?',ARRAY['K3-2-u4-X32']::text[],false,'{"seq":8,"concept":"K3-2-u4-C26","difficulty":1,"kind":"mc","stem":"『국어』 215쪽 글씨 쓰기 ‘혜택’의 첫 글자에 쓰인 모음자는 무엇인가요?","options":[{"t":"ㅖ","correct":true},{"t":"ㅔ","mis":"K3-2-u4-X32"},{"t":"ㅒ","mis":"K3-2-u4-X32"},{"t":"ㅐ","mis":"K3-2-u4-X32"}],"explanation":["‘혜’는 ㅎ과 ㅖ가 만난 글자예요.","ㅖ는 ㅔ에 짧은 획이 하나 더 있어요.","‘예절’, ‘기계’에도 ㅖ가 쓰였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#9','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C6',2,'mc','auto','대화 ㉡에서 민수의 말 “그럼 제가 데리러 갈게요.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X35','K3-2-u4-X40','K3-2-u4-X10']::text[],false,'{"seq":9,"concept":"K3-2-u4-C6","difficulty":2,"kind":"mc","stem":"대화 ㉡에서 민수의 말 “그럼 제가 데리러 갈게요.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“그럼 제가 모시러 갈게요.”","correct":true},{"t":"“그럼 제가 데리시러 갈게요.”","mis":"K3-2-u4-X35"},{"t":"“그럼 제가 데리러 가실게요.”","mis":"K3-2-u4-X40"},{"t":"“그럼 제가 데리러 갈게.”","mis":"K3-2-u4-X10"}],"explanation":["할머니를 데리러 가는 상황이에요.","웃어른을 데리러 갈 때는 높임의 뜻이 있는 ‘모시다’를 써요.","내가 하는 일이라 ‘가실게요’라고 하지 않아요."],"asset":{"type":"passage","lines":["㉠ 민수: 어머니, 오늘 할머니께서 우리 집에 오나요?","어머니: 맞아. 오늘 오실 거야.","㉡ 민수: 그럼 제가 데리러 갈게요.","어머니: 그래. 할머니께서 정말 좋아하시겠구나.","㉢ 민수: 그런데 할머니가 몇 시쯤 오세요?","어머니: 오후 세 시쯤 오실 거야.","㉣ 민수: 그럼 나갈 준비를 미리 할게.","어머니: 그렇게 하자."],"title":"높임 표현을 바르게 사용하기 — 대화 ㉠~㉣"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#10','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C8',2,'mc','auto','손님에게 자리를 안내할 때 “손님, 이쪽으로 오실게요.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X40','K3-2-u4-X10']::text[],false,'{"seq":10,"concept":"K3-2-u4-C8","difficulty":2,"kind":"mc","stem":"손님에게 자리를 안내할 때 “손님, 이쪽으로 오실게요.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“손님, 이쪽으로 오세요.”","correct":true},{"t":"“손님, 이쪽으로 와 주실게요.”","mis":"K3-2-u4-X40"},{"t":"“손님, 이쪽으로 와.”","mis":"K3-2-u4-X10"},{"t":"“손님께서, 이쪽으로 오실게요.”","mis":"K3-2-u4-X40"}],"explanation":["‘-ㄹ게요’는 내가 하겠다고 약속하는 말이에요.","손님에게 오라고 권하는 말이니 ‘오세요’라고 해요.","‘오실게요’는 자주 듣지만 잘못된 높임 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#11','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C2',2,'mc','auto','엄마가 범수에게 높임말을 쓰면 쓸수록, 범수가 엄마에게 반말을 하면 할수록 범수의 기분이 엉망이 되어 간 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X33','K3-2-u4-X04']::text[],false,'{"seq":11,"concept":"K3-2-u4-C2","difficulty":2,"kind":"mc","stem":"엄마가 범수에게 높임말을 쓰면 쓸수록, 범수가 엄마에게 반말을 하면 할수록 범수의 기분이 엉망이 되어 간 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"엄마는 높임말을 하는데 자신은 반말을 하는 모습을 사람들이 이상하게 보아 창피하고 불편했기 때문","correct":true},{"t":"엄마가 높임말을 틀리게 했기 때문","mis":"K3-2-u4-X33"},{"t":"범수가 높임말을 너무 많이 들어 지겨웠기 때문","mis":"K3-2-u4-X04"},{"t":"범수가 떡볶이를 싫어하게 되었기 때문","mis":"K3-2-u4-X33"}],"explanation":["마트의 할머니가 범수와 엄마를 보고 혀를 찼어요.","범수는 군것질할 마음도, 떡볶이를 먹을 즐거움도 사라졌어요.","바르지 않은 말이 얼마나 불편한지 느끼게 되었어요."],"asset":{"type":"passage","lines":["(간추림) ① 아침 — 범수는 엄마에게 짜증을 내며 반말을 했다.","(간추림) ② 학교에서 돌아오니 엄마와 할머니가 높임말을 썼다.","(간추림) ③ 마트 — 모르는 할머니가 범수의 반말을 꾸짖었다.","(간추림) ④ 집 — 좋아하는 떡볶이도 맛이 없었다.","(간추림) ⑤ 태권도장 — 아이들이 놀리자 범수는 뛰쳐나왔다.","(간추림) ⑥ 집 — 범수는 울며 높임말을 잘 쓰겠다고 약속했다."],"title":"「아드님, 진지 드세요」 간추린 흐름 — 『국어』 188~194쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#12','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C15',2,'mc','auto','웃어른의 부탁을 들어드릴 수 없을 때 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K3-2-u4-X20','K3-2-u4-X19']::text[],false,'{"seq":12,"concept":"K3-2-u4-C15","difficulty":2,"kind":"mc","stem":"웃어른의 부탁을 들어드릴 수 없을 때 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"“죄송해요. 지금 친구와 약속한 시간이라 나가 봐야 해요. 다음에는 꼭 도와드릴게요.”","correct":true},{"t":"“네, 할게요.” (하고는 몰래 나간다)","mis":"K3-2-u4-X20"},{"t":"“싫어요.”","mis":"K3-2-u4-X19"},{"t":"(아무 대답 없이 방으로 들어간다)","mis":"K3-2-u4-X19"}],"explanation":["웃어른께는 높임 표현과 공손한 태도로 말해요.","죄송한 마음과 도와드릴 수 없는 까닭을 함께 말씀드려요.","거짓으로 하겠다고 대답하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#13','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C17',2,'mc','auto','1모둠은 「태수와 할아버지의 대화」로 토의했어요. 토의해서 정한 대화 예절로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X23','K3-2-u4-X17']::text[],false,'{"seq":13,"concept":"K3-2-u4-C17","difficulty":2,"kind":"mc","stem":"1모둠은 「태수와 할아버지의 대화」로 토의했어요. 토의해서 정한 대화 예절로 알맞은 것은 무엇인가요?","options":[{"t":"웃어른과 대화할 때에는 높임 표현을 쓰면서 공손한 태도와 말투로 말해야 한다","correct":true},{"t":"웃어른과 대화할 때에는 말끝에 ‘요’만 붙이면 된다","mis":"K3-2-u4-X23"},{"t":"웃어른과 대화할 때에는 하던 일을 계속하며 대답해도 된다","mis":"K3-2-u4-X23"},{"t":"웃어른이 물으시면 대답하지 않는 것이 공손하다","mis":"K3-2-u4-X17"}],"explanation":["태수는 ‘요’를 붙였지만 누운 채 성의 없이 대답했어요.","웃어른께는 하던 일을 멈추고 바라보며 말씀드려요.","높임 표현과 공손한 태도, 말투가 함께 필요해요."],"asset":{"type":"speech","turns":[{"who":"할아버지","text":"“태수야, 가위가 어디 있니?”"},{"who":"태수","text":"(소파에 누운 채 성의 없는 말투로) “서랍장에요.”"},{"who":"할아버지","text":"“태수야, 할아버지와 대화할 때에는 공손하게 말해야지.”"},{"who":"태수","text":"“아, 죄송해요. 저기 서랍장 안에 있어요. 가져다드릴까요?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#14','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C21',2,'mc','auto','대화할 때 경청하고 있다는 것을 표현하는 몸짓으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X27']::text[],false,'{"seq":14,"concept":"K3-2-u4-C21","difficulty":2,"kind":"mc","stem":"대화할 때 경청하고 있다는 것을 표현하는 몸짓으로 알맞은 것은 무엇인가요?","options":[{"t":"상대를 바라보고, 상대의 말을 들을 때 고개를 끄덕인다","correct":true},{"t":"다른 곳을 보며 휴대 전화를 만진다","mis":"K3-2-u4-X27"},{"t":"팔짱을 끼고 하품을 한다","mis":"K3-2-u4-X27"},{"t":"상대의 말이 끝나기 전에 고개를 돌린다","mis":"K3-2-u4-X27"}],"explanation":["표정과 몸짓으로도 대화 예절을 나타낼 수 있어요.","상대를 바라보고 고개를 끄덕이면 잘 듣고 있다는 뜻이 전해져요.","듣는 자세에도 존중하는 마음이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#15','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C12',2,'mc','auto','서로 뜻이 반대인 관계의 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":15,"concept":"K3-2-u4-C12","difficulty":2,"kind":"mc","stem":"서로 뜻이 반대인 관계의 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"묻다 — 대답하다","correct":true},{"t":"식탁 — 가구","mis":"K3-2-u4-X15"},{"t":"돕다 — 거들다","mis":"K3-2-u4-X15"},{"t":"고치다 — 바로잡다","mis":"K3-2-u4-X15"}],"explanation":["묻는 것과 대답하는 것은 반대예요.","식탁-가구는 포함 관계예요.","돕다-거들다, 고치다-바로잡다는 비슷한 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#16','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C23',2,'mc','auto','생활 속으로에서 정한솔의 다짐은 무엇과 관련된 것인가요?',ARRAY['K3-2-u4-X29']::text[],false,'{"seq":16,"concept":"K3-2-u4-C23","difficulty":2,"kind":"mc","stem":"생활 속으로에서 정한솔의 다짐은 무엇과 관련된 것인가요?","options":[{"t":"부모님이나 선생님과 대화할 때 높임 표현을 바르게 사용하는 것","correct":true},{"t":"친구들과 대화할 때 상황에 맞는 대화 예절을 지키는 것","mis":"K3-2-u4-X29"},{"t":"부탁을 들어준 친구에게 고마운 마음을 표현하는 것","mis":"K3-2-u4-X29"},{"t":"전화를 걸 때 자신이 누구인지 밝히는 것","mis":"K3-2-u4-X29"}],"explanation":["정한솔은 “부모님이나 선생님과 대화할 때 높임 표현을 바르게 사용하겠습니다.”라고 했어요.","최연재는 상황에 맞는 대화 예절, 김민수는 고마움 표현을 다짐했어요.","어떤 예절을 고를지는 사람마다 달라요."],"asset":{"type":"passage","lines":["정한솔 — 부모님이나 선생님과 대화할 때 높임 표현을 바르게 사용하겠습니다.","최연재 — 친구들과 대화할 때 상황에 맞는 대화 예절을 지키도록 노력하겠습니다.","김민수 — 부탁을 들어준 친구에게 고마운 마음을 표현하겠습니다."],"title":"생활 속으로 — 우리 모두 대화 예절을 실천할 것을 다짐해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#17','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C7',3,'mc','auto','「할아버지, 그동안 잘 지내셨어요?」에서 말끝의 ‘요’로 높인 사람은 누구인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X09','K3-2-u4-X10']::text[],false,'{"seq":17,"concept":"K3-2-u4-C7","difficulty":3,"kind":"mc","stem":"「할아버지, 그동안 잘 지내셨어요?」에서 말끝의 ‘요’로 높인 사람은 누구인가요?","options":[{"t":"말을 듣는 할아버지","correct":true},{"t":"말하는 손자","mis":"K3-2-u4-X11"},{"t":"그동안","mis":"K3-2-u4-X09"},{"t":"아무도 높이지 않았다","mis":"K3-2-u4-X10"}],"explanation":["이 말을 듣는 사람은 할아버지예요.","말끝의 ‘요’는 듣는 사람을 높여요.","‘지내셨어요’의 ‘-시-’도 지내신 할아버지를 높였어요."],"asset":{"type":"passage","lines":["① 높임을 나타내는 ‘-습니다’나 ‘요’를 사용한다.","② 높임을 나타내는 ‘-시-’를 사용한다.","③ 높임을 나타내는 ‘께서’나 ‘께’를 사용한다.","④ 높임의 뜻이 있는 낱말을 사용한다.","[그림 1] 손자가 할아버지께 달려가며 — “할아버지, 그동안 잘 지내셨어요?”","[그림 2] 공부하던 친구가 짝에게 — “이 내용은 선생님께 여쭈어보자.”"],"title":"『국어활동』 58쪽 실력 키우기 1"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#18','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C9',3,'error','auto','세 친구가 「아드님, 진지 드세요」 장면 ㉯ 범수의 말을 고쳤어요. 잘못 고친 친구는 누구인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X08']::text[],false,'{"seq":18,"concept":"K3-2-u4-C9","difficulty":3,"kind":"error","stem":"세 친구가 「아드님, 진지 드세요」 장면 ㉯ 범수의 말을 고쳤어요. 잘못 고친 친구는 누구인가요?","options":[{"t":"수아: “오늘 저녁 반찬은 뭐세요?”, “떡갈비세요.”","correct":true,"mis_target":"K3-2-u4-X09"},{"t":"지후: “오늘 저녁 반찬은 뭐예요?”, “떡갈비요.”","mis":"K3-2-u4-X08"},{"t":"나은: “엄마, 오늘 저녁 반찬은 뭐예요?”, “떡갈비 먹고 싶어요.”","mis":"K3-2-u4-X08"}],"explanation":["반찬과 떡갈비는 물건이라 높이지 않아요.","듣는 엄마를 높이려면 ‘요’를 붙여요.","“뭐세요?”, “떡갈비세요.”는 물건을 높인 말이에요."],"asset":{"type":"passage","lines":["“오늘 저녁 반찬은 뭐야?”","“아드님은 뭐가 드시고 싶으세요?”","“떡갈비.”"],"title":"「아드님, 진지 드세요」 장면 ㉯ — 『국어』 196쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#19','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C20',3,'mc','auto','『국어활동』 61쪽 ㉱ “할머니, 지금 통화 괜찮으세요?”에서 잘한 점을 두 가지 바르게 고른 것은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X25']::text[],false,'{"seq":19,"concept":"K3-2-u4-C20","difficulty":3,"kind":"mc","stem":"『국어활동』 61쪽 ㉱ “할머니, 지금 통화 괜찮으세요?”에서 잘한 점을 두 가지 바르게 고른 것은 무엇인가요?","options":[{"t":"상대가 통화하기 괜찮은 상황인지 확인함 · 높임 표현으로 할머니를 높임","correct":true},{"t":"자신이 누구인지 밝힘 · 끝인사를 함","mis":"K3-2-u4-X22"},{"t":"통화하기 괜찮은지 확인함 · 할 말부터 먼저 함","mis":"K3-2-u4-X25"},{"t":"높임 표현을 씀 · 공공장소에서 작게 말함","mis":"K3-2-u4-X22"}],"explanation":["“지금 통화 괜찮으세요?”는 상대의 상황을 묻는 말이에요.","‘괜찮으세요’에 ‘-시-’와 ‘요’를 써서 할머니를 높였어요.","전화 예절과 높임 표현을 함께 지켰어요."],"asset":{"type":"passage","lines":["㉰ 수찬: “여보세요?”","희지: “수찬아, 안녕? 나 희지야.”","㉱ 손녀: “할머니, 지금 통화 괜찮으세요?”","할머니: “응, 괜찮아. 그동안 잘 지냈니?”"],"title":"『국어활동』 61쪽 — 전화 대화에서 잘 지킨 예절"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#20','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C3',3,'ox','auto','나이가 더 많은 사람이 더 젊은 사람에게 높임 표현을 쓰는 것은 언제나 틀린 말이에요.',ARRAY['K3-2-u4-X02']::text[],false,'{"seq":20,"concept":"K3-2-u4-C3","difficulty":3,"kind":"ox","stem":"나이가 더 많은 사람이 더 젊은 사람에게 높임 표현을 쓰는 것은 언제나 틀린 말이에요.","answer":"X","reason_options":[{"t":"진헌이 할머니가 선생님께 높임 표현을 쓴 것처럼, 관계와 역할에 따라 나이와 관계없이 높임 표현을 써요.","correct":true},{"t":"높임 표현은 어린 사람이 나이 많은 사람에게만 쓰는 말이에요.","mis":"K3-2-u4-X02"}],"mis":"K3-2-u4-X02","explanation":["높임 표현은 나이표가 아니에요.","상대와의 관계와 역할, 존중하는 마음에 따라 쓰기도 해요.","처음 만난 어른끼리도 서로 높임 표현을 써요."],"asset":{"type":"passage","lines":["[그림] 학교 앞에서 할머니와 진헌이가 젊은 담임 선생님을 만남","진헌이 할머니 — “선생님, 안녕하세요? 제가 진헌이 할머니예요.”","진헌 — “선생님, 안녕하세요?”"],"title":"상황 ㉱ — 『국어』 182쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#21','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C14',3,'mc','auto','친구들과 대화할 때 줄임말이나 자기들만 아는 말을 쓰면 어떤 일이 생길 수 있나요?',ARRAY['K3-2-u4-X24','K3-2-u4-X18']::text[],false,'{"seq":21,"concept":"K3-2-u4-C14","difficulty":3,"kind":"mc","stem":"친구들과 대화할 때 줄임말이나 자기들만 아는 말을 쓰면 어떤 일이 생길 수 있나요?","options":[{"t":"그 말을 모르는 친구가 소외감을 느낄 수 있다","correct":true},{"t":"모두 더 빨리 친해진다","mis":"K3-2-u4-X24"},{"t":"대화가 짧아져서 모두 좋아한다","mis":"K3-2-u4-X24"},{"t":"아무 일도 생기지 않는다","mis":"K3-2-u4-X18"}],"explanation":["여럿이 함께 있을 때 일부만 아는 말을 쓰면 다른 친구는 대화에 끼지 못해요.","귓속말처럼 한 사람을 빼는 일이 될 수 있어요.","모두가 알아듣는 말로 대화해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#22','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C10',3,'mc','auto','뒷이야기를 상상해요. 약속을 한 다음 날 범수의 모습으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X12','K3-2-u4-X33']::text[],false,'{"seq":22,"concept":"K3-2-u4-C10","difficulty":3,"kind":"mc","stem":"뒷이야기를 상상해요. 약속을 한 다음 날 범수의 모습으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학교에 들어서자마자 선생님께 허리를 굽혀 “선생님, 안녕하세요?”라고 인사했다","correct":true},{"t":"친구들에게도 동생에게도 ‘님’을 붙여 높였다","mis":"K3-2-u4-X11"},{"t":"높임말이 틀릴까 봐 아무에게도 말을 걸지 않았다","mis":"K3-2-u4-X12"},{"t":"집에서는 다시 엄마에게 반말을 했다","mis":"K3-2-u4-X33"}],"explanation":["범수는 누구에게나 높임말을 잘 쓰겠다고 약속했어요.","서툴러도 웃어른께 높임말로 먼저 인사하는 모습이 어울려요.","말이 곱게 나가면 행동도 고와져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#23','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C9',4,'essay','teacher','지운이의 쪽지에서 잘못된 높임 표현을 세 군데 찾아 고쳐 쓰고, 그렇게 고친 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u4-C9","difficulty":4,"kind":"essay","stem":"지운이의 쪽지에서 잘못된 높임 표현을 세 군데 찾아 고쳐 쓰고, 그렇게 고친 까닭을 쓰세요.","answer_guide":{"answer":"① 인사하고 → 인사드리고: 인사를 받는 분이 할머니, 할아버지라서. ② 집 → 댁: 할머니, 할아버지의 집이라서. ③ 떡이세요 → 떡이에요: 떡은 물건이라 높이지 않아서.","scoring_points":["잘못된 높임 표현 세 군데를 찾았는가","세 군데를 바르게 고쳤는가","고친 까닭을 높임의 대상과 이어 썼는가"]},"explanation":["쪽지를 읽을 분은 할머니, 할아버지예요.","높임의 뜻이 있는 낱말(인사드리다·댁)을 써요.","물건에는 높임 표현을 쓰지 않아요."],"asset":{"type":"passage","lines":["할머니, 할아버지께","안녕하세요?","저는 옆집에 이사 온 김지운입니다.","직접 인사하고 싶었지만 집에 안 계셔서 이렇게 쪽지를 남겨요.","이건 저희 부모님께서 할머니, 할아버지께 드리는 떡이세요.","맛있게 잡수시면 좋겠어요.","안녕히 계세요.","김지운 올림"],"title":"지운이가 쓴 쪽지 — 『국어』 187쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#24','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C15',4,'essay','teacher','『국어』 207쪽 상황 ㉯의 대본을 이어 쓰세요. 어머니께서 “분리배출하는 것 좀 도와줄 수 있니?”라고 하셨을 때 거절하는 말과, 어머니께서 “그래? 아쉽지만 어쩔 수 없네.”라고 하신 뒤의 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u4-C15","difficulty":4,"kind":"essay","stem":"『국어』 207쪽 상황 ㉯의 대본을 이어 쓰세요. 어머니께서 “분리배출하는 것 좀 도와줄 수 있니?”라고 하셨을 때 거절하는 말과, 어머니께서 “그래? 아쉽지만 어쩔 수 없네.”라고 하신 뒤의 말을 쓰세요.","answer_guide":{"answer":"예: 나 — “어머니, 죄송해요. 지금 수학 학원 버스를 타러 나가야 해서 도와드릴 수가 없어요.” / 나 — “다녀와서 남은 것은 제가 정리할게요. 이해해 주셔서 감사해요.”","scoring_points":["높임 표현으로 공손하게 말했는가","죄송한 마음과 도와드릴 수 없는 까닭을 말했는가","거절당하는 어머니의 마음을 헤아리는 말을 덧붙였는가"]},"explanation":["어머니는 웃어른이시니 높임 표현을 써요.","거절할 때에는 죄송한 마음과 까닭을 말씀드려요.","할 수 있는 만큼 돕겠다는 말로 마음을 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_b#25','kor',3,2,'u4','','tb_g3_2_kor_u4_review_b','unit_review','K3-2-u4-C1',4,'essay','teacher','대화할 때 예절을 지켰거나 지키지 않았던 경험을 하나 떠올려 쓰고, 그때 지켜야 했던 대화 예절과 앞으로의 다짐을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u4-C1","difficulty":4,"kind":"essay","stem":"대화할 때 예절을 지켰거나 지키지 않았던 경험을 하나 떠올려 쓰고, 그때 지켜야 했던 대화 예절과 앞으로의 다짐을 쓰세요.","answer_guide":{"answer":"예: 도서관에서 친구와 큰 소리로 웃다가 다른 사람들이 쳐다본 적이 있다. 도서관 같은 공공장소에서는 조용히 대화해야 했다. 앞으로는 장소를 먼저 살피고 목소리를 알맞게 하겠다.","scoring_points":["대화 예절과 관련된 경험을 구체적으로 썼는가","그때 지켜야 했던 대화 예절을 썼는가","앞으로의 다짐을 썼는가"]},"explanation":["『국어』 179쪽 상황 ㉮(도서관), ㉯(전화)를 떠올려도 좋아요.","그때 상대나 둘레 사람의 기분을 생각해요.","배운 예절을 다짐으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#1','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C6',1,'ox','auto','스스로 확인하기 ③이에요. 「‘밥’, ‘생일’은 높임의 뜻이 있는 낱말이다.」는 알맞은 설명이에요.',ARRAY['K3-2-u4-X36']::text[],false,'{"seq":1,"concept":"K3-2-u4-C6","difficulty":1,"kind":"ox","stem":"스스로 확인하기 ③이에요. 「‘밥’, ‘생일’은 높임의 뜻이 있는 낱말이다.」는 알맞은 설명이에요.","answer":"X","reason_options":[{"t":"‘밥’, ‘생일’은 본래의 낱말이고, 높임의 뜻이 있는 낱말은 ‘진지’, ‘생신’이에요.","correct":true},{"t":"‘밥’과 ‘생일’이 웃어른께 쓰는 높임 낱말이에요.","mis":"K3-2-u4-X36"}],"mis":"K3-2-u4-X36","explanation":["높임의 뜻이 있는 낱말은 웃어른께 쓰는 쪽이에요.","밥-진지, 생일-생신이에요.","짝의 방향을 거꾸로 알지 않게 해요."],"asset":{"type":"passage","lines":["① 대화하는 상대가 웃어른일 때에는 ‘-시-’, ‘-습니다’와 같은 높임 표현을 사용한다.","② 언제 어디에서든 자신의 말이 잘 들릴 수 있도록 큰 소리로 대화한다.","③ ‘밥’, ‘생일’은 높임의 뜻이 있는 낱말이다.","④ 통화를 마칠 때에는 끝인사를 한다."],"title":"스스로 확인하기 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#2','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C6',1,'mc','auto','진우가 할아버지께 한 말 “할아버지, 생신 축하드려요!”에서 ‘생신’은 어떤 낱말을 높인 말인가요?',ARRAY['K3-2-u4-X07']::text[],false,'{"seq":2,"concept":"K3-2-u4-C6","difficulty":1,"kind":"mc","stem":"진우가 할아버지께 한 말 “할아버지, 생신 축하드려요!”에서 ‘생신’은 어떤 낱말을 높인 말인가요?","options":[{"t":"생일","correct":true},{"t":"선물","mis":"K3-2-u4-X07"},{"t":"축하","mis":"K3-2-u4-X07"},{"t":"잔치","mis":"K3-2-u4-X07"}],"explanation":["친구들은 진우에게 “생일 축하해!”라고 했어요.","진우는 할아버지께 ‘생일’ 대신 ‘생신’이라고 했어요.","‘생신’은 ‘생일’의 높임말이에요."],"asset":{"type":"speech","turns":[{"who":"㉮ 친구들 → 진우","text":"“진우야, 생일 축하해!”"},{"who":"㉯ 진우 → 할아버지","text":"“할아버지, 생신 축하드려요!”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#3','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C6',1,'blank','auto','할머니께 “안녕히 (     ).”라고 밤 인사를 드릴 때 빈칸에 알맞은 높임의 뜻이 있는 낱말은 무엇인가요?',ARRAY['K3-2-u4-X35','K3-2-u4-X10']::text[],false,'{"seq":3,"concept":"K3-2-u4-C6","difficulty":1,"kind":"blank","stem":"할머니께 “안녕히 (     ).”라고 밤 인사를 드릴 때 빈칸에 알맞은 높임의 뜻이 있는 낱말은 무엇인가요?","options":[{"t":"주무세요","correct":true},{"t":"자세요","mis":"K3-2-u4-X35"},{"t":"자요","mis":"K3-2-u4-X10"}],"explanation":["‘자다’의 높임말은 ‘주무시다’예요.","‘-시-’만 붙인 ‘자세요’는 높임 낱말을 쓴 것이 아니에요.","그래서 “안녕히 주무세요.”라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#4','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C7',1,'mc','auto','선생님께 인사할 때 듣는 선생님을 높이는 말로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X11']::text[],false,'{"seq":4,"concept":"K3-2-u4-C7","difficulty":1,"kind":"mc","stem":"선생님께 인사할 때 듣는 선생님을 높이는 말로 알맞은 것은 무엇인가요?","options":[{"t":"“선생님, 내일 뵙겠습니다.”","correct":true},{"t":"“선생님, 내일 보자.”","mis":"K3-2-u4-X10"},{"t":"“선생님, 내일 봐.”","mis":"K3-2-u4-X10"},{"t":"“선생님께서, 내일 보셔.”","mis":"K3-2-u4-X11"}],"explanation":["말을 듣는 사람은 선생님이에요.","말끝에 ‘-습니다’를 붙여 듣는 선생님을 높여요.","보는 사람은 나라서 ‘뵙다’를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#5','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C14',1,'sa','auto','소영이가 동호에게 부탁할 때 동호를 부른 말을 그대로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u4-C14","difficulty":1,"kind":"sa","stem":"소영이가 동호에게 부탁할 때 동호를 부른 말을 그대로 쓰세요.","answer":["동호야","동호야, 지금 바빠?"],"explanation":["소영이는 “동호야, 지금 바빠?”라고 했어요.","이름을 부르면 상대를 존중하는 마음이 드러나요.","효진이는 “야!”라고 불렀어요."],"asset":{"type":"speech","turns":[{"who":"소영","text":"“동호야, 지금 바빠? 이 책 좀 같이 들어 줄 수 있어?”"},{"who":"동호","text":"“응, 알았어. 그런데 나 지금 선생님 심부름 가는 길인데, 저기 계단까지만 들어 줘도 될까?”"},{"who":"소영","text":"“물론이지. 도와줘서 고마워.”"},{"who":"효진","text":"“왜 내 건 안 들어 주고 소영이 것만 들어 줘?”"},{"who":"동호","text":"“나는 네가 나한테 짜증만 내고 명령하듯이 말해서 들어 주고 싶지 않았어.”"}]},"mis":"K3-2-u4-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#6','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C17',1,'mc','auto','『국어활동』 60쪽 ㉯ 버스 안에서 (작은 목소리로) 형에게 말한 아이가 잘 지킨 대화 예절은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X24']::text[],false,'{"seq":6,"concept":"K3-2-u4-C17","difficulty":1,"kind":"mc","stem":"『국어활동』 60쪽 ㉯ 버스 안에서 (작은 목소리로) 형에게 말한 아이가 잘 지킨 대화 예절은 무엇인가요?","options":[{"t":"공공장소에서는 조용히 대화한다","correct":true},{"t":"대화하는 목적을 고려해 주제와 관련 있는 말을 한다","mis":"K3-2-u4-X22"},{"t":"웃어른과 대화할 때에는 공손한 태도로 말한다","mis":"K3-2-u4-X22"},{"t":"여럿이 있을 때 귓속말을 한다","mis":"K3-2-u4-X24"}],"explanation":["버스는 여러 사람이 함께 타는 공공장소예요.","작은 목소리로 말해 다른 사람에게 방해가 되지 않았어요.","장소에 맞게 목소리를 조절했어요."],"asset":{"type":"passage","lines":["㉮ 학급 회의 — 사회자: “친구들과 사이좋게 지내기 위해 노력할 점을 발표해 주십시오.”","발표자: “친구가 기분 나빠 하는 별명으로 부르지 말아야 합니다.”","㉯ 버스 안 — (작은 목소리로) “형, 우리 집에 가는 길에 과자 사서 먹자.”"],"title":"『국어활동』 60쪽 — 잘 지킨 대화 예절 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#7','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C18',1,'mc','auto','인영이의 전화 대화 ㉮에서 할머니께서 전화를 받으시자 인영이가 한 말은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X25']::text[],false,'{"seq":7,"concept":"K3-2-u4-C18","difficulty":1,"kind":"mc","stem":"인영이의 전화 대화 ㉮에서 할머니께서 전화를 받으시자 인영이가 한 말은 무엇인가요?","options":[{"t":"“할머니, 저 인영이예요.”","correct":true},{"t":"“여보세요? 누구세요?”","mis":"K3-2-u4-X22"},{"t":"“준비물이 뭐예요?”","mis":"K3-2-u4-X25"},{"t":"“안녕.”","mis":"K3-2-u4-X25"}],"explanation":["할머니께서 “여보세요?” 하고 전화를 받으셨어요.","인영이는 상대를 확인하고 자신을 밝혔어요.","전화에서는 얼굴이 보이지 않아 이렇게 말해요."],"asset":{"type":"passage","lines":["㉮ 할머니: “여보세요?”","인영: “할머니, 저 인영이예요.”","㉯ 인영: “지금 통화하기 괜찮아?”","친구: “저녁 식사 중이라 지금은 좀 어려워. 이따가 내가 다시 연락할게.”","㉰ 인영: “준비물 알려 줘서 고마워. 그럼 내일 보자. 안녕.”","친구: “응, 안녕.”"],"title":"인영이의 전화 대화 ㉮~㉰ — 『국어』 204쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#8','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C26',1,'mc','auto','『국어』 215쪽 글씨 쓰기 ‘배려’의 첫 글자에 쓰인 모음자는 무엇인가요?',ARRAY['K3-2-u4-X32']::text[],false,'{"seq":8,"concept":"K3-2-u4-C26","difficulty":1,"kind":"mc","stem":"『국어』 215쪽 글씨 쓰기 ‘배려’의 첫 글자에 쓰인 모음자는 무엇인가요?","options":[{"t":"ㅐ","correct":true},{"t":"ㅔ","mis":"K3-2-u4-X32"},{"t":"ㅒ","mis":"K3-2-u4-X32"},{"t":"ㅖ","mis":"K3-2-u4-X32"}],"explanation":["‘배’는 ㅂ과 ㅐ가 만난 글자예요.","ㅐ와 ㅔ는 가로획의 자리가 달라요.","‘샘물’의 ‘샘’에도 ㅐ가 쓰였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#9','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C5',2,'mc','auto','대화 ㉢에서 민수의 말 “그런데 할머니가 몇 시쯤 오세요?”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X10','K3-2-u4-X08']::text[],false,'{"seq":9,"concept":"K3-2-u4-C5","difficulty":2,"kind":"mc","stem":"대화 ㉢에서 민수의 말 “그런데 할머니가 몇 시쯤 오세요?”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“그런데 할머니께서 몇 시쯤 오세요?”","correct":true},{"t":"“그런데 할머니께 몇 시쯤 오세요?”","mis":"K3-2-u4-X06"},{"t":"“그런데 할머니가 몇 시쯤 와요?”","mis":"K3-2-u4-X10"},{"t":"“그런데 할머니께서 몇 시쯤 오니?”","mis":"K3-2-u4-X08"}],"explanation":["‘오세요’로 할머니를 높였어요.","그렇다면 ‘할머니가’도 ‘할머니께서’로 높여야 해요.","‘께’는 ‘에게’ 자리에 쓰는 말이에요."],"asset":{"type":"passage","lines":["㉠ 민수: 어머니, 오늘 할머니께서 우리 집에 오나요?","어머니: 맞아. 오늘 오실 거야.","㉡ 민수: 그럼 제가 데리러 갈게요.","어머니: 그래. 할머니께서 정말 좋아하시겠구나.","㉢ 민수: 그런데 할머니가 몇 시쯤 오세요?","어머니: 오후 세 시쯤 오실 거야.","㉣ 민수: 그럼 나갈 준비를 미리 할게.","어머니: 그렇게 하자."],"title":"높임 표현을 바르게 사용하기 — 대화 ㉠~㉣"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#10','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C6',2,'mc','auto','“할머니 지금 집에 있으시니?”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X35']::text[],false,'{"seq":10,"concept":"K3-2-u4-C6","difficulty":2,"kind":"mc","stem":"“할머니 지금 집에 있으시니?”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“할머니 지금 댁에 계시니?”","correct":true},{"t":"“할머니 지금 집에 있니?”","mis":"K3-2-u4-X10"},{"t":"“할머니 지금 집에 있으시니요?”","mis":"K3-2-u4-X35"},{"t":"“할머니 지금 댁에 있어?”","mis":"K3-2-u4-X35"}],"explanation":["‘있다’에는 높임의 뜻이 있는 낱말 ‘계시다’가 있어요.","‘-시-’만 붙인 ‘있으시다’보다 ‘계시다’를 써요.","할머니의 집은 ‘댁’이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#11','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C2',2,'mc','auto','엄마와 할머니께서 범수에게 일부러 높임말을 쓰신 까닭은 무엇일까요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":11,"concept":"K3-2-u4-C2","difficulty":2,"kind":"mc","stem":"엄마와 할머니께서 범수에게 일부러 높임말을 쓰신 까닭은 무엇일까요?","options":[{"t":"범수에게 높임 표현을 바르게 사용하는 것이 중요하다는 것을 가르치려고","correct":true},{"t":"범수를 왕자처럼 키우려고","mis":"K3-2-u4-X33"},{"t":"엄마가 반말을 쓰는 법을 잊어버려서","mis":"K3-2-u4-X33"},{"t":"범수를 놀리려고","mis":"K3-2-u4-X33"}],"explanation":["할머니는 “우리 범수가 이참에 단단히 배우겠구먼.”이라고 했어요.","엄마와 할머니는 범수를 가르치려고, 범수는 배우는 거예요.","‘가르치다’와 ‘배우다’를 떠올리면 이야기의 주제가 보여요."],"asset":{"type":"passage","lines":["범수는 식탁에서 벌떡 일어났어요.","범수는 반말을 고치고 싶은 마음이 전혀 없었어요.","“우리 범수가 이참에 단단히 배우겠구먼.”"],"title":"「아드님, 진지 드세요」 낱말 알기 — 『국어』 195쪽","hi":["식탁","고치고","배우겠구먼"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#12','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C15',2,'ox','auto','친구의 부탁을 들어줄 수 없을 때에는 까닭은 말하지 말고 “안 돼.”라고만 짧게 말하는 것이 좋아요.',ARRAY['K3-2-u4-X19']::text[],false,'{"seq":12,"concept":"K3-2-u4-C15","difficulty":2,"kind":"ox","stem":"친구의 부탁을 들어줄 수 없을 때에는 까닭은 말하지 말고 “안 돼.”라고만 짧게 말하는 것이 좋아요.","answer":"X","reason_options":[{"t":"거절할 때에는 미안한 마음을 표현하고 도와줄 수 없는 까닭을 자세히 말해요.","correct":true},{"t":"거절할 때 까닭을 말하면 핑계처럼 들려요.","mis":"K3-2-u4-X19"}],"mis":"K3-2-u4-X19","explanation":["“안 돼.”라고만 하면 친구는 내가 자기를 싫어한다고 오해할 수 있어요.","“미안해. 나 지금 ……라서 안 될 것 같아.”처럼 말해요.","거절당하는 사람의 마음을 헤아려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#13','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C18',2,'mc','auto','3모둠은 「인영이의 전화 대화」로 토의했어요. 통화를 마칠 때의 예절로 정한 말은 무엇인가요?',ARRAY['K3-2-u4-X25','K3-2-u4-X17','K3-2-u4-X21']::text[],false,'{"seq":13,"concept":"K3-2-u4-C18","difficulty":2,"kind":"mc","stem":"3모둠은 「인영이의 전화 대화」로 토의했어요. 통화를 마칠 때의 예절로 정한 말은 무엇인가요?","options":[{"t":"통화를 마칠 때에는 “이만 끊겠습니다.”처럼 끝인사를 한다","correct":true},{"t":"내 할 말만 하고 바로 끊는다","mis":"K3-2-u4-X25"},{"t":"상대가 먼저 끊을 때까지 아무 말도 하지 않는다","mis":"K3-2-u4-X17"},{"t":"통화를 마칠 때에는 더 크게 말한다","mis":"K3-2-u4-X21"}],"explanation":["전화로는 대화가 끝났는지 눈으로 알 수 없어요.","“이만 끊겠습니다.”, “안녕.”처럼 끝인사를 해요.","끝인사를 하면 상대도 편하게 전화를 끊어요."],"asset":{"type":"passage","lines":["㉮ 할머니: “여보세요?”","인영: “할머니, 저 인영이예요.”","㉯ 인영: “지금 통화하기 괜찮아?”","친구: “저녁 식사 중이라 지금은 좀 어려워. 이따가 내가 다시 연락할게.”","㉰ 인영: “준비물 알려 줘서 고마워. 그럼 내일 보자. 안녕.”","친구: “응, 안녕.”"],"title":"인영이의 전화 대화 ㉮~㉰ — 『국어』 204쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#14','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C21',2,'mc','auto','같은 “고맙습니다.”라도 듣는 사람이 가장 기분 좋게 느낄 말하기는 무엇인가요?',ARRAY['K3-2-u4-X27']::text[],false,'{"seq":14,"concept":"K3-2-u4-C21","difficulty":2,"kind":"mc","stem":"같은 “고맙습니다.”라도 듣는 사람이 가장 기분 좋게 느낄 말하기는 무엇인가요?","options":[{"t":"상대를 바라보며 웃는 얼굴로 밝은 말투로 말한다","correct":true},{"t":"딴 곳을 보며 작게 중얼거린다","mis":"K3-2-u4-X27"},{"t":"화난 목소리로 빠르게 말한다","mis":"K3-2-u4-X27"},{"t":"말투는 상관없이 “고맙습니다.”라는 말만 하면 된다","mis":"K3-2-u4-X27"}],"explanation":["같은 말이라도 표정, 몸짓, 말투에 따라 듣는 이의 기분이 달라져요.","고마운 마음은 웃는 얼굴과 밝은 말투에 잘 드러나요.","말투도 말의 한 부분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#15','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C12',2,'mc','auto','한 낱말이 다른 낱말의 뜻을 포함하는 관계로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":15,"concept":"K3-2-u4-C12","difficulty":2,"kind":"mc","stem":"한 낱말이 다른 낱말의 뜻을 포함하는 관계로 알맞은 것은 무엇인가요?","options":[{"t":"꽃 — 장미","correct":true},{"t":"크다 — 작다","mis":"K3-2-u4-X15"},{"t":"기쁘다 — 즐겁다","mis":"K3-2-u4-X15"},{"t":"가르치다 — 배우다","mis":"K3-2-u4-X15"}],"explanation":["장미는 꽃 가운데 하나예요.","‘꽃’이 ‘장미’의 뜻을 포함해요.","‘식탁 — 가구’도 같은 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#16','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C23',2,'mc','auto','김수빈의 실천 다짐판 「친구의 말을 끝까지 귀담아듣겠습니다.」를 잘 실천한 모습은 무엇인가요?',ARRAY['K3-2-u4-X26','K3-2-u4-X27','K3-2-u4-X28']::text[],false,'{"seq":16,"concept":"K3-2-u4-C23","difficulty":2,"kind":"mc","stem":"김수빈의 실천 다짐판 「친구의 말을 끝까지 귀담아듣겠습니다.」를 잘 실천한 모습은 무엇인가요?","options":[{"t":"모둠 활동에서 친구가 말을 마칠 때까지 기다렸다가 내 생각을 말했다","correct":true},{"t":"친구가 말할 때 중간에 끼어들어 내 생각을 먼저 말했다","mis":"K3-2-u4-X26"},{"t":"친구가 말할 때 다른 곳을 보며 딴생각을 했다","mis":"K3-2-u4-X27"},{"t":"붙임딱지만 날마다 붙였다","mis":"K3-2-u4-X28"}],"explanation":["귀담아듣는 것은 끝까지 주의 깊게 듣는 거예요.","친구의 말이 끝날 때까지 기다리며 들어요.","실천한 대로 붙임딱지를 솔직하게 붙여요."],"asset":{"type":"passage","lines":["실천 다짐판 (오유찬) — 친구의 말을 존중하고 고운 말을 사용하겠습니다.","실천 다짐판 (김수빈) — 친구의 말을 끝까지 귀담아듣겠습니다.","[다짐판 아래] 목·금·토·일 칸에 붙임딱지 — 잘했을 때 · 보통일 때 · 노력이 필요할 때"],"title":"대화 예절을 실천하는 다짐판 — 『국어』 211쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#17','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C6',3,'mc','auto','아버지의 말 “할아버지께 미리 연락을 드렸대.”에서 ‘께’와 ‘드렸대’로 높인 사람은 누구인가요?',ARRAY['K3-2-u4-X05','K3-2-u4-X08','K3-2-u4-X11']::text[],false,'{"seq":17,"concept":"K3-2-u4-C6","difficulty":3,"kind":"mc","stem":"아버지의 말 “할아버지께 미리 연락을 드렸대.”에서 ‘께’와 ‘드렸대’로 높인 사람은 누구인가요?","options":[{"t":"연락을 받으신 할아버지","correct":true},{"t":"연락을 한 누나","mis":"K3-2-u4-X05"},{"t":"말을 듣는 민수","mis":"K3-2-u4-X08"},{"t":"말하는 아버지","mis":"K3-2-u4-X11"}],"explanation":["연락을 드린 사람은 누나, 받으신 분은 할아버지예요.","‘에게’ 대신 ‘께’, ‘주다’ 대신 ‘드리다’를 써서 할아버지를 높였어요.","아버지는 민수에게 말하니 말끝은 높이지 않았어요."],"asset":{"type":"speech","turns":[{"who":"민수","text":"“아버지, 오늘 할아버지께서 오시는 날이지요? 누가 모시러 가요?”"},{"who":"아버지","text":"“응, 누나가 이미 출발했어. 할아버지께 미리 연락을 드렸대.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#18','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C9',3,'error','auto','세 친구가 불퉁이의 말 “할머니, 생일 축하해. 올해 나이가 몇 살이야?”를 고쳤어요. 잘못 고친 친구는 누구인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X07']::text[],false,'{"seq":18,"concept":"K3-2-u4-C9","difficulty":3,"kind":"error","stem":"세 친구가 불퉁이의 말 “할머니, 생일 축하해. 올해 나이가 몇 살이야?”를 고쳤어요. 잘못 고친 친구는 누구인가요?","options":[{"t":"도담: “할머니, 생신 축하해. 올해 연세가 몇 살이야?”","correct":true,"mis_target":"K3-2-u4-X10"},{"t":"시온: “할머니, 생신 축하드려요. 올해 연세가 어떻게 되세요?”","mis":"K3-2-u4-X07"},{"t":"예준: “할머니, 생신 축하드려요. 연세가 어떻게 되시는지 여쭈어봐도 돼요?”","mis":"K3-2-u4-X07"}],"explanation":["‘생신’, ‘연세’로 바꾸어도 말끝을 낮추면 할머니를 높이지 못해요.","‘축하해’는 ‘축하드려요’로, ‘몇 살이야?’는 ‘어떻게 되세요?’로 바꾸어요.","낱말과 말끝을 함께 살펴요."],"asset":{"type":"passage","lines":["불퉁: “할머니, 생일 축하해. 올해 나이가 몇 살이야?”","엄마: “불퉁아, 할머니께 반말하면 못써.”","불퉁: “알았어. 아빠 안 먹어? 나 먼저 먹는다?”","아빠: “안 되겠다. 지금 당장 배워야지!”"],"title":"「서로서로 통하는 말」 만화 가운데 (박은정 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#19','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C22',3,'mc','auto','대화 예절을 잘 지키며 대화했는지 스스로 확인할 내용으로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u4-X28','K3-2-u4-X27']::text[],false,'{"seq":19,"concept":"K3-2-u4-C22","difficulty":3,"kind":"mc","stem":"대화 예절을 잘 지키며 대화했는지 스스로 확인할 내용으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"대본을 가장 길게 썼나요?","correct":true},{"t":"대화하는 상대에 따라 알맞은 높임 표현과 태도로 대화했나요?","mis":"K3-2-u4-X28"},{"t":"대화 목적에 알맞은 대화 예절을 지키며 대화했나요?","mis":"K3-2-u4-X28"},{"t":"상황에 어울리는 표정, 몸짓, 말투로 대화했나요?","mis":"K3-2-u4-X27"}],"explanation":["스스로 확인하기는 상대·목적·표정 몸짓 말투를 살펴요.","대본의 길이는 대화 예절과 상관이 없어요.","확인하는 까닭은 다음에 고칠 점을 찾기 위해서예요."],"asset":{"type":"passage","lines":["1. 대화 계획 — 대화를 나누는 사람 · 대화 방식 · 대화 목적 · 대화 주제","2. 계획을 바탕으로 대화 예절을 지키며 대화하기","3. 스스로 확인하기","· 대화하는 상대에 따라 알맞은 높임 표현과 태도로 대화했나요?","· 대화 목적에 알맞은 대화 예절을 지키며 대화했나요?","· 상황에 어울리는 표정, 몸짓, 말투로 대화했나요?"],"title":"대화 예절을 지키며 대화하기 — 평가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#20','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C3',3,'mc','auto','「이럴 땐 어떻게 말할까?」의 꼼마가 처음에 높임말을 잘못 쓴 까닭과 고칠 점을 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X03','K3-2-u4-X12']::text[],false,'{"seq":20,"concept":"K3-2-u4-C3","difficulty":3,"kind":"mc","stem":"「이럴 땐 어떻게 말할까?」의 꼼마가 처음에 높임말을 잘못 쓴 까닭과 고칠 점을 바르게 말한 것은 무엇인가요?","options":[{"t":"높임말과 예사말을 몰라 거꾸로 썼다 — 선생님께는 높임말, 친구들에게는 예사말을 쓴다","correct":true},{"t":"높임말을 너무 많이 썼다 — 누구에게도 높임말을 쓰지 않는다","mis":"K3-2-u4-X10"},{"t":"친구들에게 높임말을 썼다 — 친구들에게는 언제 어디서나 높임말을 쓴다","mis":"K3-2-u4-X03"},{"t":"선생님께 예사말을 썼다 — 선생님께는 말을 걸지 않는다","mis":"K3-2-u4-X12"}],"explanation":["꼼마는 친구들에게는 높임말을, 선생님에게는 예사말을 썼어요.","대화하는 상대에 따라 높임말과 예사말을 가려 써야 해요.","틀릴까 봐 말을 걸지 않는 것보다 바르게 배워 쓰는 것이 좋아요."],"asset":{"type":"passage","lines":["(간추림) 새로운 늑대 이야기를 쓰려고 학교에 간 꼬마 늑대 꼼마는","처음에 높임말과 예사말을 몰라서","친구들에게는 높임말을 쓰고 선생님에게는 예사말을 했다.","(간추림) 꼼마는 말과 글을 차근차근 배워 간다."],"title":"「이럴 땐 어떻게 말할까?」(김은의 글) — 『국어활동』 62~71쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#21','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C14',3,'mc','auto','『국어활동』 60쪽 ㉮에서 발표한 친구는 “친구가 기분 나빠 하는 별명으로 부르지 말아야 합니다.”라고 했어요. 이 의견이 대화 예절과 관련된 까닭은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X21','K3-2-u4-X02']::text[],false,'{"seq":21,"concept":"K3-2-u4-C14","difficulty":3,"kind":"mc","stem":"『국어활동』 60쪽 ㉮에서 발표한 친구는 “친구가 기분 나빠 하는 별명으로 부르지 말아야 합니다.”라고 했어요. 이 의견이 대화 예절과 관련된 까닭은 무엇인가요?","options":[{"t":"듣기 싫어하는 별명은 상대를 존중하지 않는 부르는 말이기 때문","correct":true},{"t":"별명은 길어서 부르기 힘들기 때문","mis":"K3-2-u4-X18"},{"t":"별명을 부르면 목소리가 커지기 때문","mis":"K3-2-u4-X21"},{"t":"별명은 웃어른께만 쓰는 말이기 때문","mis":"K3-2-u4-X02"}],"explanation":["부르는 말에도 상대를 존중하는 마음이 드러나요.","상대가 기분 나빠 하는 호칭으로 부르면 안 돼요.","친구의 이름을 불러 주면 존중받는 느낌이 들어요."],"asset":{"type":"passage","lines":["㉮ 학급 회의 — 사회자: “친구들과 사이좋게 지내기 위해 노력할 점을 발표해 주십시오.”","발표자: “친구가 기분 나빠 하는 별명으로 부르지 말아야 합니다.”","㉯ 버스 안 — (작은 목소리로) “형, 우리 집에 가는 길에 과자 사서 먹자.”"],"title":"『국어활동』 60쪽 — 잘 지킨 대화 예절 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#22','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C2',3,'mc','auto','범수가 아침에 “엄마, 이게 뭐야? 누가 아침부터 이렇게 밥을 많이 먹어?”라고 말했을 때 부모님의 마음은 어땠을까요?',ARRAY['K3-2-u4-X33','K3-2-u4-X27']::text[],false,'{"seq":22,"concept":"K3-2-u4-C2","difficulty":3,"kind":"mc","stem":"범수가 아침에 “엄마, 이게 뭐야? 누가 아침부터 이렇게 밥을 많이 먹어?”라고 말했을 때 부모님의 마음은 어땠을까요?","options":[{"t":"반말과 짜증 섞인 말을 들어 속상하고 존중받지 못한다고 느꼈을 것이다","correct":true},{"t":"범수가 솔직하게 말해서 기뻤을 것이다","mis":"K3-2-u4-X33"},{"t":"밥을 많이 차려서 미안했을 것이다","mis":"K3-2-u4-X33"},{"t":"아무렇지 않았을 것이다","mis":"K3-2-u4-X27"}],"explanation":["아빠와 엄마는 동시에 범수를 노려보았어요.","반말과 짜증 섞인 말은 듣는 사람의 마음을 상하게 해요.","높임 표현을 듣는 상대의 마음을 짐작해 보아요."],"asset":{"type":"passage","lines":["(간추림) 엄마가 깨우자 범수는 이불을 뒤집어쓰고 돌아누웠다.","“밥 안 먹어. 더 잘 거야.”","(간추림) 수북이 쌓인 밥을 보니 범수는 다시 짜증이 확 났다.","“엄마, 이게 뭐야? 누가 아침부터 이렇게 밥을 많이 먹어?”","(간추림) 아빠와 엄마가 동시에 범수를 노려보았다."],"title":"「아드님, 진지 드세요」 아침 장면 — 『국어』 188쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#23','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C9',4,'essay','teacher','스승의 날 일기에서 높임 표현을 적절하게 사용하지 못한 부분을 세 군데 찾아 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u4-C9","difficulty":4,"kind":"essay","stem":"스승의 날 일기에서 높임 표현을 적절하게 사용하지 못한 부분을 세 군데 찾아 바르게 고쳐 쓰세요.","answer_guide":{"answer":"① 오라고 했다 → 오라고 하셨다 ② 작년 담임 선생님에게 편지를 주고 → 작년 담임 선생님께 편지를 드리고 ③ 선생님이 기뻐하는 → 선생님께서 기뻐하시는","scoring_points":["잘못된 부분 세 군데를 찾았는가","‘께’·‘께서’·‘드리다’·‘-시-’를 알맞게 써서 고쳤는가","높여야 할 선생님을 바르게 판단했는가"]},"explanation":["일기에 나오는 두 선생님을 모두 높여야 해요.","‘에게’는 ‘께’, ‘주다’는 ‘드리다’로 바꾸어요.","선생님이 하신 일에는 ‘-시-’를 넣어요."],"asset":{"type":"passage","lines":["5월 15일 ○요일 날씨: 맑음","오늘은 스승의 날을 맞이해 작년 담임 선생님께 편지를 썼다.","편지를 다 쓰고 선생님께서 작년 담임 선생님께 편지를 주고 오라고 했다.","나랑 현승이는 작년에 같은 반이었기 때문에","함께 작년 담임 선생님에게 편지를 주고 왔다.","선생님이 기뻐하는 모습을 보니 뿌듯한 마음이 들었다."],"title":"어느 날의 일기 — 높임 표현을 살펴보아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#24','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C18',4,'essay','teacher','상황 ㉮ 역할놀이 대본의 빈칸 ‘나’의 말을 처음부터 끝까지 채워 쓰세요. 전화 대화의 예절이 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u4-C18","difficulty":4,"kind":"essay","stem":"상황 ㉮ 역할놀이 대본의 빈칸 ‘나’의 말을 처음부터 끝까지 채워 쓰세요. 전화 대화의 예절이 드러나게 쓰세요.","answer_guide":{"answer":"예: 나 — “나 ○○야. 지금 통화 괜찮아?” / 나 — “우리 내일 만나기로 했잖아. 언제 어디에서 볼까?” / 나 — “응, 좋아. 2시에 놀이터에서 보자.” / 나 — “알았어. 그럼 내일 보자. 안녕.”","scoring_points":["자신이 누구인지 밝히고 통화가 괜찮은지 물었는가","대화 목적(만날 약속)에 맞게 의견을 나누었는가","친구의 상황을 헤아리며 끝인사를 했는가"]},"explanation":["친구가 “(  )(이)구나.”라고 하려면 먼저 내가 누구인지 밝혀야 해요.","약속 시간과 장소를 친구와 함께 정해요.","마지막에는 끝인사를 하고 끊어요."],"asset":{"type":"passage","lines":["친구: 여보세요?","나: (            )","친구: (     )(이)구나. 무슨 일이야?","나: (            )","친구: 그럼 2시에 놀이터에서 볼까? 괜찮아?","나: (            )","친구: 나도 좋아. 난 동생이 불러서 가 봐야 할 것 같아. 내일 놀이터에서 보자.","나: (            )"],"title":"역할놀이 대본 쓰기 — 상황 ㉮"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_c#25','kor',3,2,'u4','','tb_g3_2_kor_u4_review_c','unit_review','K3-2-u4-C13',4,'essay','teacher','「이럴 땐 어떻게 말할까?」의 꼼마에게 더 알려 주고 싶은 대화 예절을 한 가지 쓰고, 그 예절을 지켜야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u4-C13","difficulty":4,"kind":"essay","stem":"「이럴 땐 어떻게 말할까?」의 꼼마에게 더 알려 주고 싶은 대화 예절을 한 가지 쓰고, 그 예절을 지켜야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 친구에게 부탁할 때에는 친구가 들어줄 수 있는 상황인지 먼저 묻고, 부탁을 들어주면 고맙다고 말해야 해. 그래야 친구가 존중받는다고 느끼고 서로 좋은 관계를 이어 갈 수 있어.","scoring_points":["꼼마에게 알려 줄 대화 예절을 한 가지 골랐는가","그 예절을 지키는 방법을 구체적으로 썼는가","지켜야 하는 까닭을 상대의 마음이나 관계와 이어 썼는가"]},"explanation":["꼼마는 학교에서 말과 글을 처음 배우고 있어요.","이 단원에서 배운 부탁·거절·전화·모둠 대화 예절을 떠올려요.","까닭은 듣는 사람의 마음과 이어 써요."],"asset":{"type":"passage","lines":["(간추림) 새로운 늑대 이야기를 쓰려고 학교에 간 꼬마 늑대 꼼마는","처음에 높임말과 예사말을 몰라서","친구들에게는 높임말을 쓰고 선생님에게는 예사말을 했다.","(간추림) 꼼마는 말과 글을 차근차근 배워 간다."],"title":"「이럴 땐 어떻게 말할까?」(김은의 글) — 『국어활동』 62~71쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#1','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C18',1,'ox','auto','스스로 확인하기 ④예요. 「통화를 마칠 때에는 끝인사를 한다.」는 알맞은 설명이에요.',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":1,"concept":"K3-2-u4-C18","difficulty":1,"kind":"ox","stem":"스스로 확인하기 ④예요. 「통화를 마칠 때에는 끝인사를 한다.」는 알맞은 설명이에요.","answer":"O","reason_options":[{"t":"통화를 마칠 때에는 “안녕.”, “이만 끊을게.”처럼 끝인사를 해요.","correct":true},{"t":"할 말을 다 했으면 끝인사 없이 끊어도 돼요.","mis":"K3-2-u4-X25"}],"mis":"K3-2-u4-X25","explanation":["전화는 얼굴이 보이지 않아 언제 끝났는지 알기 어려워요.","끝인사를 하면 상대도 통화가 끝난 것을 알아요.","인영이도 “그럼 내일 보자. 안녕.”이라고 했어요."],"asset":{"type":"passage","lines":["① 대화하는 상대가 웃어른일 때에는 ‘-시-’, ‘-습니다’와 같은 높임 표현을 사용한다.","② 언제 어디에서든 자신의 말이 잘 들릴 수 있도록 큰 소리로 대화한다.","③ ‘밥’, ‘생일’은 높임의 뜻이 있는 낱말이다.","④ 통화를 마칠 때에는 끝인사를 한다."],"title":"스스로 확인하기 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#2','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C6',1,'sa','auto','‘집’을 높여 이르는 높임의 뜻이 있는 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u4-C6","difficulty":1,"kind":"sa","stem":"‘집’을 높여 이르는 높임의 뜻이 있는 낱말을 쓰세요.","answer":["댁"],"explanation":["지운이의 쪽지에서 고친 낱말이에요.","웃어른의 집은 ‘댁’이라고 해요.","“할머니 댁에 가요.”처럼 써요."],"mis":"K3-2-u4-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#3','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C6',1,'mc','auto','‘보다’를 높여 이르는 낱말로, “선생님을 (     ) 반가웠어요.”의 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X08','K3-2-u4-X07']::text[],false,'{"seq":3,"concept":"K3-2-u4-C6","difficulty":1,"kind":"mc","stem":"‘보다’를 높여 이르는 낱말로, “선생님을 (     ) 반가웠어요.”의 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"뵈어서","correct":true},{"t":"보셔서","mis":"K3-2-u4-X11"},{"t":"봐서요","mis":"K3-2-u4-X08"},{"t":"여쭈어서","mis":"K3-2-u4-X07"}],"explanation":["선생님을 보는 사람은 나예요.","내가 웃어른을 볼 때는 ‘뵙다·뵈다’를 써요.","‘보셔서’는 나를 높인 말이라 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#4','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C7',1,'mc','auto','“어머니, 학교 다녀오겠습니다.”에서 ‘-습니다’로 높인 사람은 누구인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X05','K3-2-u4-X09']::text[],false,'{"seq":4,"concept":"K3-2-u4-C7","difficulty":1,"kind":"mc","stem":"“어머니, 학교 다녀오겠습니다.”에서 ‘-습니다’로 높인 사람은 누구인가요?","options":[{"t":"말을 듣는 어머니","correct":true},{"t":"학교에 가는 나","mis":"K3-2-u4-X11"},{"t":"학교 선생님","mis":"K3-2-u4-X05"},{"t":"학교","mis":"K3-2-u4-X09"}],"explanation":["‘-습니다’는 말끝에 붙어 듣는 사람을 높여요.","이 말을 듣는 사람은 어머니예요.","학교에 가는 사람은 나라서 ‘-시-’는 쓰지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#5','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C13',1,'mc','auto','『국어』 200쪽 정리 「대화 예절은 말하는 이와 듣는 이가 서로 말을 주고받을 때 지켜야 할 예절을 뜻해요.」 다음에 이어지는 말은 무엇인가요?',ARRAY['K3-2-u4-X17','K3-2-u4-X16','K3-2-u4-X21']::text[],false,'{"seq":5,"concept":"K3-2-u4-C13","difficulty":1,"kind":"mc","stem":"『국어』 200쪽 정리 「대화 예절은 말하는 이와 듣는 이가 서로 말을 주고받을 때 지켜야 할 예절을 뜻해요.」 다음에 이어지는 말은 무엇인가요?","options":[{"t":"대화할 때 상대를 배려하고 존중하려는 마음가짐이 중요해요.","correct":true},{"t":"대화할 때는 말을 많이 할수록 좋아요.","mis":"K3-2-u4-X17"},{"t":"대화할 때는 상대의 부탁을 모두 들어주어야 해요.","mis":"K3-2-u4-X16"},{"t":"대화할 때는 큰 소리로 말해야 해요.","mis":"K3-2-u4-X21"}],"explanation":["대화 예절의 뜻 다음에 마음가짐을 말했어요.","상대를 배려하고 존중하려는 마음가짐이에요.","이 마음이 부르는 말, 말투, 표정에 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#6','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C16',1,'mc','auto','「태수의 대화」 ㉯에서 태수가 대화하는 상대와 목적을 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X24']::text[],false,'{"seq":6,"concept":"K3-2-u4-C16","difficulty":1,"kind":"mc","stem":"「태수의 대화」 ㉯에서 태수가 대화하는 상대와 목적을 바르게 말한 것은 무엇인가요?","options":[{"t":"모둠 친구들과 조사할 공공 기관을 정하려고","correct":true},{"t":"할아버지께 가위의 위치를 알려 드리려고","mis":"K3-2-u4-X22"},{"t":"친구들과 무슨 놀이를 할지 고르려고","mis":"K3-2-u4-X22"},{"t":"급식 메뉴를 알아보려고","mis":"K3-2-u4-X24"}],"explanation":["혜진이는 “우리 모둠은 공공 기관 가운데에서 어디를 조사해 볼까?”라고 했어요.","대화 ㉯는 수업 중 모둠 활동이에요.","목적을 생각하면 주제와 관련한 말을 하게 돼요."],"asset":{"type":"speech","turns":[{"who":"혜진","text":"“우리 모둠은 공공 기관 가운데에서 어디를 조사해 볼까?”"},{"who":"태수","text":"“혜진아, 그런데 오늘 급식 메뉴가 뭐지? 배고프다.”"},{"who":"혜진","text":"“지금 모둠 활동 중이잖아.”"},{"who":"태수","text":"“아, 미안. 이제 대화에 집중할게.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#7','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C18',1,'sa','auto','전화를 받을 때나 걸었을 때 상대를 부르며 처음에 자주 쓰는 말을 쓰세요. (네 글자)','{}'::text[],false,'{"seq":7,"concept":"K3-2-u4-C18","difficulty":1,"kind":"sa","stem":"전화를 받을 때나 걸었을 때 상대를 부르며 처음에 자주 쓰는 말을 쓰세요. (네 글자)","answer":["여보세요"],"explanation":["『국어』 204쪽에서 전화 대화에 자주 쓰는 말을 이야기했어요.","전화를 받을 때 “여보세요?”라고 해요.","끊을 때에는 “이만 끊을게.”처럼 끝인사를 해요."],"mis":"K3-2-u4-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#8','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C25',1,'ox','auto','같은 물건을 지역마다 ‘가우, 가새, 가시개’처럼 다르게 부르는 말은 모두 틀린 말이라서 쓰면 안 돼요.',ARRAY['K3-2-u4-X31']::text[],false,'{"seq":8,"concept":"K3-2-u4-C25","difficulty":1,"kind":"ox","stem":"같은 물건을 지역마다 ‘가우, 가새, 가시개’처럼 다르게 부르는 말은 모두 틀린 말이라서 쓰면 안 돼요.","answer":"X","reason_options":[{"t":"방언은 어느 한 지역에서만 쓰는, 표준어가 아닌 말일 뿐 틀린 말이 아니에요.","correct":true},{"t":"표준어 ‘가위’ 말고는 모두 잘못 배운 말이에요.","mis":"K3-2-u4-X31"}],"mis":"K3-2-u4-X31","explanation":["방언이란 어느 한 지역에서만 쓰는 말이에요.","다른 것은 틀린 것이 아니에요.","방언에는 그 지역의 말맛이 담겨 있어요."],"asset":{"type":"passage","lines":["방언: 가우, 가새, 가시개  →  표준어: (     )","방언: 개구락지, 까구리, 깨구리  →  표준어: (     )","방언이란 어느 한 지역에서만 쓰는, 표준어가 아닌 말을 뜻해요."],"title":"기초 다지기 2 — 『국어』 214쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#9','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C7',2,'mc','auto','대화 ㉣에서 민수의 말 “그럼 나갈 준비를 미리 할게.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X40','K3-2-u4-X11','K3-2-u4-X06']::text[],false,'{"seq":9,"concept":"K3-2-u4-C7","difficulty":2,"kind":"mc","stem":"대화 ㉣에서 민수의 말 “그럼 나갈 준비를 미리 할게.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“그럼 나갈 준비를 미리 할게요.”","correct":true},{"t":"“그럼 나갈 준비를 미리 하실게요.”","mis":"K3-2-u4-X40"},{"t":"“그럼 나가실 준비를 미리 하셔.”","mis":"K3-2-u4-X11"},{"t":"“그럼 나갈 준비를 미리 할게, 어머니께서.”","mis":"K3-2-u4-X06"}],"explanation":["민수는 어머니께 말하고 있어요.","듣는 어머니를 높이려면 말끝에 ‘요’를 붙여요.","준비하는 사람은 민수라서 ‘-시-’를 넣지 않아요."],"asset":{"type":"passage","lines":["㉠ 민수: 어머니, 오늘 할머니께서 우리 집에 오나요?","어머니: 맞아. 오늘 오실 거야.","㉡ 민수: 그럼 제가 데리러 갈게요.","어머니: 그래. 할머니께서 정말 좋아하시겠구나.","㉢ 민수: 그런데 할머니가 몇 시쯤 오세요?","어머니: 오후 세 시쯤 오실 거야.","㉣ 민수: 그럼 나갈 준비를 미리 할게.","어머니: 그렇게 하자."],"title":"높임 표현을 바르게 사용하기 — 대화 ㉠~㉣"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#10','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C9',2,'mc','auto','종수가 윤아 어머니께 한 말 “윤아 어머니, 한번 먹어 볼래요?”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X35','K3-2-u4-X06','K3-2-u4-X10']::text[],false,'{"seq":10,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"종수가 윤아 어머니께 한 말 “윤아 어머니, 한번 먹어 볼래요?”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“윤아 어머니, 한번 드셔 보시겠어요?”","correct":true},{"t":"“윤아 어머니, 한번 먹으셔 볼래요?”","mis":"K3-2-u4-X35"},{"t":"“윤아 어머니께, 한번 먹어 볼래요?”","mis":"K3-2-u4-X06"},{"t":"“윤아 어머니, 한번 먹어 봐.”","mis":"K3-2-u4-X10"}],"explanation":["떡을 먹을 분은 윤아 어머니예요.","‘먹다’ 대신 높임의 뜻이 있는 ‘드시다’를 써요.","“드셔 보시겠어요?”처럼 공손하게 여쭈어요."],"asset":{"type":"speech","turns":[{"who":"상황","text":"종수가 길을 걸어가다가 윤아와 윤아 어머니를 만났어요."},{"who":"종수","text":"“윤아야, 안녕? 윤아 어머니, 안녕하세요?”"},{"who":"윤아","text":"“종수야, 안녕? 너 손에 들고 있는 건 뭐니?”"},{"who":"종수","text":"“아, 이건 떡이야. 윤아 어머니, 한번 먹어 볼래요?”"},{"who":"윤아 어머니","text":"“종수야, 고맙구나. 누가 만든 거니?”"},{"who":"종수","text":"“우리 엄마가 만들었어요.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#11','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C2',2,'mc','auto','이야기 끝에서 엄마가 해 주는 ‘아들’이란 말이 범수에게 달콤하게 들린 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X33','K3-2-u4-X10']::text[],false,'{"seq":11,"concept":"K3-2-u4-C2","difficulty":2,"kind":"mc","stem":"이야기 끝에서 엄마가 해 주는 ‘아들’이란 말이 범수에게 달콤하게 들린 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"엄마가 다시 편하게 대해 주고, 자신도 높임말을 바르게 쓰기로 마음먹었기 때문","correct":true},{"t":"엄마가 처음으로 범수를 불러 주었기 때문","mis":"K3-2-u4-X33"},{"t":"엄마가 계속 높임말을 써 주기로 했기 때문","mis":"K3-2-u4-X33"},{"t":"범수가 다시 반말을 해도 되었기 때문","mis":"K3-2-u4-X10"}],"explanation":["범수는 누구에게나 높임말을 잘 쓰겠다고 약속했어요.","엄마도 범수에게 다시 편하게 말하기로 했어요.","반말이 푹신한 솜이불처럼 편안하게 느껴졌어요."],"asset":{"type":"passage","lines":["“그럼 약속하세요. 이제부터 누구에게나 높임말을 잘 쓰겠다고요.”","“약속할게……요. 앞으로 높임말 잘 쓸게……요.”","(간추림) 엄마가 해 주는 ‘아들’이란 말이 달콤하게 들렸고,","(간추림) 엄마가 해 주는 반말이 푹신한 솜이불처럼 편안했다."],"title":"「아드님, 진지 드세요」 마지막 장면 — 『국어』 194쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#12','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C15',2,'mc','auto','할머니께서 화분 옮기는 일을 도와 달라고 하셨는데, 지금은 숙제를 내러 나가야 해요. 알맞지 않은 대답은 무엇인가요?',ARRAY['K3-2-u4-X20']::text[],false,'{"seq":12,"concept":"K3-2-u4-C15","difficulty":2,"kind":"mc","stem":"할머니께서 화분 옮기는 일을 도와 달라고 하셨는데, 지금은 숙제를 내러 나가야 해요. 알맞지 않은 대답은 무엇인가요?","options":[{"t":"“네, 지금 할게요.” (하고는 그냥 나간다)","correct":true},{"t":"“할머니, 죄송해요. 지금 숙제를 내러 가야 해서요. 다녀와서 도와드릴게요.”","mis":"K3-2-u4-X20"},{"t":"“할머니, 지금은 어려워요. 숙제를 내고 와서 꼭 도와드릴게요.”","mis":"K3-2-u4-X20"}],"explanation":["하겠다고 대답하고 하지 않으면 할머니께서 더 속상하세요.","들어드릴 수 없을 때에는 솔직하게 까닭을 말씀드려요.","할 수 있는 때를 함께 말씀드리면 더 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#13','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C19',2,'ox','auto','모둠 활동에서 친구가 의견을 말하는 중이라도 좋은 생각이 떠오르면 바로 끼어들어 말해도 돼요.',ARRAY['K3-2-u4-X26']::text[],false,'{"seq":13,"concept":"K3-2-u4-C19","difficulty":2,"kind":"ox","stem":"모둠 활동에서 친구가 의견을 말하는 중이라도 좋은 생각이 떠오르면 바로 끼어들어 말해도 돼요.","answer":"X","reason_options":[{"t":"다른 사람의 말을 중간에 끊지 않고 끝까지 귀 기울여 들은 뒤에 내 생각을 말해요.","correct":true},{"t":"좋은 생각은 잊어버리기 전에 끼어들어서라도 바로 말해야 해요.","mis":"K3-2-u4-X26"}],"mis":"K3-2-u4-X26","explanation":["모둠 대화는 함께 답을 찾는 것이에요.","친구의 말을 끊고 내 생각만 말하면 친구가 속상해요.","끝까지 듣고 나서 내 생각을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#14','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C21',2,'mc','auto','전화로 대화할 때 표정과 몸짓 대신 잘 듣고 있다는 것을 알리는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u4-X27','K3-2-u4-X21']::text[],false,'{"seq":14,"concept":"K3-2-u4-C21","difficulty":2,"kind":"mc","stem":"전화로 대화할 때 표정과 몸짓 대신 잘 듣고 있다는 것을 알리는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"텔레비전을 보면서 대답을 하지 않는다","correct":true},{"t":"다른 일을 하지 않고 통화에 집중한다","mis":"K3-2-u4-X27"},{"t":"“응.”, “그렇구나.” 하고 한 번씩 호응한다","mis":"K3-2-u4-X27"},{"t":"평소보다 또박또박 말한다","mis":"K3-2-u4-X21"}],"explanation":["전화는 서로를 볼 수 없는 대화예요.","그래서 통화에 집중하고 짧은 말로 호응해요.","다른 일을 하면 상대는 내가 듣지 않는다고 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#15','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C12',2,'mc','auto','「범수는 식탁에서 벌떡 일어났어요.」의 ‘식탁’과 ‘가구’는 어떤 관계인가요?',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":15,"concept":"K3-2-u4-C12","difficulty":2,"kind":"mc","stem":"「범수는 식탁에서 벌떡 일어났어요.」의 ‘식탁’과 ‘가구’는 어떤 관계인가요?","options":[{"t":"한 낱말이 다른 낱말의 뜻을 포함하는 관계","correct":true},{"t":"서로 뜻이 비슷한 관계","mis":"K3-2-u4-X15"},{"t":"서로 뜻이 반대인 관계","mis":"K3-2-u4-X15"}],"explanation":["식탁은 가구의 한 가지예요.","‘가구’ 안에 식탁, 의자, 옷장 들이 들어가요.","그래서 포함하는 관계예요."],"asset":{"type":"passage","lines":["범수는 식탁에서 벌떡 일어났어요.","범수는 반말을 고치고 싶은 마음이 전혀 없었어요.","“우리 범수가 이참에 단단히 배우겠구먼.”"],"title":"「아드님, 진지 드세요」 낱말 알기 — 『국어』 195쪽","hi":["식탁","고치고","배우겠구먼"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#16','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C24',2,'mc','auto','『국어』에 나온 두 활동 말고도 우리 반에서 할 수 있는 실천 활동으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X30']::text[],false,'{"seq":16,"concept":"K3-2-u4-C24","difficulty":2,"kind":"mc","stem":"『국어』에 나온 두 활동 말고도 우리 반에서 할 수 있는 실천 활동으로 알맞은 것은 무엇인가요?","options":[{"t":"높임 표현을 생각하며 이야기 바꾸어 쓰기","correct":true},{"t":"가장 빨리 끝나는 퍼즐 맞추기","mis":"K3-2-u4-X30"},{"t":"가장 재미있는 만화 영화 보기","mis":"K3-2-u4-X30"},{"t":"줄넘기 오래 하기 시합","mis":"K3-2-u4-X30"}],"explanation":["실천 활동은 높임 표현과 대화 예절을 익히는 활동이어야 해요.","이야기 바꾸어 쓰기, 공익 광고 감상하기도 할 수 있어요.","재미나 빠르기보다 배운 것을 써 보는지가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#17','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C4',3,'mc','auto','대화 ㉡에서 어머니의 말 “할머니께서 정말 좋아하시겠구나.”로 높인 사람은 누구인가요?',ARRAY['K3-2-u4-X08','K3-2-u4-X11','K3-2-u4-X05']::text[],false,'{"seq":17,"concept":"K3-2-u4-C4","difficulty":3,"kind":"mc","stem":"대화 ㉡에서 어머니의 말 “할머니께서 정말 좋아하시겠구나.”로 높인 사람은 누구인가요?","options":[{"t":"좋아하실 할머니","correct":true},{"t":"말을 듣는 민수","mis":"K3-2-u4-X08"},{"t":"말하는 어머니","mis":"K3-2-u4-X11"},{"t":"데리러 갈 민수","mis":"K3-2-u4-X05"}],"explanation":["좋아하실 분은 할머니예요.","‘께서’와 ‘좋아하시겠구나’의 ‘-시-’로 할머니를 높였어요.","어머니는 민수에게 말하니 말끝은 낮추었어요."],"asset":{"type":"passage","lines":["㉠ 민수: 어머니, 오늘 할머니께서 우리 집에 오나요?","어머니: 맞아. 오늘 오실 거야.","㉡ 민수: 그럼 제가 데리러 갈게요.","어머니: 그래. 할머니께서 정말 좋아하시겠구나.","㉢ 민수: 그런데 할머니가 몇 시쯤 오세요?","어머니: 오후 세 시쯤 오실 거야.","㉣ 민수: 그럼 나갈 준비를 미리 할게.","어머니: 그렇게 하자."],"title":"높임 표현을 바르게 사용하기 — 대화 ㉠~㉣"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#18','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C11',3,'error','auto','세 친구가 “효빈아, 선생님이 너 오래.”를 고쳤어요. 잘못 고친 친구는 누구인가요?',ARRAY['K3-2-u4-X14','K3-2-u4-X11']::text[],false,'{"seq":18,"concept":"K3-2-u4-C11","difficulty":3,"kind":"error","stem":"세 친구가 “효빈아, 선생님이 너 오래.”를 고쳤어요. 잘못 고친 친구는 누구인가요?","options":[{"t":"라희: “효빈아, 선생님께서 너 오시래.”","correct":true,"mis_target":"K3-2-u4-X14"},{"t":"준우: “효빈아, 선생님께서 너 오라고 하셔.”","mis":"K3-2-u4-X11"},{"t":"채아: “효빈아, 선생님께서 교실로 오라고 하셨어.”","mis":"K3-2-u4-X11"}],"explanation":["오는 사람은 효빈이라서 ‘오시래’라고 하면 효빈이를 높이게 돼요.","말씀하신 분은 선생님이니 ‘하셔’, ‘하셨어’로 높여요.","말을 옮길 때도 누가 한 말인지 살펴요."],"asset":{"type":"speech","turns":[{"who":"① 선생님 → 지호","text":"“지호야, 효빈이 좀 교실에 들어오라고 해 줘.”"},{"who":"지호","text":"“네.”"},{"who":"② 지호 → 효빈","text":"“효빈아, 선생님이 너 오래.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#19','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C20',3,'mc','auto','『국어』 206쪽 상황 ㉮와 상황 ㉯를 견주었어요. 두 상황의 다른 점을 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u4-X22']::text[],false,'{"seq":19,"concept":"K3-2-u4-C20","difficulty":3,"kind":"mc","stem":"『국어』 206쪽 상황 ㉮와 상황 ㉯를 견주었어요. 두 상황의 다른 점을 바르게 말한 것은 무엇인가요?","options":[{"t":"대화 상대, 대화 목적, 대화 방식이 모두 다르다","correct":true},{"t":"대화 상대만 다르고 목적과 방식은 같다","mis":"K3-2-u4-X22"},{"t":"대화 방식만 다르고 상대와 목적은 같다","mis":"K3-2-u4-X22"},{"t":"두 상황은 다른 점이 없다","mis":"K3-2-u4-X22"}],"explanation":["㉮는 친구, ㉯는 어머니와 대화해요.","㉮는 약속을 하려고, ㉯는 부탁을 거절하려고 대화해요.","㉮는 전화, ㉯는 직접 만나서 대화해요."],"asset":{"type":"passage","lines":["상황 ㉮ — 친구와 언제 어디에서 만날지 전화로 약속을 정하는 상황","상황 ㉯ — 어머니께서 분리배출을 도와 달라고 하시는데","도와드릴 수 없는 상황"],"title":"『국어』 206쪽 대화 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#20','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C3',3,'ox','auto','학급 회의 때 성준이에게 높임 표현을 썼으니 회의가 끝난 쉬는 시간에도 성준이에게 계속 높임 표현을 써야 해요.',ARRAY['K3-2-u4-X03']::text[],false,'{"seq":20,"concept":"K3-2-u4-C3","difficulty":3,"kind":"ox","stem":"학급 회의 때 성준이에게 높임 표현을 썼으니 회의가 끝난 쉬는 시간에도 성준이에게 계속 높임 표현을 써야 해요.","answer":"X","reason_options":[{"t":"회의처럼 공식적인 상황이 끝나면 친구 사이에서는 평소처럼 말해도 돼요.","correct":true},{"t":"한 번 높인 친구에게는 언제 어디서나 높임 표현을 써야 해요.","mis":"K3-2-u4-X03"}],"mis":"K3-2-u4-X03","explanation":["쉬는 시간에 성준이와 반말로 이야기한 장면이 있어요.","높임 표현은 상황에 따라 달라져요.","공식적인 상황에서 높이고, 편한 자리에서는 평소처럼 말해요."],"asset":{"type":"passage","lines":["쉬는 시간 — “성준아, 회의 주제에 대한 의견 정했어?”","“응, 실천 방법을 제안해 보려고.”","학급 회의 — “박성준 학생, 회의 주제에 대한 의견을 말해 주십시오.”","“네, 제가 발표하겠습니다.”"],"title":"상황 ㉯ — 『국어』 181쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#21','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C14',3,'mc','auto','효진이와 소영이의 부탁을 견주었어요. 바르게 정리한 것은 무엇인가요?',ARRAY['K3-2-u4-X18']::text[],false,'{"seq":21,"concept":"K3-2-u4-C14","difficulty":3,"kind":"mc","stem":"효진이와 소영이의 부탁을 견주었어요. 바르게 정리한 것은 무엇인가요?","options":[{"t":"부르는 말 — “야!” / “동호야.” · 부탁하는 말 — “빨리 좀 들어 봐!” / “들어 줄 수 있어?”","correct":true},{"t":"부르는 말 — “동호야.” / “야!” · 부탁하는 말 — “들어 줄 수 있어?” / “빨리 좀 들어 봐!”","mis":"K3-2-u4-X18"},{"t":"부르는 말 — 둘 다 “동호야.” · 부탁하는 말 — 둘 다 “들어 줄 수 있어?”","mis":"K3-2-u4-X18"},{"t":"부르는 말과 부탁하는 말은 같고 책의 양만 달랐다","mis":"K3-2-u4-X18"}],"explanation":["효진이는 “야!”라고 부르고 “빨리 좀 들어 봐!”라고 시켰어요.","소영이는 “동호야.”라고 부르고 “들어 줄 수 있어?”라고 물었어요.","부르는 말과 부탁하는 말에 예절이 드러나요."],"asset":{"type":"speech","turns":[{"who":"소영","text":"“동호야, 지금 바빠? 이 책 좀 같이 들어 줄 수 있어?”"},{"who":"동호","text":"“응, 알았어. 그런데 나 지금 선생님 심부름 가는 길인데, 저기 계단까지만 들어 줘도 될까?”"},{"who":"소영","text":"“물론이지. 도와줘서 고마워.”"},{"who":"효진","text":"“왜 내 건 안 들어 주고 소영이 것만 들어 줘?”"},{"who":"동호","text":"“나는 네가 나한테 짜증만 내고 명령하듯이 말해서 들어 주고 싶지 않았어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#22','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C2',3,'mc','auto','마트에서 엄마가 모르는 할머니께 허리를 굽혀 사과하는 모습을 본 범수의 마음으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":22,"concept":"K3-2-u4-C2","difficulty":3,"kind":"mc","stem":"마트에서 엄마가 모르는 할머니께 허리를 굽혀 사과하는 모습을 본 범수의 마음으로 알맞은 것은 무엇인가요?","options":[{"t":"엄마가 자기 때문에 혼나는 것 같아 속상하고 불편했다","correct":true},{"t":"엄마가 혼나서 고소했다","mis":"K3-2-u4-X33"},{"t":"할머니께 칭찬받아 뿌듯했다","mis":"K3-2-u4-X33"},{"t":"아무 생각이 없었다","mis":"K3-2-u4-X33"}],"explanation":["할머니는 아들의 반말을 보고 호통을 쳤어요.","엄마는 할머니께 죄송하다고 싹싹 빌었어요.","범수는 군것질할 마음이 싹 사라질 만큼 기분이 상했어요."],"asset":{"type":"passage","lines":["(간추림) 마트에서 처음 보는 머리 하얀 할머니가 혀를 차며 호통을 쳤다.","(간추림) 엄마는 아들에게 높임말을 하는데 아들은 반말을 한다는 것이었다.","(간추림) 범수는 모르는 할머니께 사과하는 엄마가 못마땅해 물었다.","“모르는 분이더라도 어르신이 말씀하시니 귀 기울여 들어야지요.”"],"title":"「아드님, 진지 드세요」 마트 장면 — 『국어』 191~192쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#23','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C7',4,'essay','teacher','『국어활동』 59쪽처럼 웃어른께 감사의 마음을 전하는 짧은 편지를 쓰세요. 높임 표현을 세 가지 방법 이상 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u4-C7","difficulty":4,"kind":"essay","stem":"『국어활동』 59쪽처럼 웃어른께 감사의 마음을 전하는 짧은 편지를 쓰세요. 높임 표현을 세 가지 방법 이상 쓰세요.","answer_guide":{"answer":"예: 조리사님께 / 조리사님, 안녕하세요? 저는 3학년 ○반 △△△입니다. 더운 조리실에서 매일 저희 급식을 만들어 주셔서 감사드립니다. 늘 건강하세요. / △△△ 올림","scoring_points":["편지를 받을 웃어른과 전하고 싶은 마음이 드러나는가","‘-시-’·‘께’·‘-습니다/요’·높임 낱말 가운데 세 가지 이상을 썼는가","편지의 짜임(받는 사람·인사·전할 말·끝인사·쓴 사람)을 갖추었는가"]},"explanation":["편지를 받을 분과 전하고 싶은 마음을 먼저 정해요.","‘께’, ‘-시-’, ‘-습니다’, ‘드리다’ 같은 높임 표현을 써요.","쓴 다음 친구와 바꾸어 읽으며 누구를 높였는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#24','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C22',4,'essay','teacher','역할놀이를 한 뒤 점검표의 세 가지(대화 상대·대화 목적·대화 방식)로 자신의 대화를 점검하고, 가장 부족했던 점과 고칠 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u4-C22","difficulty":4,"kind":"essay","stem":"역할놀이를 한 뒤 점검표의 세 가지(대화 상대·대화 목적·대화 방식)로 자신의 대화를 점검하고, 가장 부족했던 점과 고칠 방법을 쓰세요.","answer_guide":{"answer":"예: 대화 상대 ●●● — 어머니께 높임 표현을 잘 썼다. 대화 목적 ●● — 거절하는 까닭을 짧게만 말했다. 대화 방식 ●●● — 어머니를 바라보며 말했다. 가장 부족한 점은 까닭을 자세히 말하지 못한 것이라 다음에는 왜 도와드릴 수 없는지 자세히 말씀드리겠다.","scoring_points":["세 가지 확인 내용으로 자신의 대화를 점검했는가","가장 부족했던 점을 솔직하게 찾았는가","부족한 점을 고칠 방법을 구체적으로 썼는가"]},"explanation":["점검은 점수를 높이려는 것이 아니에요.","부족한 부분을 찾아 고치려고 하는 거예요.","고칠 방법을 구체적으로 정하면 다음 대화가 더 좋아져요."],"asset":{"type":"passage","lines":["대화 상대에 알맞은 대화 예절을 지켰나요?   나 ○○○ · 짝 ○○○","대화 목적에 알맞은 대화 예절을 지켰나요?   나 ○○○ · 짝 ○○○","대화 방식에 알맞은 대화 예절을 지켰나요?   나 ○○○ · 짝 ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"역할놀이 점검표 — 『국어』 209쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u4_review_d#25','kor',3,2,'u4','','tb_g3_2_kor_u4_review_d','unit_review','K3-2-u4-C13',4,'essay','teacher','높임 표현과 대화 예절에 공통으로 담겨 있는 마음은 무엇인지 쓰고, 이 단원에서 배운 예를 하나씩 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u4-C13","difficulty":4,"kind":"essay","stem":"높임 표현과 대화 예절에 공통으로 담겨 있는 마음은 무엇인지 쓰고, 이 단원에서 배운 예를 하나씩 들어 설명하세요.","answer_guide":{"answer":"예: 둘 다 상대를 존중하고 배려하는 마음이 담겨 있다. 높임 표현의 예 — 진우가 할아버지께 “생신 축하드려요!”라고 한 것. 대화 예절의 예 — 소영이가 “동호야, 지금 바빠?” 하고 상대의 상황을 먼저 물은 것.","scoring_points":["공통으로 담긴 마음(존중·배려)을 썼는가","높임 표현의 예를 이 단원에서 들었는가","대화 예절의 예를 이 단원에서 들었는가"]},"explanation":["높임 표현에는 존중과 공경의 마음이 담겨 있어요.","대화 예절의 첫출발도 상대를 존중하고 배려하는 마음이에요.","두 가지를 함께 지키면 서로 좋은 관계를 이어 갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
